#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ActorKind {
    Human,
    LocalAi,
    RemoteAi,
}

impl ActorKind {
    pub const fn code(self) -> i32 {
        match self {
            Self::Human => 1,
            Self::LocalAi => 2,
            Self::RemoteAi => 3,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Human => "human",
            Self::LocalAi => "local_ai",
            Self::RemoteAi => "remote_ai",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ActorKindError {
    pub code: i32,
}

impl TryFrom<i32> for ActorKind {
    type Error = ActorKindError;

    fn try_from(code: i32) -> Result<Self, Self::Error> {
        match code {
            1 => Ok(Self::Human),
            2 => Ok(Self::LocalAi),
            3 => Ok(Self::RemoteAi),
            _ => Err(ActorKindError { code }),
        }
    }
}

