#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EnvelopeFacts {
    pub version: i32,
    pub suite_id: i32,
    pub conversation_id_len: i32,
    pub sender_account_id_len: i32,
    pub sender_device_id_len: i32,
    pub epoch: i32,
    pub sequence: i32,
    pub message_kind: i32,
    pub payload_len: i32,
    pub critical_flags: i32,
    pub noncritical_flags: i32,
    pub expected_epoch: i32,
    pub expected_sequence: i32,
    pub min_suite_id: i32,
    pub max_payload_len: i32,
}

impl From<EnvelopeFacts> for policy::EnvelopeInput {
    fn from(facts: EnvelopeFacts) -> Self {
        Self {
            version: facts.version,
            suite_id: facts.suite_id,
            conversation_id_len: facts.conversation_id_len,
            sender_account_id_len: facts.sender_account_id_len,
            sender_device_id_len: facts.sender_device_id_len,
            epoch: facts.epoch,
            sequence: facts.sequence,
            message_kind: facts.message_kind,
            payload_len: facts.payload_len,
            critical_flags: facts.critical_flags,
            noncritical_flags: facts.noncritical_flags,
            expected_epoch: facts.expected_epoch,
            expected_sequence: facts.expected_sequence,
            min_suite_id: facts.min_suite_id,
            max_payload_len: facts.max_payload_len,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
