#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AiParticipantAction {
    ReadSelectedContext,
    DraftReply,
    SendMessageWithConfirmation,
    AutonomousSend,
    UseReadOnlyLocalTool,
    UseRoomSearchSelectedTool,
    UseOpenWorldExternalTool,
    StorePrompt,
    TrainOnContext,
    WriteMemory,
}

impl AiParticipantAction {
    pub const fn access_kind(self) -> AccessKind {
        match self {
            Self::SendMessageWithConfirmation | Self::AutonomousSend => AccessKind::Write,
            Self::ReadSelectedContext
            | Self::DraftReply
            | Self::UseReadOnlyLocalTool
            | Self::UseRoomSearchSelectedTool
            | Self::UseOpenWorldExternalTool
            | Self::StorePrompt
            | Self::TrainOnContext
            | Self::WriteMemory => AccessKind::Read,
        }
    }

    pub const fn requires_selected_context(self) -> bool {
        match self {
            Self::ReadSelectedContext
            | Self::DraftReply
            | Self::UseReadOnlyLocalTool
            | Self::UseRoomSearchSelectedTool
            | Self::UseOpenWorldExternalTool
            | Self::StorePrompt
            | Self::TrainOnContext
            | Self::WriteMemory => true,
            Self::SendMessageWithConfirmation | Self::AutonomousSend => false,
        }
    }
}

