#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupChatInput {
    pub protocol: GroupChatProtocol,
    pub crypto_suite: GroupChatCryptoSuite,
    pub room_mode: RoomMode,
    pub member_count: i32,
    pub active_member_devices: i32,
    pub local_device_is_member: bool,
    pub room_state_available: bool,
    pub group_secret_sealed: bool,
    pub membership_transition_pending: bool,
    pub current_epoch: i32,
    pub local_epoch: i32,
    pub key_transparency_ready: bool,
    pub mls_provider_configured: bool,
    pub mls_provider_security: MlsProviderSecurityDecision,
    pub plaintext_member_metadata_fields: i32,
}

impl GroupChatInput {
    pub fn evaluate(self) -> GroupChatDecision {
        evaluate_group_chat(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupChatDecision {
    pub accepted: bool,
    pub protocol: GroupChatProtocol,
    pub crypto_suite: GroupChatCryptoSuite,
    pub can_open_group: bool,
    pub can_send_message: bool,
    pub can_change_membership: bool,
    pub requires_sync: bool,
    pub requires_mls_setup: bool,
    pub requires_pq_upgrade: bool,
    pub requires_user_action: bool,
    pub forbids_server_plaintext: bool,
    pub plaintext_bytes_exposed: bool,
    pub reason: GroupChatReason,
}

impl GroupChatDecision {
    pub const fn reason_code(self) -> i32 {
        self.reason.code()
    }

    pub const fn reason_label(self) -> &'static str {
        self.reason.label()
    }
}

pub fn evaluate_group_chat(input: GroupChatInput) -> GroupChatDecision {
    if input.member_count < 3 {
        return group_chat_reject(
            input,
            GroupChatReason::NotEnoughMembers,
            false,
            false,
            false,
            true,
        );
    }

    if input.member_count > MERCURY_MAX_GROUP_CHAT_MEMBERS {
        return group_chat_reject(
            input,
            GroupChatReason::MemberLimitExceeded,
            false,
            false,
            false,
            true,
        );
    }

    if !input.local_device_is_member {
        return group_chat_reject(
            input,
            GroupChatReason::LocalDeviceNotMember,
            false,
            false,
            false,
            true,
        );
    }

    if input.active_member_devices < input.member_count {
        return group_chat_reject(
            input,
            GroupChatReason::ActiveMemberDeviceMissing,
            false,
            false,
            false,
            true,
        );
    }

    if !input.room_state_available {
        return group_chat_reject(
            input,
            GroupChatReason::RoomStateMissing,
            true,
            false,
            false,
            false,
        );
    }

    if !input.group_secret_sealed {
        return group_chat_reject(
            input,
            GroupChatReason::GroupSecretMissing,
            true,
            false,
            false,
            false,
        );
    }

    if input.membership_transition_pending {
        return group_chat_reject(
            input,
            GroupChatReason::MembershipTransitionPending,
            true,
            false,
            false,
            true,
        );
    }

    if input.current_epoch <= 0
        || input.local_epoch <= 0
        || input.current_epoch != input.local_epoch
    {
        return group_chat_reject(
            input,
            GroupChatReason::EpochNotCurrent,
            true,
            false,
            false,
            false,
        );
    }

    if input.plaintext_member_metadata_fields != 0 {
        return group_chat_reject(
            input,
            GroupChatReason::PlaintextMetadataForbidden,
            false,
            false,
            false,
            false,
        );
    }

    if !input.key_transparency_ready {
        return group_chat_reject(
            input,
            GroupChatReason::KeyTransparencyNotReady,
            true,
            false,
            false,
            false,
        );
    }

    if input.room_mode == RoomMode::HighSecurity && input.protocol != GroupChatProtocol::Mls {
        return group_chat_reject(
            input,
            GroupChatReason::HighSecurityRequiresMls,
            false,
            true,
            false,
            true,
        );
    }

    if input.room_mode == RoomMode::HighSecurity && !input.crypto_suite.is_high_security_pq() {
        return group_chat_reject(
            input,
            GroupChatReason::HighSecurityRequiresPqHybridSuite,
            false,
            true,
            true,
            true,
        );
    }

    if input.protocol == GroupChatProtocol::Mls && !input.mls_provider_configured {
        return group_chat_reject(
            input,
            GroupChatReason::MlsProviderMissing,
            false,
            true,
            false,
            false,
        );
    }

    if input.protocol == GroupChatProtocol::Mls
        && (!input.mls_provider_security.accepted
            || input.mls_provider_security.suite != input.crypto_suite)
    {
        return group_chat_reject(
            input,
            GroupChatReason::MlsProviderSecurityRejected,
            false,
            true,
            input.mls_provider_security.requires_pq_upgrade
                || input.mls_provider_security.suite != input.crypto_suite,
            input.mls_provider_security.requires_user_action
                || input.mls_provider_security.suite != input.crypto_suite,
        );
    }

    GroupChatDecision {
        accepted: true,
        protocol: input.protocol,
        crypto_suite: input.crypto_suite,
        can_open_group: true,
        can_send_message: true,
        can_change_membership: true,
        requires_sync: false,
        requires_mls_setup: false,
        requires_pq_upgrade: false,
        requires_user_action: false,
        forbids_server_plaintext: true,
        plaintext_bytes_exposed: false,
        reason: GroupChatReason::Accepted,
    }
}

const fn group_chat_reject(
    input: GroupChatInput,
    reason: GroupChatReason,
    requires_sync: bool,
    requires_mls_setup: bool,
    requires_pq_upgrade: bool,
    requires_user_action: bool,
) -> GroupChatDecision {
    GroupChatDecision {
        accepted: false,
        protocol: input.protocol,
        crypto_suite: input.crypto_suite,
        can_open_group: false,
        can_send_message: false,
        can_change_membership: false,
        requires_sync,
        requires_mls_setup,
        requires_pq_upgrade,
        requires_user_action,
        forbids_server_plaintext: true,
        plaintext_bytes_exposed: false,
        reason,
    }
}

