pub struct MlsWelcomeSendOutboxDecision {
    pub accepted: bool,
    pub reason: MlsWelcomeSendOutboxReason,
    pub persisted_record: bool,
    pub record_count: usize,
    pub can_enqueue_welcome_once: bool,
    pub can_send_welcome_after_commit: bool,
    pub consumes_key_package: bool,
    pub binds_welcome_send_transaction: bool,
    pub binds_commit: bool,
    pub binds_delivery_route: bool,
    pub prevents_duplicate_outbox: bool,
    pub keeps_digest_only: bool,
    pub plaintext_bytes_exposed: bool,
}

pub struct AcceptedMlsWelcomeSendOutboxWrite<'a> {
    write: MlsWelcomeSendOutboxWrite<'a>,
    decision: MlsWelcomeSendOutboxDecision,
}

impl<'a> AcceptedMlsWelcomeSendOutboxWrite<'a> {
    pub const fn write(&self) -> MlsWelcomeSendOutboxWrite<'a> {
        self.write
    }

    pub const fn decision(&self) -> &MlsWelcomeSendOutboxDecision {
        &self.decision
    }
}

pub trait MlsWelcomeSendOutboxAdapter {
    type Error;

    fn put_accepted_mls_welcome_send_outbox(
        &mut self,
        write: AcceptedMlsWelcomeSendOutboxWrite<'_>,
    ) -> Result<(), Self::Error>;

    fn read_mls_welcome_send_outbox_by_transaction(
        &self,
        welcome_send_transaction_digest: &[u8],
    ) -> Result<Option<MlsWelcomeSendOutboxRecord>, Self::Error>;

    fn read_mls_welcome_send_outbox_by_key_package(
        &self,
        key_package_hash: &[u8],
    ) -> Result<Option<MlsWelcomeSendOutboxRecord>, Self::Error>;

    fn mls_welcome_send_outbox_record_count(&self) -> Result<usize, Self::Error>;
}

pub fn evaluate_mls_welcome_send_outbox_write(
    write: MlsWelcomeSendOutboxWrite<'_>,
) -> MlsWelcomeSendOutboxDecision {
    if !write.key_package_consumption.accepted
        || !write.key_package_consumption.can_send_welcome_once
        || !write.key_package_consumption.binds_welcome_send_transaction
        || !write.key_package_consumption.prevents_key_package_reuse
    {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::KeyPackageConsumeStoreRejected,
            0,
            false,
        );
    }

    if !write.commit_admission.accepted
        || !write.commit_admission.can_apply_commit
        || !write.commit_admission.can_initialize_epoch
        || !write.commit_admission.can_continue_group
        || !write.commit_admission.prevents_commit_replay
    {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::CommitAdmissionRejected,
            0,
            false,
        );
    }

    if write.group_id.len() != 32 {
        return mls_welcome_send_outbox_reject(MlsWelcomeSendOutboxReason::BadGroupId, 0, false);
    }

    if write.key_package_hash.len() != 32 {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::BadKeyPackageHash,
            0,
            false,
        );
    }

    if write.added_member_ref.len() != 32 {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::BadAddedMemberRef,
            0,
            false,
        );
    }

    if write.welcome_send_transaction_digest.len() != 32 {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::BadWelcomeSendTransactionDigest,
            0,
            false,
        );
    }

    if write.commit_hash.len() != 32 {
        return mls_welcome_send_outbox_reject(MlsWelcomeSendOutboxReason::BadCommitHash, 0, false);
    }

    if write.welcome_ciphertext_hash.len() != 32 {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::BadWelcomeCiphertextHash,
            0,
            false,
        );
    }

    if write.delivery_route_id.len() != 32 {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::BadDeliveryRouteId,
            0,
            false,
        );
    }

    if write.replay_token.len() != 32 {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::BadReplayToken,
            0,
            false,
        );
    }

    if write.created_at_s < 0 {
        return mls_welcome_send_outbox_reject(MlsWelcomeSendOutboxReason::BadCreatedAt, 0, false);
    }

    if write.expires_at_s <= write.created_at_s {
        return mls_welcome_send_outbox_reject(MlsWelcomeSendOutboxReason::BadExpiresAt, 0, false);
    }

    if write.plaintext_metadata_fields != 0 {
        return mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::PlaintextMetadataForbidden,
            0,
            true,
        );
    }

    mls_welcome_send_outbox_accept(0)
}

pub fn put_mls_welcome_send_outbox_record<S>(
    outbox: &mut S,
    write: MlsWelcomeSendOutboxWrite<'_>,
) -> Result<MlsWelcomeSendOutboxDecision, S::Error>
where
    S: MlsWelcomeSendOutboxAdapter + ?Sized,
{
    let record_count = outbox.mls_welcome_send_outbox_record_count()?;
    let decision = evaluate_mls_welcome_send_outbox_write(write);
    if !decision.accepted {
        return Ok(MlsWelcomeSendOutboxDecision {
            record_count,
            ..decision
        });
    }

    if outbox
        .read_mls_welcome_send_outbox_by_transaction(write.welcome_send_transaction_digest)?
        .is_some()
    {
        return Ok(mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::WelcomeSendTransactionAlreadyQueued,
            record_count,
            false,
        ));
    }

    if outbox
        .read_mls_welcome_send_outbox_by_key_package(write.key_package_hash)?
        .is_some()
    {
        return Ok(mls_welcome_send_outbox_reject(
            MlsWelcomeSendOutboxReason::KeyPackageAlreadyQueued,
            record_count,
            false,
        ));
    }

    outbox.put_accepted_mls_welcome_send_outbox(AcceptedMlsWelcomeSendOutboxWrite {
        write,
        decision,
    })?;
    let record_count = outbox.mls_welcome_send_outbox_record_count()?;
    Ok(MlsWelcomeSendOutboxDecision {
        record_count,
        ..decision
    })
}

