#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MlsWelcomeReplayStoreWrite<'a> {
    pub welcome_admission: MlsWelcomeAdmissionDecision,
    pub group_id: &'a [u8],
    pub welcome_hash: &'a [u8],
    pub consumed_key_package_ref: &'a [u8],
    pub tree_hash: &'a [u8],
    pub confirmed_transcript_hash: &'a [u8],
    pub group_state_commit_digest: &'a [u8],
    pub epoch: i64,
    pub joined_at_s: i64,
    pub init_key_deleted: bool,
    pub group_state_committed: bool,
    pub plaintext_metadata_fields: i32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MlsWelcomeReplayStoreRecord {
    pub group_id: Vec<u8>,
    pub welcome_hash: Vec<u8>,
    pub consumed_key_package_ref: Vec<u8>,
    pub tree_hash: Vec<u8>,
    pub confirmed_transcript_hash: Vec<u8>,
    pub group_state_commit_digest: Vec<u8>,
    pub epoch: i64,
    pub joined_at_s: i64,
    pub init_key_deleted: bool,
    pub plaintext_bytes_exposed: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MlsWelcomeReplayStoreDecision {
    pub accepted: bool,
    pub reason: MlsWelcomeReplayStoreReason,
    pub persisted_record: bool,
    pub record_count: usize,
    pub can_initialize_group_once: bool,
    pub can_open_group: bool,
    pub consumes_key_package: bool,
    pub deletes_init_key: bool,
    pub binds_tree_hash: bool,
    pub binds_confirmed_transcript_hash: bool,
    pub commits_group_state_transactionally: bool,
    pub keeps_digest_only: bool,
    pub plaintext_bytes_exposed: bool,
}

pub struct AcceptedMlsWelcomeReplayStoreWrite<'a> {
    write: MlsWelcomeReplayStoreWrite<'a>,
    decision: MlsWelcomeReplayStoreDecision,
}

impl<'a> AcceptedMlsWelcomeReplayStoreWrite<'a> {
    pub const fn write(&self) -> MlsWelcomeReplayStoreWrite<'a> {
        self.write
    }

    pub const fn decision(&self) -> &MlsWelcomeReplayStoreDecision {
        &self.decision
    }
}

pub trait MlsWelcomeReplayStoreAdapter {
    type Error;

    fn put_accepted_mls_welcome_replay(
        &mut self,
        write: AcceptedMlsWelcomeReplayStoreWrite<'_>,
    ) -> Result<(), Self::Error>;

    fn read_mls_welcome_replay(
        &self,
        group_id: &[u8],
        welcome_hash: &[u8],
    ) -> Result<Option<MlsWelcomeReplayStoreRecord>, Self::Error>;

    fn read_mls_welcome_replay_by_key_package(
        &self,
        consumed_key_package_ref: &[u8],
    ) -> Result<Option<MlsWelcomeReplayStoreRecord>, Self::Error>;

    fn mls_welcome_replay_record_count(&self) -> Result<usize, Self::Error>;
}

pub fn evaluate_mls_welcome_replay_store_write(
    write: MlsWelcomeReplayStoreWrite<'_>,
) -> MlsWelcomeReplayStoreDecision {
    if !write.welcome_admission.accepted
        || !write.welcome_admission.can_join_group
        || !write.welcome_admission.can_initialize_epoch
        || !write.welcome_admission.can_open_group
        || !write.welcome_admission.prevents_welcome_replay
    {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::WelcomeAdmissionRejected,
            0,
            false,
        );
    }

    if write.group_id.len() != 32 {
        return mls_welcome_replay_store_reject(MlsWelcomeReplayStoreReason::BadGroupId, 0, false);
    }

    if write.welcome_hash.len() != 32 {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::BadWelcomeHash,
            0,
            false,
        );
    }

    if write.consumed_key_package_ref.len() != 32 {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::BadConsumedKeyPackageRef,
            0,
            false,
        );
    }

    if write.tree_hash.len() != 32 {
        return mls_welcome_replay_store_reject(MlsWelcomeReplayStoreReason::BadTreeHash, 0, false);
    }

    if write.confirmed_transcript_hash.len() != 32 {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::BadConfirmedTranscriptHash,
            0,
            false,
        );
    }

    if write.group_state_commit_digest.len() != 32 {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::BadGroupStateCommitDigest,
            0,
            false,
        );
    }

    if write.epoch <= 0 {
        return mls_welcome_replay_store_reject(MlsWelcomeReplayStoreReason::BadEpoch, 0, false);
    }

    if write.joined_at_s < 0 {
        return mls_welcome_replay_store_reject(MlsWelcomeReplayStoreReason::BadJoinedAt, 0, false);
    }

    if !write.init_key_deleted {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::InitKeyNotDeleted,
            0,
            false,
        );
    }

    if !write.group_state_committed {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::GroupStateNotCommitted,
            0,
            false,
        );
    }

    if write.plaintext_metadata_fields != 0 {
        return mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::PlaintextMetadataForbidden,
            0,
            true,
        );
    }

    mls_welcome_replay_store_accept(0, write.welcome_admission.can_open_group)
}

pub fn put_mls_welcome_replay_record<S>(
    store: &mut S,
    write: MlsWelcomeReplayStoreWrite<'_>,
) -> Result<MlsWelcomeReplayStoreDecision, S::Error>
where
    S: MlsWelcomeReplayStoreAdapter + ?Sized,
{
    let record_count = store.mls_welcome_replay_record_count()?;
    let decision = evaluate_mls_welcome_replay_store_write(write);
    if !decision.accepted {
        return Ok(MlsWelcomeReplayStoreDecision {
            record_count,
            ..decision
        });
    }

    if store
        .read_mls_welcome_replay(write.group_id, write.welcome_hash)?
        .is_some()
    {
        return Ok(mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::WelcomeAlreadyRecorded,
            record_count,
            false,
        ));
    }

    if store
        .read_mls_welcome_replay_by_key_package(write.consumed_key_package_ref)?
        .is_some()
    {
        return Ok(mls_welcome_replay_store_reject(
            MlsWelcomeReplayStoreReason::KeyPackageAlreadyConsumed,
            record_count,
            false,
        ));
    }

    store
        .put_accepted_mls_welcome_replay(AcceptedMlsWelcomeReplayStoreWrite { write, decision })?;
    let record_count = store.mls_welcome_replay_record_count()?;
    Ok(MlsWelcomeReplayStoreDecision {
        record_count,
        ..decision
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeMlsWelcomeReplayStore {
    records: BTreeMap<(Vec<u8>, Vec<u8>), MlsWelcomeReplayStoreRecord>,
}

impl PrototypeMlsWelcomeReplayStore {
    pub fn put(&mut self, write: MlsWelcomeReplayStoreWrite<'_>) -> MlsWelcomeReplayStoreDecision {
        match put_mls_welcome_replay_record(self, write) {
            Ok(decision) => decision,
            Err(error) => match error {},
        }
    }

    pub fn get(
        &self,
        group_id: &[u8],
        welcome_hash: &[u8],
    ) -> Option<&MlsWelcomeReplayStoreRecord> {
        self.records
            .get(&(group_id.to_vec(), welcome_hash.to_vec()))
    }

    pub fn len(&self) -> usize {
        self.records.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records.is_empty()
    }
}

impl MlsWelcomeReplayStoreAdapter for PrototypeMlsWelcomeReplayStore {
    type Error = Infallible;

    fn put_accepted_mls_welcome_replay(
        &mut self,
        write: AcceptedMlsWelcomeReplayStoreWrite<'_>,
    ) -> Result<(), Self::Error> {
        let request = write.write();
        let record = MlsWelcomeReplayStoreRecord {
            group_id: request.group_id.to_vec(),
            welcome_hash: request.welcome_hash.to_vec(),
            consumed_key_package_ref: request.consumed_key_package_ref.to_vec(),
            tree_hash: request.tree_hash.to_vec(),
            confirmed_transcript_hash: request.confirmed_transcript_hash.to_vec(),
            group_state_commit_digest: request.group_state_commit_digest.to_vec(),
            epoch: request.epoch,
            joined_at_s: request.joined_at_s,
            init_key_deleted: request.init_key_deleted,
            plaintext_bytes_exposed: false,
        };
        self.records.insert(
            (record.group_id.clone(), record.welcome_hash.clone()),
            record,
        );
        Ok(())
    }

    fn read_mls_welcome_replay(
        &self,
        group_id: &[u8],
        welcome_hash: &[u8],
    ) -> Result<Option<MlsWelcomeReplayStoreRecord>, Self::Error> {
        Ok(self.get(group_id, welcome_hash).cloned())
    }

    fn read_mls_welcome_replay_by_key_package(
        &self,
        consumed_key_package_ref: &[u8],
    ) -> Result<Option<MlsWelcomeReplayStoreRecord>, Self::Error> {
        Ok(self
            .records
            .values()
            .find(|record| record.consumed_key_package_ref == consumed_key_package_ref)
            .cloned())
    }

    fn mls_welcome_replay_record_count(&self) -> Result<usize, Self::Error> {
        Ok(self.records.len())
    }
}

const fn mls_welcome_replay_store_accept(
    record_count: usize,
    can_open_group: bool,
) -> MlsWelcomeReplayStoreDecision {
    MlsWelcomeReplayStoreDecision {
        accepted: true,
        reason: MlsWelcomeReplayStoreReason::Accepted,
        persisted_record: true,
        record_count,
        can_initialize_group_once: true,
        can_open_group,
        consumes_key_package: true,
        deletes_init_key: true,
        binds_tree_hash: true,
        binds_confirmed_transcript_hash: true,
        commits_group_state_transactionally: true,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

const fn mls_welcome_replay_store_reject(
    reason: MlsWelcomeReplayStoreReason,
    record_count: usize,
    plaintext_bytes_exposed: bool,
) -> MlsWelcomeReplayStoreDecision {
    MlsWelcomeReplayStoreDecision {
        accepted: false,
        reason,
        persisted_record: false,
        record_count,
        can_initialize_group_once: false,
        can_open_group: false,
        consumes_key_package: false,
        deletes_init_key: false,
        binds_tree_hash: false,
        binds_confirmed_transcript_hash: false,
        commits_group_state_transactionally: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed,
    }
}

