#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MlsCommitAdmissionInput {
    pub group_chat: GroupChatDecision,
    pub current_epoch: i64,
    pub commit_epoch: i64,
    pub external_commit: bool,
    pub sender_is_member: bool,
    pub sender_type_new_member_commit: bool,
    pub external_init_present: bool,
    pub commit_signature_valid: bool,
    pub commit_membership_tag_valid: bool,
    pub proposal_list_valid: bool,
    pub referenced_proposals_available: bool,
    pub application_policy_accepts_proposals: bool,
    pub duplicate_update_or_remove_targets: bool,
    pub committer_update_present: bool,
    pub committer_remove_present: bool,
    pub path_required: bool,
    pub update_path_present: bool,
    pub update_path_leaf_valid: bool,
    pub update_path_leaf_source_commit: bool,
    pub update_path_parent_hash_valid: bool,
    pub update_path_secret_decryptable: bool,
    pub ratchet_tree_hash_matches: bool,
    pub provisional_group_context_bound: bool,
    pub epoch_secret_derived: bool,
    pub confirmed_transcript_hash_len: i32,
    pub confirmation_tag_valid: bool,
    pub commit_won_tie_break: bool,
    pub commit_hash_len: i32,
    pub commit_hash_already_processed: bool,
    pub removes_local_member: bool,
    pub plaintext_commit_metadata_fields: i32,
}

impl MlsCommitAdmissionInput {
    pub fn evaluate(self) -> MlsCommitAdmissionDecision {
        evaluate_mls_commit_admission(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MlsCommitAdmissionDecision {
    pub accepted: bool,
    pub reason: MlsCommitAdmissionReason,
    pub can_apply_commit: bool,
    pub can_initialize_epoch: bool,
    pub can_continue_group: bool,
    pub local_member_removed: bool,
    pub requires_sync: bool,
    pub requires_mls_setup: bool,
    pub requires_tree_repair: bool,
    pub requires_rekey: bool,
    pub requires_user_action: bool,
    pub prevents_commit_replay: bool,
    pub forbids_plaintext_commit_metadata: bool,
    pub plaintext_bytes_exposed: bool,
}

pub fn evaluate_mls_commit_admission(input: MlsCommitAdmissionInput) -> MlsCommitAdmissionDecision {
    if !input.group_chat.accepted || !input.group_chat.can_open_group {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::GroupChatRejected,
            input.group_chat.requires_sync,
            input.group_chat.requires_mls_setup,
            input.group_chat.requires_user_action,
            false,
            false,
            false,
        );
    }

    if input.current_epoch <= 0 || input.commit_epoch != input.current_epoch {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::BadEpoch,
            true,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.external_commit {
        if !input.sender_type_new_member_commit || !input.external_init_present {
            return mls_commit_admission_reject(
                MlsCommitAdmissionReason::ExternalCommitSenderInvalid,
                false,
                true,
                true,
                false,
                false,
                false,
            );
        }
    } else if !input.sender_is_member {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::CommitSenderNotMember,
            true,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if !input.commit_signature_valid || !input.commit_membership_tag_valid {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::CommitAuthenticationInvalid,
            true,
            true,
            true,
            false,
            false,
            false,
        );
    }

    if !input.proposal_list_valid {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::ProposalListInvalid,
            true,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if !input.referenced_proposals_available {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::ReferencedProposalMissing,
            true,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if !input.application_policy_accepts_proposals {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::ApplicationPolicyRejected,
            false,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if input.duplicate_update_or_remove_targets {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::DuplicateProposalTargets,
            true,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if input.committer_update_present {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::CommitterUpdateForbidden,
            true,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if input.committer_remove_present {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::CommitterRemoveForbidden,
            true,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if input.path_required && !input.update_path_present {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::PathRequiredMissing,
            false,
            true,
            true,
            true,
            false,
            false,
        );
    }

    if input.update_path_present {
        if !input.update_path_leaf_valid {
            return mls_commit_admission_reject(
                MlsCommitAdmissionReason::UpdatePathLeafInvalid,
                false,
                true,
                true,
                true,
                false,
                false,
            );
        }

        if !input.update_path_leaf_source_commit {
            return mls_commit_admission_reject(
                MlsCommitAdmissionReason::UpdatePathLeafSourceInvalid,
                false,
                true,
                true,
                true,
                false,
                false,
            );
        }

        if !input.update_path_parent_hash_valid {
            return mls_commit_admission_reject(
                MlsCommitAdmissionReason::UpdatePathParentHashInvalid,
                true,
                true,
                true,
                true,
                false,
                false,
            );
        }

        if !input.update_path_secret_decryptable {
            return mls_commit_admission_reject(
                MlsCommitAdmissionReason::UpdatePathSecretDecryptFailed,
                true,
                true,
                true,
                true,
                false,
                false,
            );
        }

        if !input.ratchet_tree_hash_matches {
            return mls_commit_admission_reject(
                MlsCommitAdmissionReason::RatchetTreeHashMismatch,
                true,
                true,
                true,
                true,
                false,
                false,
            );
        }
    }

    if !input.provisional_group_context_bound {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::ProvisionalGroupContextMismatch,
            true,
            true,
            true,
            false,
            false,
            false,
        );
    }

    if !input.epoch_secret_derived {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::EpochSecretDerivationFailed,
            true,
            true,
            true,
            false,
            false,
            false,
        );
    }

    if input.confirmed_transcript_hash_len != 32 {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::BadConfirmedTranscriptHash,
            true,
            true,
            true,
            false,
            false,
            false,
        );
    }

    if !input.confirmation_tag_valid {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::ConfirmationTagInvalid,
            true,
            true,
            true,
            false,
            false,
            false,
        );
    }

    if !input.commit_won_tie_break {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::CommitTieBreakRejected,
            true,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.commit_hash_len != 32 {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::BadCommitHash,
            true,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.commit_hash_already_processed {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::CommitAlreadyProcessed,
            true,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.plaintext_commit_metadata_fields != 0 {
        return mls_commit_admission_reject(
            MlsCommitAdmissionReason::PlaintextCommitMetadataForbidden,
            false,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if input.removes_local_member {
        return MlsCommitAdmissionDecision {
            accepted: true,
            reason: MlsCommitAdmissionReason::LocalMemberRemoved,
            can_apply_commit: true,
            can_initialize_epoch: false,
            can_continue_group: false,
            local_member_removed: true,
            requires_sync: false,
            requires_mls_setup: false,
            requires_tree_repair: false,
            requires_rekey: true,
            requires_user_action: true,
            prevents_commit_replay: true,
            forbids_plaintext_commit_metadata: true,
            plaintext_bytes_exposed: false,
        };
    }

    MlsCommitAdmissionDecision {
        accepted: true,
        reason: MlsCommitAdmissionReason::Accepted,
        can_apply_commit: true,
        can_initialize_epoch: true,
        can_continue_group: true,
        local_member_removed: false,
        requires_sync: false,
        requires_mls_setup: false,
        requires_tree_repair: false,
        requires_rekey: false,
        requires_user_action: false,
        prevents_commit_replay: true,
        forbids_plaintext_commit_metadata: true,
        plaintext_bytes_exposed: false,
    }
}

const fn mls_commit_admission_reject(
    reason: MlsCommitAdmissionReason,
    requires_sync: bool,
    requires_mls_setup: bool,
    requires_user_action: bool,
    requires_tree_repair: bool,
    requires_rekey: bool,
    plaintext_bytes_exposed: bool,
) -> MlsCommitAdmissionDecision {
    MlsCommitAdmissionDecision {
        accepted: false,
        reason,
        can_apply_commit: false,
        can_initialize_epoch: false,
        can_continue_group: false,
        local_member_removed: false,
        requires_sync,
        requires_mls_setup,
        requires_tree_repair,
        requires_rekey,
        requires_user_action,
        prevents_commit_replay: true,
        forbids_plaintext_commit_metadata: true,
        plaintext_bytes_exposed,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MlsCommitReplayStoreReason {
    Accepted,
    CommitAdmissionRejected,
    BadGroupId,
    BadCommitHash,
    BadEpoch,
    BadAppliedAt,
    PlaintextMetadataForbidden,
    CommitAlreadyRecorded,
}

impl MlsCommitReplayStoreReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::Accepted => 0,
            Self::CommitAdmissionRejected => 1,
            Self::BadGroupId => 2,
            Self::BadCommitHash => 3,
            Self::BadEpoch => 4,
            Self::BadAppliedAt => 5,
            Self::PlaintextMetadataForbidden => 6,
            Self::CommitAlreadyRecorded => 7,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Accepted => "ACCEPTED",
            Self::CommitAdmissionRejected => "COMMIT_ADMISSION_REJECTED",
            Self::BadGroupId => "BAD_GROUP_ID",
            Self::BadCommitHash => "BAD_COMMIT_HASH",
            Self::BadEpoch => "BAD_EPOCH",
            Self::BadAppliedAt => "BAD_APPLIED_AT",
            Self::PlaintextMetadataForbidden => "PLAINTEXT_METADATA_FORBIDDEN",
            Self::CommitAlreadyRecorded => "COMMIT_ALREADY_RECORDED",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MlsCommitReplayStoreWrite<'a> {
    pub commit_admission: MlsCommitAdmissionDecision,
    pub group_id: &'a [u8],
    pub commit_hash: &'a [u8],
    pub epoch: i64,
    pub applied_at_s: i64,
    pub plaintext_metadata_fields: i32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MlsCommitReplayStoreRecord {
    pub group_id: Vec<u8>,
    pub commit_hash: Vec<u8>,
    pub epoch: i64,
    pub applied_at_s: i64,
    pub local_member_removed: bool,
    pub plaintext_bytes_exposed: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MlsCommitReplayStoreDecision {
    pub accepted: bool,
    pub reason: MlsCommitReplayStoreReason,
    pub persisted_record: bool,
    pub record_count: usize,
    pub can_apply_commit_once: bool,
    pub can_continue_group: bool,
    pub local_member_removed: bool,
    pub keeps_digest_only: bool,
    pub plaintext_bytes_exposed: bool,
}

pub struct AcceptedMlsCommitReplayStoreWrite<'a> {
    write: MlsCommitReplayStoreWrite<'a>,
    decision: MlsCommitReplayStoreDecision,
}

impl<'a> AcceptedMlsCommitReplayStoreWrite<'a> {
    pub const fn write(&self) -> MlsCommitReplayStoreWrite<'a> {
        self.write
    }

    pub const fn decision(&self) -> &MlsCommitReplayStoreDecision {
        &self.decision
    }
}

pub trait MlsCommitReplayStoreAdapter {
    type Error;

    fn put_accepted_mls_commit_replay(
        &mut self,
        write: AcceptedMlsCommitReplayStoreWrite<'_>,
    ) -> Result<(), Self::Error>;

    fn read_mls_commit_replay(
        &self,
        group_id: &[u8],
        commit_hash: &[u8],
    ) -> Result<Option<MlsCommitReplayStoreRecord>, Self::Error>;

    fn mls_commit_replay_record_count(&self) -> Result<usize, Self::Error>;
}

pub fn evaluate_mls_commit_replay_store_write(
    write: MlsCommitReplayStoreWrite<'_>,
) -> MlsCommitReplayStoreDecision {
    if !write.commit_admission.accepted
        || !write.commit_admission.can_apply_commit
        || !write.commit_admission.prevents_commit_replay
    {
        return mls_commit_replay_store_reject(
            MlsCommitReplayStoreReason::CommitAdmissionRejected,
            0,
            false,
        );
    }

    if write.group_id.len() != 32 {
        return mls_commit_replay_store_reject(MlsCommitReplayStoreReason::BadGroupId, 0, false);
    }

    if write.commit_hash.len() != 32 {
        return mls_commit_replay_store_reject(MlsCommitReplayStoreReason::BadCommitHash, 0, false);
    }

    if write.epoch <= 0 {
        return mls_commit_replay_store_reject(MlsCommitReplayStoreReason::BadEpoch, 0, false);
    }

    if write.applied_at_s < 0 {
        return mls_commit_replay_store_reject(MlsCommitReplayStoreReason::BadAppliedAt, 0, false);
    }

    if write.plaintext_metadata_fields != 0 {
        return mls_commit_replay_store_reject(
            MlsCommitReplayStoreReason::PlaintextMetadataForbidden,
            0,
            true,
        );
    }

    mls_commit_replay_store_accept(
        0,
        write.commit_admission.can_continue_group,
        write.commit_admission.local_member_removed,
    )
}

pub fn put_mls_commit_replay_record<S>(
    store: &mut S,
    write: MlsCommitReplayStoreWrite<'_>,
) -> Result<MlsCommitReplayStoreDecision, S::Error>
where
    S: MlsCommitReplayStoreAdapter + ?Sized,
{
    let record_count = store.mls_commit_replay_record_count()?;
    let decision = evaluate_mls_commit_replay_store_write(write);
    if !decision.accepted {
        return Ok(MlsCommitReplayStoreDecision {
            record_count,
            ..decision
        });
    }

    if store
        .read_mls_commit_replay(write.group_id, write.commit_hash)?
        .is_some()
    {
        return Ok(mls_commit_replay_store_reject(
            MlsCommitReplayStoreReason::CommitAlreadyRecorded,
            record_count,
            false,
        ));
    }

    store.put_accepted_mls_commit_replay(AcceptedMlsCommitReplayStoreWrite { write, decision })?;
    let record_count = store.mls_commit_replay_record_count()?;
    Ok(MlsCommitReplayStoreDecision {
        record_count,
        ..decision
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeMlsCommitReplayStore {
    records: BTreeMap<(Vec<u8>, Vec<u8>), MlsCommitReplayStoreRecord>,
}

impl PrototypeMlsCommitReplayStore {
    pub fn put(&mut self, write: MlsCommitReplayStoreWrite<'_>) -> MlsCommitReplayStoreDecision {
        match put_mls_commit_replay_record(self, write) {
            Ok(decision) => decision,
            Err(error) => match error {},
        }
    }

    pub fn get(&self, group_id: &[u8], commit_hash: &[u8]) -> Option<&MlsCommitReplayStoreRecord> {
        self.records.get(&(group_id.to_vec(), commit_hash.to_vec()))
    }

    pub fn len(&self) -> usize {
        self.records.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records.is_empty()
    }
}

impl MlsCommitReplayStoreAdapter for PrototypeMlsCommitReplayStore {
    type Error = Infallible;

    fn put_accepted_mls_commit_replay(
        &mut self,
        write: AcceptedMlsCommitReplayStoreWrite<'_>,
    ) -> Result<(), Self::Error> {
        let request = write.write();
        let record = MlsCommitReplayStoreRecord {
            group_id: request.group_id.to_vec(),
            commit_hash: request.commit_hash.to_vec(),
            epoch: request.epoch,
            applied_at_s: request.applied_at_s,
            local_member_removed: request.commit_admission.local_member_removed,
            plaintext_bytes_exposed: false,
        };
        self.records.insert(
            (record.group_id.clone(), record.commit_hash.clone()),
            record,
        );
        Ok(())
    }

    fn read_mls_commit_replay(
        &self,
        group_id: &[u8],
        commit_hash: &[u8],
    ) -> Result<Option<MlsCommitReplayStoreRecord>, Self::Error> {
        Ok(self.get(group_id, commit_hash).cloned())
    }

    fn mls_commit_replay_record_count(&self) -> Result<usize, Self::Error> {
        Ok(self.records.len())
    }
}

const fn mls_commit_replay_store_accept(
    record_count: usize,
    can_continue_group: bool,
    local_member_removed: bool,
) -> MlsCommitReplayStoreDecision {
    MlsCommitReplayStoreDecision {
        accepted: true,
        reason: MlsCommitReplayStoreReason::Accepted,
        persisted_record: true,
        record_count,
        can_apply_commit_once: true,
        can_continue_group,
        local_member_removed,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

const fn mls_commit_replay_store_reject(
    reason: MlsCommitReplayStoreReason,
    record_count: usize,
    plaintext_bytes_exposed: bool,
) -> MlsCommitReplayStoreDecision {
    MlsCommitReplayStoreDecision {
        accepted: false,
        reason,
        persisted_record: false,
        record_count,
        can_apply_commit_once: false,
        can_continue_group: false,
        local_member_removed: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum GroupMessageTranscriptReason {
    Accepted,
    GroupChatRejected,
    OutboundSendRejected,
    BadGroupIdentifier,
    EpochMismatch,
    BadSenderLeafIndex,
    BadSenderGeneration,
    TranscriptContextMissing,
    SenderDataNotSealed,
    ApplicationPayloadNotSealed,
    ReuseGuardMissing,
    LocalStoreSealingRejected,
    LocalStoreEpochBindingMismatch,
    UsedGenerationNotDeleted,
}

impl GroupMessageTranscriptReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::Accepted => 0,
            Self::GroupChatRejected => 1,
            Self::OutboundSendRejected => 2,
            Self::BadGroupIdentifier => 3,
            Self::EpochMismatch => 4,
            Self::BadSenderLeafIndex => 5,
            Self::BadSenderGeneration => 6,
            Self::TranscriptContextMissing => 7,
            Self::SenderDataNotSealed => 8,
            Self::ApplicationPayloadNotSealed => 9,
            Self::ReuseGuardMissing => 10,
            Self::LocalStoreSealingRejected => 11,
            Self::LocalStoreEpochBindingMismatch => 12,
            Self::UsedGenerationNotDeleted => 13,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Accepted => "ACCEPTED",
            Self::GroupChatRejected => "GROUP_CHAT_REJECTED",
            Self::OutboundSendRejected => "OUTBOUND_SEND_REJECTED",
            Self::BadGroupIdentifier => "BAD_GROUP_IDENTIFIER",
            Self::EpochMismatch => "EPOCH_MISMATCH",
            Self::BadSenderLeafIndex => "BAD_SENDER_LEAF_INDEX",
            Self::BadSenderGeneration => "BAD_SENDER_GENERATION",
            Self::TranscriptContextMissing => "TRANSCRIPT_CONTEXT_MISSING",
            Self::SenderDataNotSealed => "SENDER_DATA_NOT_SEALED",
            Self::ApplicationPayloadNotSealed => "APPLICATION_PAYLOAD_NOT_SEALED",
            Self::ReuseGuardMissing => "REUSE_GUARD_MISSING",
            Self::LocalStoreSealingRejected => "LOCAL_STORE_SEALING_REJECTED",
            Self::LocalStoreEpochBindingMismatch => "LOCAL_STORE_EPOCH_BINDING_MISMATCH",
            Self::UsedGenerationNotDeleted => "USED_GENERATION_NOT_DELETED",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupMessageTranscriptInput<'a> {
    pub group_chat: GroupChatDecision,
    pub outbound_send: OutboundSendDecision,
    pub local_store_seal: LocalStoreSealRequest<'a>,
    pub group_id_len: i32,
    pub message_epoch: i32,
    pub local_epoch: i32,
    pub sender_leaf_index: i32,
    pub sender_generation: i32,
    pub group_context_digest_len: i32,
    pub confirmed_transcript_hash_len: i32,
    pub sender_data_sealed: bool,
    pub application_payload_sealed: bool,
    pub reuse_guard_len: i32,
    pub used_generation_deleted: bool,
}

impl<'a> GroupMessageTranscriptInput<'a> {
    pub fn evaluate(self) -> GroupMessageTranscriptDecision {
        evaluate_group_message_transcript(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupMessageTranscriptDecision {
    pub accepted: bool,
    pub can_persist_ciphertext: bool,
    pub can_submit_to_relay: bool,
    pub requires_sync: bool,
    pub requires_rekey: bool,
    pub requires_user_action: bool,
    pub forbids_plaintext: bool,
    pub plaintext_bytes_exposed: bool,
    pub reason: GroupMessageTranscriptReason,
}

impl GroupMessageTranscriptDecision {
    pub const fn reason_code(self) -> i32 {
        self.reason.code()
    }

    pub const fn reason_label(self) -> &'static str {
        self.reason.label()
    }
}

pub fn evaluate_group_message_transcript(
    input: GroupMessageTranscriptInput<'_>,
) -> GroupMessageTranscriptDecision {
    if !input.group_chat.accepted {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::GroupChatRejected,
            input.group_chat.requires_sync,
            input.group_chat.requires_mls_setup || input.group_chat.requires_pq_upgrade,
            input.group_chat.requires_user_action,
        );
    }

    if !input.outbound_send.accepted
        || !input.outbound_send.can_send
        || !input.outbound_send.can_persist_ciphertext
    {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::OutboundSendRejected,
            false,
            false,
            input.outbound_send.requires_user_action,
        );
    }

    if input.group_id_len <= 0 {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::BadGroupIdentifier,
            false,
            false,
            true,
        );
    }

    if input.message_epoch <= 0
        || input.local_epoch <= 0
        || input.message_epoch != input.local_epoch
    {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::EpochMismatch,
            true,
            false,
            false,
        );
    }

    if input.sender_leaf_index < 0 {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::BadSenderLeafIndex,
            false,
            false,
            true,
        );
    }

    if input.sender_generation < 0 {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::BadSenderGeneration,
            true,
            false,
            false,
        );
    }

    if input.group_context_digest_len < 32 || input.confirmed_transcript_hash_len < 32 {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::TranscriptContextMissing,
            true,
            false,
            false,
        );
    }

    if !input.sender_data_sealed {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::SenderDataNotSealed,
            false,
            true,
            false,
        );
    }

    if !input.application_payload_sealed {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::ApplicationPayloadNotSealed,
            false,
            true,
            false,
        );
    }

    if input.reuse_guard_len != 4 {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::ReuseGuardMissing,
            false,
            true,
            false,
        );
    }

    if !input.local_store_seal.evaluate().accepted {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::LocalStoreSealingRejected,
            false,
            false,
            false,
        );
    }

    if !group_message_local_store_binding_matches(input.local_store_seal, input) {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::LocalStoreEpochBindingMismatch,
            false,
            true,
            false,
        );
    }

    if !input.used_generation_deleted {
        return group_message_transcript_reject(
            GroupMessageTranscriptReason::UsedGenerationNotDeleted,
            false,
            true,
            false,
        );
    }

    GroupMessageTranscriptDecision {
        accepted: true,
        can_persist_ciphertext: true,
        can_submit_to_relay: true,
        requires_sync: false,
        requires_rekey: false,
        requires_user_action: false,
        forbids_plaintext: true,
        plaintext_bytes_exposed: false,
        reason: GroupMessageTranscriptReason::Accepted,
    }
}

fn group_message_local_store_binding_matches(
    request: LocalStoreSealRequest<'_>,
    input: GroupMessageTranscriptInput<'_>,
) -> bool {
    request.record_kind.policy().plaintext_class == LocalStorePlaintextClass::EncryptedOnly
        && request.record_kind == LocalStoreRecordKind::MessageCiphertext
        && request.key.scope == LocalStoreKeyScope::RoomEpoch
        && request.key.binding.account_id_len > 0
        && request.key.binding.conversation_id_len == input.group_id_len
        && request.key.binding.room_epoch == input.message_epoch
}

const fn group_message_transcript_reject(
    reason: GroupMessageTranscriptReason,
    requires_sync: bool,
    requires_rekey: bool,
    requires_user_action: bool,
) -> GroupMessageTranscriptDecision {
    GroupMessageTranscriptDecision {
        accepted: false,
        can_persist_ciphertext: false,
        can_submit_to_relay: false,
        requires_sync,
        requires_rekey,
        requires_user_action,
        forbids_plaintext: true,
        plaintext_bytes_exposed: false,
        reason,
    }
}

