#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreWriteIntent {
    pub record_kind: LocalStoreRecordKind,
    pub encrypted_at_rest: bool,
    pub policy_decision: Option<PolicyDecision>,
}

impl LocalStoreWriteIntent {
    pub const fn new(
        record_kind: LocalStoreRecordKind,
        encrypted_at_rest: bool,
        policy_decision: Option<PolicyDecision>,
    ) -> Self {
        Self {
            record_kind,
            encrypted_at_rest,
            policy_decision,
        }
    }

    pub fn evaluate(self) -> LocalStoreWriteDecision {
        evaluate_local_store_write(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LocalStoreWriteReason {
    Accepted,
    RequiresEncryptionAtRest,
    PlaintextRecordForbidden,
    PolicyDecisionRequired,
    PolicyDecisionRejected,
    PayloadClassMismatch,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreWriteDecision {
    pub accepted: bool,
    pub reason: LocalStoreWriteReason,
    pub record_policy: LocalStoreRecordPolicy,
}

pub fn evaluate_local_store_write(intent: LocalStoreWriteIntent) -> LocalStoreWriteDecision {
    let record_policy = intent.record_kind.policy();

    if record_policy.plaintext_class == LocalStorePlaintextClass::NeverStore {
        return local_store_reject(
            record_policy,
            LocalStoreWriteReason::PlaintextRecordForbidden,
        );
    }

    if record_policy.plaintext_class == LocalStorePlaintextClass::EncryptedOnly
        && !intent.encrypted_at_rest
    {
        return local_store_reject(
            record_policy,
            LocalStoreWriteReason::RequiresEncryptionAtRest,
        );
    }

    match record_policy.policy_requirement {
        LocalStorePolicyRequirement::None => local_store_accept(record_policy),
        LocalStorePolicyRequirement::AnyMessagePolicyDecision => {
            if intent.policy_decision.is_some() {
                local_store_accept(record_policy)
            } else {
                local_store_reject(record_policy, LocalStoreWriteReason::PolicyDecisionRequired)
            }
        }
        LocalStorePolicyRequirement::AcceptedMessagePolicy => match intent.policy_decision {
            Some(decision) if decision.accepted => local_store_accept(record_policy),
            Some(_) => {
                local_store_reject(record_policy, LocalStoreWriteReason::PolicyDecisionRejected)
            }
            None => {
                local_store_reject(record_policy, LocalStoreWriteReason::PolicyDecisionRequired)
            }
        },
    }
}

fn local_store_accept(record_policy: LocalStoreRecordPolicy) -> LocalStoreWriteDecision {
    LocalStoreWriteDecision {
        accepted: true,
        reason: LocalStoreWriteReason::Accepted,
        record_policy,
    }
}

fn local_store_reject(
    record_policy: LocalStoreRecordPolicy,
    reason: LocalStoreWriteReason,
) -> LocalStoreWriteDecision {
    LocalStoreWriteDecision {
        accepted: false,
        reason,
        record_policy,
    }
}

