#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreSealRequest<'a> {
    pub locator: LocalStoreRecordLocator<'a>,
    pub record_kind: LocalStoreRecordKind,
    pub key: LocalStoreKeyDescriptor,
    pub nonce_len: i32,
    pub plaintext_len: i32,
    pub policy_decision: Option<PolicyDecision>,
}

impl<'a> LocalStoreSealRequest<'a> {
    pub const fn new(
        locator: LocalStoreRecordLocator<'a>,
        record_kind: LocalStoreRecordKind,
        key: LocalStoreKeyDescriptor,
        nonce_len: i32,
        plaintext_len: i32,
        policy_decision: Option<PolicyDecision>,
    ) -> Self {
        Self {
            locator,
            record_kind,
            key,
            nonce_len,
            plaintext_len,
            policy_decision,
        }
    }

    pub fn evaluate(self) -> LocalStoreSealingDecision {
        evaluate_local_store_sealing_request(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LocalStoreSealingReason {
    Accepted,
    EmptyLocator,
    RecordCannotBeSealed,
    KeyScopeMismatch,
    KeyBindingMismatch,
    BadKeyGeneration,
    BadNonceLength,
    BadPlaintextLength,
    PolicyDecisionRequired,
    PolicyDecisionRejected,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreSealingDecision {
    pub accepted: bool,
    pub reason: LocalStoreSealingReason,
    pub record_policy: LocalStoreRecordPolicy,
}

pub fn evaluate_local_store_sealing_request(
    request: LocalStoreSealRequest<'_>,
) -> LocalStoreSealingDecision {
    let record_policy = request.record_kind.policy();

    if request.locator.namespace.is_empty() || request.locator.record_id.is_empty() {
        return local_store_seal_reject(record_policy, LocalStoreSealingReason::EmptyLocator);
    }

    if record_policy.plaintext_class != LocalStorePlaintextClass::EncryptedOnly {
        return local_store_seal_reject(
            record_policy,
            LocalStoreSealingReason::RecordCannotBeSealed,
        );
    }

    if request.key.scope != record_policy.key_scope {
        return local_store_seal_reject(record_policy, LocalStoreSealingReason::KeyScopeMismatch);
    }

    if !local_store_key_binding_matches(request.key.scope, request.key.binding) {
        return local_store_seal_reject(record_policy, LocalStoreSealingReason::KeyBindingMismatch);
    }

    if request.key.generation <= 0 {
        return local_store_seal_reject(record_policy, LocalStoreSealingReason::BadKeyGeneration);
    }

    if request.nonce_len != request.key.suite.nonce_len() {
        return local_store_seal_reject(record_policy, LocalStoreSealingReason::BadNonceLength);
    }

    if request.plaintext_len <= 0 {
        return local_store_seal_reject(record_policy, LocalStoreSealingReason::BadPlaintextLength);
    }

    match record_policy.policy_requirement {
        LocalStorePolicyRequirement::None => local_store_seal_accept(record_policy),
        LocalStorePolicyRequirement::AnyMessagePolicyDecision => {
            if request.policy_decision.is_some() {
                local_store_seal_accept(record_policy)
            } else {
                local_store_seal_reject(
                    record_policy,
                    LocalStoreSealingReason::PolicyDecisionRequired,
                )
            }
        }
        LocalStorePolicyRequirement::AcceptedMessagePolicy => match request.policy_decision {
            Some(decision) if decision.accepted => local_store_seal_accept(record_policy),
            Some(_) => local_store_seal_reject(
                record_policy,
                LocalStoreSealingReason::PolicyDecisionRejected,
            ),
            None => local_store_seal_reject(
                record_policy,
                LocalStoreSealingReason::PolicyDecisionRequired,
            ),
        },
    }
}

pub fn build_sealed_local_store_write_request<'a>(
    request: LocalStoreSealRequest<'a>,
    sealed_bytes: &'a [u8],
) -> Result<LocalStoreWriteRequest<'a>, LocalStoreSealingDecision> {
    let decision = request.evaluate();
    if decision.accepted {
        Ok(LocalStoreWriteRequest::new(
            request.locator,
            request.record_kind,
            LocalStorePayload::sealed(sealed_bytes),
            request.policy_decision,
        ))
    } else {
        Err(decision)
    }
}

