#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeMediaUploadSession {
    local_store: PrototypeEncryptedLocalStore,
    crypto: PrototypeLocalStoreCryptoProvider,
    events: Vec<PrototypeMediaUploadSessionEvent>,
}

impl PrototypeMediaUploadSession {
    pub fn run(
        &mut self,
        input: PrototypeMediaUploadSessionInput<'_>,
    ) -> PrototypeMediaUploadSessionOutcome {
        self.events.clear();
        self.record_event(
            PrototypeMediaUploadSessionEventKind::UploadStarted,
            true,
            false,
            PrototypeMediaUploadSessionReason::Completed,
        );

        let sealed =
            match seal_local_store_plaintext(&mut self.crypto, input.seal_request, input.plaintext)
                .expect("prototype crypto is infallible")
            {
                LocalStoreSealResult::Sealed(output) => output,
                LocalStoreSealResult::Rejected(decision) => {
                    self.record_event(
                        PrototypeMediaUploadSessionEventKind::LocalStoreSealEvaluated,
                        false,
                        true,
                        PrototypeMediaUploadSessionReason::LocalStoreSealRejected,
                    );
                    return self.outcome(
                        PrototypeMediaUploadSessionReason::LocalStoreSealRejected,
                        Some(decision),
                        None,
                        None,
                        0,
                        0,
                    );
                }
            };
        let seal_decision = input.seal_request.evaluate();
        self.record_event(
            PrototypeMediaUploadSessionEventKind::LocalStoreSealEvaluated,
            true,
            false,
            PrototypeMediaUploadSessionReason::Completed,
        );

        let media = evaluate_media_object_store(MediaObjectStoreInput {
            outbound_send: input.outbound_send,
            media_sealing: seal_decision,
            object_id_len: len_to_i32(input.object_id.len()),
            ciphertext_len: len_to_i32(sealed.sealed_bytes.len()),
            max_ciphertext_len: input.max_ciphertext_len,
            sealed_header_len: len_to_i32(input.sealed_header.len()),
            content_digest_len: len_to_i32(input.content_digest.len()),
            media_key_commitment_len: len_to_i32(input.media_key_commitment.len()),
            plaintext_bytes: input.plaintext_upload_bytes,
            automatic_download_requested: input.automatic_download_requested,
        });

        if !media.accepted {
            self.record_event(
                PrototypeMediaUploadSessionEventKind::MediaObjectStoreEvaluated,
                false,
                true,
                PrototypeMediaUploadSessionReason::MediaObjectStoreRejected,
            );
            return self.outcome(
                PrototypeMediaUploadSessionReason::MediaObjectStoreRejected,
                Some(seal_decision),
                Some(media),
                None,
                sealed.sealed_bytes.len(),
                0,
            );
        }
        self.record_event(
            PrototypeMediaUploadSessionEventKind::MediaObjectStoreEvaluated,
            true,
            false,
            PrototypeMediaUploadSessionReason::Completed,
        );

        let store_write = self.local_store.put_record(LocalStoreWriteRequest::new(
            input.seal_request.locator,
            input.store_record_kind,
            LocalStorePayload::sealed(&sealed.sealed_bytes),
            input.seal_request.policy_decision,
        ));
        if !store_write.accepted {
            self.record_event(
                PrototypeMediaUploadSessionEventKind::LocalStoreWriteEvaluated,
                false,
                true,
                PrototypeMediaUploadSessionReason::LocalStoreWriteRejected,
            );
            return self.outcome(
                PrototypeMediaUploadSessionReason::LocalStoreWriteRejected,
                Some(seal_decision),
                Some(media),
                Some(store_write),
                sealed.sealed_bytes.len(),
                0,
            );
        }
        self.record_event(
            PrototypeMediaUploadSessionEventKind::LocalStoreWriteEvaluated,
            true,
            false,
            PrototypeMediaUploadSessionReason::Completed,
        );
        self.record_event(
            PrototypeMediaUploadSessionEventKind::UploadFinished,
            true,
            true,
            PrototypeMediaUploadSessionReason::Completed,
        );

        let stored_ciphertext_len = self
            .local_store
            .get_record(input.seal_request.locator)
            .map(|record| record.bytes.len())
            .unwrap_or(0);

        self.outcome(
            PrototypeMediaUploadSessionReason::Completed,
            Some(seal_decision),
            Some(media),
            Some(store_write),
            sealed.sealed_bytes.len(),
            stored_ciphertext_len,
        )
    }

    pub fn local_store(&self) -> &PrototypeEncryptedLocalStore {
        &self.local_store
    }

    pub fn crypto(&self) -> &PrototypeLocalStoreCryptoProvider {
        &self.crypto
    }

    pub fn events(&self) -> &[PrototypeMediaUploadSessionEvent] {
        &self.events
    }

    fn record_event(
        &mut self,
        kind: PrototypeMediaUploadSessionEventKind,
        accepted: bool,
        terminal: bool,
        reason: PrototypeMediaUploadSessionReason,
    ) {
        self.events.push(PrototypeMediaUploadSessionEvent {
            sequence: self.events.len() as i32,
            kind,
            accepted,
            terminal,
            reason,
            plaintext_bytes_exposed: false,
        });
    }

    fn outcome(
        &self,
        reason: PrototypeMediaUploadSessionReason,
        seal: Option<LocalStoreSealingDecision>,
        media: Option<MediaObjectStoreDecision>,
        store_write: Option<LocalStoreWriteDecision>,
        sealed_ciphertext_len: usize,
        stored_ciphertext_len: usize,
    ) -> PrototypeMediaUploadSessionOutcome {
        PrototypeMediaUploadSessionOutcome {
            completed: reason == PrototypeMediaUploadSessionReason::Completed,
            reason,
            seal,
            media,
            store_write,
            local_store_records: self.local_store.len(),
            sealed_ciphertext_len,
            stored_ciphertext_len,
            crypto_seal_calls: self.crypto.seal_calls(),
            plaintext_exposed: false,
        }
    }
}

