#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MediaServiceAdapterInput {
    pub adapter_kind: MediaServiceAdapterKind,
    pub media_object_store: MediaObjectStoreDecision,
    pub service_authenticated: bool,
    pub upload_authorized: bool,
    pub object_namespace_bound: bool,
    pub content_digest_verified: bool,
    pub allow_development_adapter: bool,
}

impl MediaServiceAdapterInput {
    pub const fn evaluate(self) -> MediaServiceAdapterDecision {
        if !self.media_object_store.accepted || !self.media_object_store.can_upload {
            return media_service_adapter_reject(
                MediaServiceAdapterReason::MediaObjectStoreRejected,
                self.media_object_store.requires_user_action,
            );
        }

        if matches!(
            self.adapter_kind,
            MediaServiceAdapterKind::PlaintextDebugStore
        ) {
            return media_service_adapter_reject(
                MediaServiceAdapterReason::PlaintextAdapterForbidden,
                true,
            );
        }

        if matches!(
            self.adapter_kind,
            MediaServiceAdapterKind::DevelopmentMemoryObjectStore
        ) && !self.allow_development_adapter
        {
            return media_service_adapter_reject(
                MediaServiceAdapterReason::DevelopmentAdapterForbidden,
                false,
            );
        }

        if !self.service_authenticated {
            return media_service_adapter_reject(
                MediaServiceAdapterReason::ServiceAuthenticationMissing,
                true,
            );
        }

        if !self.upload_authorized {
            return media_service_adapter_reject(
                MediaServiceAdapterReason::UploadAuthorizationMissing,
                true,
            );
        }

        if !self.object_namespace_bound {
            return media_service_adapter_reject(
                MediaServiceAdapterReason::ObjectNamespaceUnbound,
                false,
            );
        }

        if !self.content_digest_verified {
            return media_service_adapter_reject(
                MediaServiceAdapterReason::ContentDigestUnverified,
                false,
            );
        }

        MediaServiceAdapterDecision {
            accepted: true,
            reason: MediaServiceAdapterReason::Accepted,
            can_upload_object: true,
            can_persist_remote_ciphertext: true,
            requires_network_setup: false,
            requires_user_action: false,
            plaintext_bytes_exposed: false,
            forbids_plaintext_upload: true,
        }
    }
}

