#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MediaServiceDownloadInput {
    pub adapter_kind: MediaServiceAdapterKind,
    pub service_authenticated: bool,
    pub download_authorized: bool,
    pub object_namespace_bound: bool,
    pub content_digest_verified: bool,
    pub allow_development_adapter: bool,
    pub object_id_len: i32,
    pub ciphertext_len: i32,
    pub max_ciphertext_len: i32,
    pub sealed_header_len: i32,
    pub content_digest_len: i32,
    pub media_key_commitment_len: i32,
    pub plaintext_preview_bytes: i32,
    pub automatic_download_requested: bool,
}

impl MediaServiceDownloadInput {
    pub const fn evaluate(self) -> MediaServiceDownloadDecision {
        if self.plaintext_preview_bytes != 0 {
            return media_service_download_reject(
                MediaServiceDownloadReason::PlaintextPreviewForbidden,
                true,
            );
        }

        if self.automatic_download_requested {
            return media_service_download_reject(
                MediaServiceDownloadReason::AutomaticDownloadForbidden,
                true,
            );
        }

        if matches!(
            self.adapter_kind,
            MediaServiceAdapterKind::PlaintextDebugStore
        ) {
            return media_service_download_reject(
                MediaServiceDownloadReason::PlaintextAdapterForbidden,
                true,
            );
        }

        if matches!(
            self.adapter_kind,
            MediaServiceAdapterKind::DevelopmentMemoryObjectStore
        ) && !self.allow_development_adapter
        {
            return media_service_download_reject(
                MediaServiceDownloadReason::DevelopmentAdapterForbidden,
                false,
            );
        }

        if !self.service_authenticated {
            return media_service_download_reject(
                MediaServiceDownloadReason::ServiceAuthenticationMissing,
                true,
            );
        }

        if !self.download_authorized {
            return media_service_download_reject(
                MediaServiceDownloadReason::DownloadAuthorizationMissing,
                true,
            );
        }

        if !self.object_namespace_bound {
            return media_service_download_reject(
                MediaServiceDownloadReason::ObjectNamespaceUnbound,
                false,
            );
        }

        if !self.content_digest_verified {
            return media_service_download_reject(
                MediaServiceDownloadReason::ContentDigestUnverified,
                false,
            );
        }

        if self.object_id_len != 32 {
            return media_service_download_reject(
                MediaServiceDownloadReason::BadObjectIdLength,
                false,
            );
        }

        if self.ciphertext_len <= 0 || self.max_ciphertext_len <= 0 {
            return media_service_download_reject(
                MediaServiceDownloadReason::BadCiphertextLength,
                false,
            );
        }

        if self.ciphertext_len > self.max_ciphertext_len
            || self.ciphertext_len > MERCURY_MAX_MEDIA_OBJECT_BYTES
            || self.max_ciphertext_len > MERCURY_MAX_MEDIA_OBJECT_BYTES
        {
            return media_service_download_reject(
                MediaServiceDownloadReason::CiphertextTooLarge,
                false,
            );
        }

        if self.sealed_header_len <= 0 || self.sealed_header_len > 4096 {
            return media_service_download_reject(
                MediaServiceDownloadReason::BadSealedHeaderLength,
                false,
            );
        }

        if self.content_digest_len != 32 {
            return media_service_download_reject(
                MediaServiceDownloadReason::BadContentDigestLength,
                false,
            );
        }

        if self.media_key_commitment_len != 32 {
            return media_service_download_reject(
                MediaServiceDownloadReason::BadMediaKeyCommitmentLength,
                false,
            );
        }

        MediaServiceDownloadDecision {
            accepted: true,
            reason: MediaServiceDownloadReason::Accepted,
            can_download_object: true,
            can_persist_local_ciphertext: true,
            requires_network_setup: false,
            requires_user_action: false,
            plaintext_bytes_exposed: false,
            forbids_plaintext_preview: true,
        }
    }
}

