#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeMediaCleanupSession {
    local_store: PrototypeEncryptedLocalStore,
    remote_delete_calls: usize,
    events: Vec<PrototypeMediaCleanupSessionEvent>,
}

impl PrototypeMediaCleanupSession {
    pub fn run(
        &mut self,
        input: PrototypeMediaCleanupSessionInput<'_>,
    ) -> PrototypeMediaCleanupSessionOutcome {
        self.events.clear();
        self.local_store = PrototypeEncryptedLocalStore::default();
        self.remote_delete_calls = 0;

        if input.seed_local_cache {
            self.seed_local_cache(input.cache_locator, input.cached_ciphertext);
        }

        self.record_event(
            PrototypeMediaCleanupSessionEventKind::CleanupStarted,
            true,
            false,
            PrototypeMediaCleanupSessionReason::Completed,
        );

        let retention = input.retention.evaluate();
        if !retention.accepted {
            self.record_event(
                PrototypeMediaCleanupSessionEventKind::MediaRetentionEvaluated,
                false,
                true,
                PrototypeMediaCleanupSessionReason::MediaRetentionRejected,
            );
            return self.outcome(
                PrototypeMediaCleanupSessionReason::MediaRetentionRejected,
                retention,
                false,
                false,
                input.cached_ciphertext.len(),
            );
        }

        self.record_event(
            PrototypeMediaCleanupSessionEventKind::MediaRetentionEvaluated,
            true,
            false,
            PrototypeMediaCleanupSessionReason::Completed,
        );

        if retention.can_delete_remote_object {
            self.remote_delete_calls += 1;
            self.record_event(
                PrototypeMediaCleanupSessionEventKind::RemoteDeleteEvaluated,
                true,
                false,
                PrototypeMediaCleanupSessionReason::Completed,
            );
        }

        let mut local_cache_deleted = false;
        if retention.can_evict_local_cache {
            local_cache_deleted = self.local_store.delete(input.cache_locator);
            self.record_event(
                PrototypeMediaCleanupSessionEventKind::LocalCacheDeleteEvaluated,
                true,
                false,
                PrototypeMediaCleanupSessionReason::Completed,
            );
        }

        self.record_event(
            PrototypeMediaCleanupSessionEventKind::CleanupFinished,
            true,
            true,
            PrototypeMediaCleanupSessionReason::Completed,
        );

        self.outcome(
            PrototypeMediaCleanupSessionReason::Completed,
            retention,
            retention.can_evict_local_cache,
            local_cache_deleted,
            input.cached_ciphertext.len(),
        )
    }

    pub fn local_store(&self) -> &PrototypeEncryptedLocalStore {
        &self.local_store
    }

    pub const fn remote_delete_calls(&self) -> usize {
        self.remote_delete_calls
    }

    pub fn events(&self) -> &[PrototypeMediaCleanupSessionEvent] {
        &self.events
    }

    fn seed_local_cache(
        &mut self,
        locator: LocalStoreRecordLocator<'_>,
        cached_ciphertext: &[u8],
    ) -> LocalStoreWriteDecision {
        self.local_store.put_record(LocalStoreWriteRequest::new(
            locator,
            LocalStoreRecordKind::MediaCiphertext,
            LocalStorePayload::sealed(cached_ciphertext),
            Some(prototype_media_cleanup_policy_decision()),
        ))
    }

    fn record_event(
        &mut self,
        kind: PrototypeMediaCleanupSessionEventKind,
        accepted: bool,
        terminal: bool,
        reason: PrototypeMediaCleanupSessionReason,
    ) {
        self.events.push(PrototypeMediaCleanupSessionEvent {
            sequence: self.events.len() as i32,
            kind,
            accepted,
            terminal,
            reason,
            plaintext_bytes_exposed: false,
        });
    }

    fn outcome(
        &self,
        reason: PrototypeMediaCleanupSessionReason,
        retention: MediaRetentionDecision,
        local_cache_delete_attempted: bool,
        local_cache_deleted: bool,
        seeded_cache_ciphertext_len: usize,
    ) -> PrototypeMediaCleanupSessionOutcome {
        PrototypeMediaCleanupSessionOutcome {
            completed: reason == PrototypeMediaCleanupSessionReason::Completed,
            reason,
            retention,
            remote_delete_calls: self.remote_delete_calls,
            local_cache_delete_attempted,
            local_cache_deleted,
            local_store_records: self.local_store.len(),
            seeded_cache_ciphertext_len,
            plaintext_exposed: false,
        }
    }
}

const fn prototype_media_cleanup_policy_decision() -> PolicyDecision {
    PolicyDecision {
        accepted: true,
        reason_code: policy::POLICY_PIPELINE_ACCEPT,
        audit_class: policy::POLICY_PIPELINE_AUDIT_ACCEPTED_POLICY_DECISION,
        components: ComponentReasons {
            envelope_reason: policy::ACCEPT,
            room_epoch_reason: policy::ROOM_EPOCH_ACCEPT,
            ai_grant_reason: policy::AI_GRANT_ACCEPT,
            ai_lifecycle_reason: policy::AI_GRANT_LIFECYCLE_ACCEPT,
        },
    }
}

