#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeMediaServiceUploadSession {
    media_upload: PrototypeMediaUploadSession,
    service_upload_calls: usize,
    events: Vec<PrototypeMediaServiceUploadSessionEvent>,
}

impl PrototypeMediaServiceUploadSession {
    pub fn run(
        &mut self,
        input: PrototypeMediaServiceUploadSessionInput<'_>,
    ) -> PrototypeMediaServiceUploadSessionOutcome {
        self.events.clear();
        self.record_event(
            PrototypeMediaServiceUploadSessionEventKind::ServiceUploadStarted,
            true,
            false,
            PrototypeMediaServiceUploadSessionReason::Completed,
        );

        let upload = self.media_upload.run(input.media_upload);
        if !upload.completed {
            self.record_event(
                PrototypeMediaServiceUploadSessionEventKind::MediaUploadSessionEvaluated,
                false,
                true,
                PrototypeMediaServiceUploadSessionReason::MediaUploadRejected,
            );
            return self.outcome(
                PrototypeMediaServiceUploadSessionReason::MediaUploadRejected,
                upload,
                None,
            );
        }
        self.record_event(
            PrototypeMediaServiceUploadSessionEventKind::MediaUploadSessionEvaluated,
            true,
            false,
            PrototypeMediaServiceUploadSessionReason::Completed,
        );

        let service = MediaServiceAdapterInput {
            adapter_kind: input.adapter_kind,
            media_object_store: upload
                .media
                .expect("completed prototype media upload has media gate decision"),
            service_authenticated: input.service_authenticated,
            upload_authorized: input.upload_authorized,
            object_namespace_bound: input.object_namespace_bound,
            content_digest_verified: input.content_digest_verified,
            allow_development_adapter: input.allow_development_adapter,
        }
        .evaluate();

        if !service.accepted {
            self.record_event(
                PrototypeMediaServiceUploadSessionEventKind::MediaServiceAdapterEvaluated,
                false,
                true,
                PrototypeMediaServiceUploadSessionReason::MediaServiceAdapterRejected,
            );
            return self.outcome(
                PrototypeMediaServiceUploadSessionReason::MediaServiceAdapterRejected,
                upload,
                Some(service),
            );
        }
        self.service_upload_calls += 1;
        self.record_event(
            PrototypeMediaServiceUploadSessionEventKind::MediaServiceAdapterEvaluated,
            true,
            false,
            PrototypeMediaServiceUploadSessionReason::Completed,
        );
        self.record_event(
            PrototypeMediaServiceUploadSessionEventKind::ServiceUploadFinished,
            true,
            true,
            PrototypeMediaServiceUploadSessionReason::Completed,
        );

        self.outcome(
            PrototypeMediaServiceUploadSessionReason::Completed,
            upload,
            Some(service),
        )
    }

    pub fn media_upload_session(&self) -> &PrototypeMediaUploadSession {
        &self.media_upload
    }

    pub const fn service_upload_calls(&self) -> usize {
        self.service_upload_calls
    }

    pub fn events(&self) -> &[PrototypeMediaServiceUploadSessionEvent] {
        &self.events
    }

    fn record_event(
        &mut self,
        kind: PrototypeMediaServiceUploadSessionEventKind,
        accepted: bool,
        terminal: bool,
        reason: PrototypeMediaServiceUploadSessionReason,
    ) {
        self.events.push(PrototypeMediaServiceUploadSessionEvent {
            sequence: self.events.len() as i32,
            kind,
            accepted,
            terminal,
            reason,
            plaintext_bytes_exposed: false,
        });
    }

    fn outcome(
        &self,
        reason: PrototypeMediaServiceUploadSessionReason,
        media_upload: PrototypeMediaUploadSessionOutcome,
        media_service: Option<MediaServiceAdapterDecision>,
    ) -> PrototypeMediaServiceUploadSessionOutcome {
        PrototypeMediaServiceUploadSessionOutcome {
            completed: reason == PrototypeMediaServiceUploadSessionReason::Completed,
            reason,
            media_upload,
            media_service,
            local_store_records: media_upload.local_store_records,
            sealed_ciphertext_len: media_upload.sealed_ciphertext_len,
            stored_ciphertext_len: media_upload.stored_ciphertext_len,
            service_upload_calls: self.service_upload_calls,
            plaintext_exposed: false,
        }
    }
}

