#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeIndexedMediaUploadSession {
    service_upload: PrototypeMediaServiceUploadSession,
    index_store: PrototypeMediaObjectIndexStore,
    events: Vec<PrototypeIndexedMediaUploadSessionEvent>,
}

impl PrototypeIndexedMediaUploadSession {
    pub fn run(
        &mut self,
        input: PrototypeIndexedMediaUploadSessionInput<'_>,
    ) -> PrototypeIndexedMediaUploadSessionOutcome {
        let mut index_store = PrototypeMediaObjectIndexStore::default();
        let outcome = match self.run_with_index_store(&mut index_store, input) {
            Ok(outcome) => outcome,
            Err(error) => match error {},
        };
        self.index_store = index_store;
        outcome
    }

    pub fn run_with_index_store<S>(
        &mut self,
        index_store_adapter: &mut S,
        input: PrototypeIndexedMediaUploadSessionInput<'_>,
    ) -> Result<PrototypeIndexedMediaUploadSessionOutcome, S::Error>
    where
        S: MediaObjectIndexStoreAdapter + ?Sized,
    {
        self.events.clear();
        self.record_event(
            PrototypeIndexedMediaUploadSessionEventKind::IndexedUploadStarted,
            true,
            false,
            PrototypeIndexedMediaUploadSessionReason::Completed,
        );

        let service_upload = self.service_upload.run(input.service_upload);
        if !service_upload.completed {
            self.record_event(
                PrototypeIndexedMediaUploadSessionEventKind::MediaServiceUploadEvaluated,
                false,
                true,
                PrototypeIndexedMediaUploadSessionReason::MediaServiceUploadRejected,
            );
            return Ok(self.outcome(
                PrototypeIndexedMediaUploadSessionReason::MediaServiceUploadRejected,
                service_upload,
                None,
            ));
        }

        self.record_event(
            PrototypeIndexedMediaUploadSessionEventKind::MediaServiceUploadEvaluated,
            true,
            false,
            PrototypeIndexedMediaUploadSessionReason::Completed,
        );

        let index_store = put_media_object_index_record(index_store_adapter, input.index_store)?;
        if !index_store.accepted {
            self.record_event(
                PrototypeIndexedMediaUploadSessionEventKind::MediaObjectIndexStoreEvaluated,
                false,
                true,
                PrototypeIndexedMediaUploadSessionReason::MediaObjectIndexStoreRejected,
            );
            return Ok(self.outcome(
                PrototypeIndexedMediaUploadSessionReason::MediaObjectIndexStoreRejected,
                service_upload,
                Some(index_store),
            ));
        }

        self.record_event(
            PrototypeIndexedMediaUploadSessionEventKind::MediaObjectIndexStoreEvaluated,
            true,
            false,
            PrototypeIndexedMediaUploadSessionReason::Completed,
        );
        self.record_event(
            PrototypeIndexedMediaUploadSessionEventKind::IndexedUploadFinished,
            true,
            true,
            PrototypeIndexedMediaUploadSessionReason::Completed,
        );

        Ok(self.outcome(
            PrototypeIndexedMediaUploadSessionReason::Completed,
            service_upload,
            Some(index_store),
        ))
    }

    pub fn media_service_upload_session(&self) -> &PrototypeMediaServiceUploadSession {
        &self.service_upload
    }

    pub fn index_store(&self) -> &PrototypeMediaObjectIndexStore {
        &self.index_store
    }

    pub fn events(&self) -> &[PrototypeIndexedMediaUploadSessionEvent] {
        &self.events
    }

    fn record_event(
        &mut self,
        kind: PrototypeIndexedMediaUploadSessionEventKind,
        accepted: bool,
        terminal: bool,
        reason: PrototypeIndexedMediaUploadSessionReason,
    ) {
        self.events.push(PrototypeIndexedMediaUploadSessionEvent {
            sequence: self.events.len() as i32,
            kind,
            accepted,
            terminal,
            reason,
            plaintext_bytes_exposed: false,
        });
    }

    fn outcome(
        &self,
        reason: PrototypeIndexedMediaUploadSessionReason,
        service_upload: PrototypeMediaServiceUploadSessionOutcome,
        index_store: Option<MediaObjectIndexStoreDecision>,
    ) -> PrototypeIndexedMediaUploadSessionOutcome {
        PrototypeIndexedMediaUploadSessionOutcome {
            completed: reason == PrototypeIndexedMediaUploadSessionReason::Completed,
            reason,
            service_upload,
            index_store_records: index_store
                .as_ref()
                .map_or(0, |decision| decision.record_count),
            index_store,
            plaintext_exposed: false,
        }
    }
}

