pub struct PrototypeMediaDownloadSessionInput<'a> {
    pub download: MediaServiceDownloadInput,
    pub open_seal_request: LocalStoreSealRequest<'a>,
    pub downloaded_ciphertext: &'a [u8],
    pub nonce: &'a [u8],
    pub authentication_tag_len: i32,
    pub store_record_kind: LocalStoreRecordKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PrototypeMediaDownloadSessionOutcome {
    pub completed: bool,
    pub reason: PrototypeMediaDownloadSessionReason,
    pub download: MediaServiceDownloadDecision,
    pub store_write: Option<LocalStoreWriteDecision>,
    pub open: Option<LocalStoreOpenDecision>,
    pub local_store_records: usize,
    pub stored_ciphertext_len: usize,
    pub opened_plaintext_len: usize,
    pub service_download_calls: usize,
    pub crypto_open_calls: usize,
    pub plaintext_exposed: bool,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeMediaDownloadSession {
    local_store: PrototypeEncryptedLocalStore,
    crypto: PrototypeLocalStoreCryptoProvider,
    service_download_calls: usize,
    events: Vec<PrototypeMediaDownloadSessionEvent>,
}

impl PrototypeMediaDownloadSession {
    pub fn run(
        &mut self,
        input: PrototypeMediaDownloadSessionInput<'_>,
    ) -> PrototypeMediaDownloadSessionOutcome {
        self.events.clear();
        self.record_event(
            PrototypeMediaDownloadSessionEventKind::DownloadStarted,
            true,
            false,
            PrototypeMediaDownloadSessionReason::Completed,
        );

        let mut download_input = input.download;
        download_input.ciphertext_len = len_to_i32(input.downloaded_ciphertext.len());
        let download = download_input.evaluate();
        if !download.accepted {
            self.record_event(
                PrototypeMediaDownloadSessionEventKind::MediaServiceDownloadEvaluated,
                false,
                true,
                PrototypeMediaDownloadSessionReason::MediaServiceDownloadRejected,
            );
            return self.outcome(
                PrototypeMediaDownloadSessionReason::MediaServiceDownloadRejected,
                download,
                None,
                None,
                0,
                0,
            );
        }
        self.service_download_calls += 1;
        self.record_event(
            PrototypeMediaDownloadSessionEventKind::MediaServiceDownloadEvaluated,
            true,
            false,
            PrototypeMediaDownloadSessionReason::Completed,
        );

        let store_write = self.local_store.put_record(LocalStoreWriteRequest::new(
            input.open_seal_request.locator,
            input.store_record_kind,
            LocalStorePayload::sealed(input.downloaded_ciphertext),
            input.open_seal_request.policy_decision,
        ));
        if !store_write.accepted {
            self.record_event(
                PrototypeMediaDownloadSessionEventKind::LocalStoreWriteEvaluated,
                false,
                true,
                PrototypeMediaDownloadSessionReason::LocalStoreWriteRejected,
            );
            return self.outcome(
                PrototypeMediaDownloadSessionReason::LocalStoreWriteRejected,
                download,
                Some(store_write),
                None,
                0,
                0,
            );
        }
        self.record_event(
            PrototypeMediaDownloadSessionEventKind::LocalStoreWriteEvaluated,
            true,
            false,
            PrototypeMediaDownloadSessionReason::Completed,
        );

        let open_request = LocalStoreOpenRequest::new(
            input.open_seal_request,
            input.nonce,
            input.downloaded_ciphertext,
            input.authentication_tag_len,
        );
        let open = open_local_store_record(&mut self.crypto, open_request)
            .expect("prototype crypto is infallible");
        let (open_decision, opened_plaintext_len) = match open {
            LocalStoreOpenResult::Opened(bytes) => (open_request.evaluate(), bytes.len()),
            LocalStoreOpenResult::Rejected(decision) => {
                self.record_event(
                    PrototypeMediaDownloadSessionEventKind::LocalStoreOpenEvaluated,
                    false,
                    true,
                    PrototypeMediaDownloadSessionReason::LocalStoreOpenRejected,
                );
                return self.outcome(
                    PrototypeMediaDownloadSessionReason::LocalStoreOpenRejected,
                    download,
                    Some(store_write),
                    Some(decision),
                    self.stored_ciphertext_len(input.open_seal_request.locator),
                    0,
                );
            }
        };
        self.record_event(
            PrototypeMediaDownloadSessionEventKind::LocalStoreOpenEvaluated,
            true,
            false,
            PrototypeMediaDownloadSessionReason::Completed,
        );
        self.record_event(
            PrototypeMediaDownloadSessionEventKind::DownloadFinished,
            true,
            true,
            PrototypeMediaDownloadSessionReason::Completed,
        );

        self.outcome(
            PrototypeMediaDownloadSessionReason::Completed,
            download,
            Some(store_write),
            Some(open_decision),
            self.stored_ciphertext_len(input.open_seal_request.locator),
            opened_plaintext_len,
        )
    }

    pub fn local_store(&self) -> &PrototypeEncryptedLocalStore {
        &self.local_store
    }

    pub fn crypto(&self) -> &PrototypeLocalStoreCryptoProvider {
        &self.crypto
    }

    pub const fn service_download_calls(&self) -> usize {
        self.service_download_calls
    }

    pub fn events(&self) -> &[PrototypeMediaDownloadSessionEvent] {
        &self.events
    }

    fn record_event(
        &mut self,
        kind: PrototypeMediaDownloadSessionEventKind,
        accepted: bool,
        terminal: bool,
        reason: PrototypeMediaDownloadSessionReason,
    ) {
        self.events.push(PrototypeMediaDownloadSessionEvent {
            sequence: self.events.len() as i32,
            kind,
            accepted,
            terminal,
            reason,
            plaintext_bytes_exposed: false,
        });
    }

    fn stored_ciphertext_len(&self, locator: LocalStoreRecordLocator<'_>) -> usize {
        self.local_store
            .get_record(locator)
            .map(|record| record.bytes.len())
            .unwrap_or(0)
    }

    fn outcome(
        &self,
        reason: PrototypeMediaDownloadSessionReason,
        download: MediaServiceDownloadDecision,
        store_write: Option<LocalStoreWriteDecision>,
        open: Option<LocalStoreOpenDecision>,
        stored_ciphertext_len: usize,
        opened_plaintext_len: usize,
    ) -> PrototypeMediaDownloadSessionOutcome {
        PrototypeMediaDownloadSessionOutcome {
            completed: reason == PrototypeMediaDownloadSessionReason::Completed,
            reason,
            download,
            store_write,
            open,
            local_store_records: self.local_store.len(),
            stored_ciphertext_len,
            opened_plaintext_len,
            service_download_calls: self.service_download_calls,
            crypto_open_calls: self.crypto.open_calls(),
            plaintext_exposed: false,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RelaySubmissionInput {
    pub version: i32,
    pub outbound_send: OutboundSendDecision,
    pub route_id_len: i32,
    pub replay_token_len: i32,
    pub queue_ttl_s: i32,
    pub max_queue_ttl_s: i32,
    pub ciphertext_len: i32,
    pub max_ciphertext_len: i32,
    pub sealed_header_len: i32,
    pub plaintext_identity_fields: i32,
    pub padding_bucket: i32,
}

impl RelaySubmissionInput {
    pub const fn into_policy_input(self) -> policy::RelaySubmitInput {
        policy::RelaySubmitInput {
            version: self.version,
            send_gate_reason: relay_send_gate_reason(self.outbound_send),
            route_id_len: self.route_id_len,
            replay_token_len: self.replay_token_len,
            queue_ttl_s: self.queue_ttl_s,
            max_queue_ttl_s: self.max_queue_ttl_s,
            ciphertext_len: self.ciphertext_len,
            max_ciphertext_len: self.max_ciphertext_len,
            sealed_header_len: self.sealed_header_len,
            plaintext_identity_fields: self.plaintext_identity_fields,
            padding_bucket: self.padding_bucket,
        }
    }

    pub fn evaluate(self) -> RelaySubmissionDecision {
        evaluate_relay_submission(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RelaySubmissionDecision {
    pub accepted: bool,
    pub reason_code: i32,
    pub audit_class: i32,
}

pub fn evaluate_relay_submission(input: RelaySubmissionInput) -> RelaySubmissionDecision {
    let reason_code = policy::relay_submit_decide_v1(input.into_policy_input());
    RelaySubmissionDecision {
        accepted: reason_code == policy::RELAY_SUBMIT_ACCEPT,
        reason_code,
        audit_class: policy::relay_submit_audit_class_for_reason(reason_code),
    }
}

const fn relay_send_gate_reason(decision: OutboundSendDecision) -> i32 {
    match (decision.accepted, decision.reason) {
        (true, OutboundSendReason::Accepted) => OutboundSendReason::Accepted.code(),
        (false, OutboundSendReason::Accepted) => OutboundSendReason::MessagePolicyRejected.code(),
        (_, reason) => reason.code(),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RelayQueueOperation {
    Enqueue,
    Deliver,
    Expire,
    Delete,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RelayQueueItemState {
    Absent,
    Pending,
    Delivered,
    Expired,
    Deleted,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RelayQueueReason {
    Accepted,
    RelaySubmissionRejected,
    ReplayTokenDuplicate,
    BadTimeWindow,
    ItemNotQueued,
    ItemAlreadyPending,
    ItemExpired,
    ItemNotExpired,
    ItemAlreadyDelivered,
    ItemAlreadyExpired,
    ItemAlreadyDeleted,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RelayQueueInput {
    pub operation: RelayQueueOperation,
    pub submission: RelaySubmissionDecision,
    pub state: RelayQueueItemState,
    pub replay_token_seen: bool,
    pub created_at_s: i64,
    pub expires_at_s: i64,
    pub now_s: i64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RelayQueueDecision {
    pub accepted: bool,
    pub next_state: RelayQueueItemState,
    pub persist_item: bool,
    pub delete_item: bool,
    pub reason: RelayQueueReason,
}

pub fn evaluate_relay_queue(input: RelayQueueInput) -> RelayQueueDecision {
    if input.created_at_s < 0
        || input.expires_at_s <= input.created_at_s
        || input.now_s < input.created_at_s
    {
        return relay_queue_reject(input.state, RelayQueueReason::BadTimeWindow);
    }

    match input.operation {
        RelayQueueOperation::Enqueue => evaluate_relay_queue_enqueue(input),
        RelayQueueOperation::Deliver => evaluate_relay_queue_deliver(input),
        RelayQueueOperation::Expire => evaluate_relay_queue_expire(input),
        RelayQueueOperation::Delete => evaluate_relay_queue_delete(input),
    }
}

fn evaluate_relay_queue_enqueue(input: RelayQueueInput) -> RelayQueueDecision {
    match input.state {
        // A free slot — or one whose previous item is already TERMINAL (Delivered / Expired /
        // Deleted = the previous message is DONE) — accepts the next message, so a route stays
        // REUSABLE for an ongoing conversation. Overwriting a terminal record is safe: its
        // ciphertext was already cleared at the terminal transition, and replay protection is a
        // SEPARATE replay-token table (see `replay_token_seen` / the relay's replay store),
        // untouched by reusing the route slot. Only a still-`Pending` item blocks — genuine
        // single-slot backpressure, because the recipient has not drained the previous message
        // yet.
        //
        // (Before this fix, ANY non-`Absent` state rejected the enqueue, and terminal records are
        // reaped only `TERMINAL_RETENTION_S` — seven days — after expiry. So a route went dead for
        // ~7 days after its first delivered message, breaking every conversation past the first
        // round-trip. The in-memory transport double models no queue state, so the defect was
        // invisible to the test suite and surfaced only in a real multi-message exchange over the
        // live relay.)
        RelayQueueItemState::Absent
        | RelayQueueItemState::Delivered
        | RelayQueueItemState::Expired
        | RelayQueueItemState::Deleted => {}
        RelayQueueItemState::Pending => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyPending);
        }
    }

    if !input.submission.accepted {
        return relay_queue_reject(input.state, RelayQueueReason::RelaySubmissionRejected);
    }

    if input.replay_token_seen {
        return relay_queue_reject(input.state, RelayQueueReason::ReplayTokenDuplicate);
    }

    if input.now_s >= input.expires_at_s {
        return relay_queue_reject(input.state, RelayQueueReason::ItemExpired);
    }

    relay_queue_accept(RelayQueueItemState::Pending, true, false)
}

fn evaluate_relay_queue_deliver(input: RelayQueueInput) -> RelayQueueDecision {
    match input.state {
        RelayQueueItemState::Absent => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemNotQueued);
        }
        RelayQueueItemState::Pending => {}
        RelayQueueItemState::Delivered => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyDelivered);
        }
        RelayQueueItemState::Expired => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyExpired);
        }
        RelayQueueItemState::Deleted => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyDeleted);
        }
    }

    if input.now_s >= input.expires_at_s {
        return relay_queue_reject(input.state, RelayQueueReason::ItemExpired);
    }

    relay_queue_accept(RelayQueueItemState::Delivered, false, true)
}

fn evaluate_relay_queue_expire(input: RelayQueueInput) -> RelayQueueDecision {
    match input.state {
        RelayQueueItemState::Absent => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemNotQueued);
        }
        RelayQueueItemState::Pending => {}
        RelayQueueItemState::Delivered => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyDelivered);
        }
        RelayQueueItemState::Expired => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyExpired);
        }
        RelayQueueItemState::Deleted => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyDeleted);
        }
    }

    if input.now_s < input.expires_at_s {
        return relay_queue_reject(input.state, RelayQueueReason::ItemNotExpired);
    }

    relay_queue_accept(RelayQueueItemState::Expired, false, true)
}

fn evaluate_relay_queue_delete(input: RelayQueueInput) -> RelayQueueDecision {
    match input.state {
        RelayQueueItemState::Absent => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemNotQueued);
        }
        RelayQueueItemState::Deleted => {
            return relay_queue_reject(input.state, RelayQueueReason::ItemAlreadyDeleted);
        }
        RelayQueueItemState::Pending
        | RelayQueueItemState::Delivered
        | RelayQueueItemState::Expired => {}
    }

    relay_queue_accept(RelayQueueItemState::Deleted, false, true)
}

const fn relay_queue_accept(
    next_state: RelayQueueItemState,
    persist_item: bool,
    delete_item: bool,
) -> RelayQueueDecision {
    RelayQueueDecision {
        accepted: true,
        next_state,
        persist_item,
        delete_item,
        reason: RelayQueueReason::Accepted,
    }
}

const fn relay_queue_reject(
    next_state: RelayQueueItemState,
    reason: RelayQueueReason,
) -> RelayQueueDecision {
    RelayQueueDecision {
        accepted: false,
        next_state,
        persist_item: false,
        delete_item: false,
        reason,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PrototypeRelaySubmitRequest<'a> {
    pub outbound_send: OutboundSendDecision,
    pub route_id: &'a [u8],
    pub replay_token: &'a [u8],
    pub queue_ttl_s: i32,
    pub max_queue_ttl_s: i32,
    pub ciphertext: &'a [u8],
    pub max_ciphertext_len: i32,
    pub sealed_header: &'a [u8],
    pub plaintext_identity_fields: i32,
    pub padding_bucket: i32,
    pub created_at_s: i64,
    pub now_s: i64,
}

impl<'a> PrototypeRelaySubmitRequest<'a> {
    pub const fn new(
        outbound_send: OutboundSendDecision,
        route_id: &'a [u8],
        replay_token: &'a [u8],
        queue_ttl_s: i32,
        max_queue_ttl_s: i32,
        ciphertext: &'a [u8],
        max_ciphertext_len: i32,
        sealed_header: &'a [u8],
        plaintext_identity_fields: i32,
        padding_bucket: i32,
        created_at_s: i64,
        now_s: i64,
    ) -> Self {
        Self {
            outbound_send,
            route_id,
            replay_token,
            queue_ttl_s,
            max_queue_ttl_s,
            ciphertext,
            max_ciphertext_len,
            sealed_header,
            plaintext_identity_fields,
            padding_bucket,
            created_at_s,
            now_s,
        }
    }

    pub fn submission_input(self) -> RelaySubmissionInput {
        RelaySubmissionInput {
            version: 1,
            outbound_send: self.outbound_send,
            route_id_len: len_to_i32(self.route_id.len()),
            replay_token_len: len_to_i32(self.replay_token.len()),
            queue_ttl_s: self.queue_ttl_s,
            max_queue_ttl_s: self.max_queue_ttl_s,
            ciphertext_len: len_to_i32(self.ciphertext.len()),
            max_ciphertext_len: self.max_ciphertext_len,
            sealed_header_len: len_to_i32(self.sealed_header.len()),
            plaintext_identity_fields: self.plaintext_identity_fields,
            padding_bucket: self.padding_bucket,
        }
    }

    pub const fn expires_at_s(self) -> i64 {
        self.created_at_s.saturating_add(self.queue_ttl_s as i64)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PrototypeRelaySubmitOutcome {
    pub submission: RelaySubmissionDecision,
    pub queue: RelayQueueDecision,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PrototypeRelayDelivery {
    pub queue: RelayQueueDecision,
    pub ciphertext: Vec<u8>,
    pub sealed_header: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PrototypeRelayQueueItem {
    pub route_id: Vec<u8>,
    pub replay_token: Vec<u8>,
    pub state: RelayQueueItemState,
    pub created_at_s: i64,
    pub expires_at_s: i64,
    pub padding_bucket: i32,
    pub submission: RelaySubmissionDecision,
    ciphertext: Vec<u8>,
    sealed_header: Vec<u8>,
}

impl PrototypeRelayQueueItem {
    pub fn has_ciphertext(&self) -> bool {
        !self.ciphertext.is_empty()
    }

    pub fn ciphertext_len(&self) -> usize {
        self.ciphertext.len()
    }

    pub fn sealed_header_len(&self) -> usize {
        self.sealed_header.len()
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeRelayServer {
    items: BTreeMap<Vec<u8>, PrototypeRelayQueueItem>,
    replay_tokens: BTreeSet<Vec<u8>>,
}

impl PrototypeRelayServer {
    pub fn submit(
        &mut self,
        request: PrototypeRelaySubmitRequest<'_>,
    ) -> PrototypeRelaySubmitOutcome {
        let submission = request.submission_input().evaluate();
        let state = self
            .items
            .get(&request.route_id.to_vec())
            .map(|item| item.state)
            .unwrap_or(RelayQueueItemState::Absent);
        let queue = evaluate_relay_queue(RelayQueueInput {
            operation: RelayQueueOperation::Enqueue,
            submission,
            state,
            replay_token_seen: self.replay_tokens.contains(&request.replay_token.to_vec()),
            created_at_s: request.created_at_s,
            expires_at_s: request.expires_at_s(),
            now_s: request.now_s,
        });

        if queue.accepted && queue.persist_item {
            self.replay_tokens.insert(request.replay_token.to_vec());
            self.items.insert(
                request.route_id.to_vec(),
                PrototypeRelayQueueItem {
                    route_id: request.route_id.to_vec(),
                    replay_token: request.replay_token.to_vec(),
                    state: queue.next_state,
                    created_at_s: request.created_at_s,
                    expires_at_s: request.expires_at_s(),
                    padding_bucket: request.padding_bucket,
                    submission,
                    ciphertext: request.ciphertext.to_vec(),
                    sealed_header: request.sealed_header.to_vec(),
                },
            );
        }

        PrototypeRelaySubmitOutcome { submission, queue }
    }

    pub fn deliver(&mut self, route_id: &[u8], now_s: i64) -> PrototypeRelayDelivery {
        let Some(item) = self.items.get_mut(&route_id.to_vec()) else {
            return PrototypeRelayDelivery {
                queue: prototype_absent_queue_decision(RelayQueueOperation::Deliver, now_s),
                ciphertext: Vec::new(),
                sealed_header: Vec::new(),
            };
        };

        let queue = prototype_queue_decision(item, RelayQueueOperation::Deliver, now_s);
        if queue.accepted {
            item.state = queue.next_state;
            return PrototypeRelayDelivery {
                queue,
                ciphertext: std::mem::take(&mut item.ciphertext),
                sealed_header: std::mem::take(&mut item.sealed_header),
            };
        }

        PrototypeRelayDelivery {
            queue,
            ciphertext: Vec::new(),
            sealed_header: Vec::new(),
        }
    }

    pub fn expire(&mut self, route_id: &[u8], now_s: i64) -> RelayQueueDecision {
        let Some(item) = self.items.get_mut(&route_id.to_vec()) else {
            return prototype_absent_queue_decision(RelayQueueOperation::Expire, now_s);
        };

        let queue = prototype_queue_decision(item, RelayQueueOperation::Expire, now_s);
        if queue.accepted {
            item.state = queue.next_state;
            item.ciphertext.clear();
            item.sealed_header.clear();
        }
        queue
    }

    pub fn delete(&mut self, route_id: &[u8], now_s: i64) -> RelayQueueDecision {
        let Some(item) = self.items.get_mut(&route_id.to_vec()) else {
            return prototype_absent_queue_decision(RelayQueueOperation::Delete, now_s);
        };

        let queue = prototype_queue_decision(item, RelayQueueOperation::Delete, now_s);
        if queue.accepted {
            item.state = queue.next_state;
            item.ciphertext.clear();
            item.sealed_header.clear();
        }
        queue
    }

    pub fn get_item(&self, route_id: &[u8]) -> Option<&PrototypeRelayQueueItem> {
        self.items.get(&route_id.to_vec())
    }

    pub fn len(&self) -> usize {
        self.items.len()
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }
}

fn prototype_queue_decision(
    item: &PrototypeRelayQueueItem,
    operation: RelayQueueOperation,
    now_s: i64,
) -> RelayQueueDecision {
    evaluate_relay_queue(RelayQueueInput {
        operation,
        submission: item.submission,
        state: item.state,
        replay_token_seen: true,
        created_at_s: item.created_at_s,
        expires_at_s: item.expires_at_s,
        now_s,
    })
}

fn prototype_absent_queue_decision(
    operation: RelayQueueOperation,
    now_s: i64,
) -> RelayQueueDecision {
    evaluate_relay_queue(RelayQueueInput {
        operation,
        submission: RelaySubmissionDecision {
            accepted: true,
            reason_code: policy::RELAY_SUBMIT_ACCEPT,
            audit_class: policy::relay_submit_audit_class_for_reason(policy::RELAY_SUBMIT_ACCEPT),
        },
        state: RelayQueueItemState::Absent,
        replay_token_seen: false,
        created_at_s: 0,
        expires_at_s: 1,
        now_s,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PrototypeBackendSessionReason {
    Completed,
    BootstrapBlocked,
    LocalStoreSealRejected,
    LocalStoreWriteRejected,
    RelaySubmitRejected,
    RelayDeliveryRejected,
    LocalStoreOpenRejected,
    AiParticipantRejected,
}

impl PrototypeBackendSessionReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::Completed => 0,
            Self::BootstrapBlocked => 1,
            Self::LocalStoreSealRejected => 2,
            Self::LocalStoreWriteRejected => 3,
            Self::RelaySubmitRejected => 4,
            Self::RelayDeliveryRejected => 5,
            Self::LocalStoreOpenRejected => 6,
            Self::AiParticipantRejected => 7,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Completed => "completed",
            Self::BootstrapBlocked => "bootstrap_blocked",
            Self::LocalStoreSealRejected => "local_store_seal_rejected",
            Self::LocalStoreWriteRejected => "local_store_write_rejected",
            Self::RelaySubmitRejected => "relay_submit_rejected",
            Self::RelayDeliveryRejected => "relay_delivery_rejected",
            Self::LocalStoreOpenRejected => "local_store_open_rejected",
            Self::AiParticipantRejected => "ai_participant_rejected",
        }
    }
}

