#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeReceiveSession {
    local_store: PrototypeEncryptedLocalStore,
    relay: PrototypeRelayServer,
    events: Vec<PrototypeReceiveSessionEvent>,
}

impl PrototypeReceiveSession {
    pub fn run(
        &mut self,
        input: PrototypeReceiveSessionInput<'_>,
    ) -> PrototypeReceiveSessionOutcome {
        self.events.clear();
        self.record_event(
            PrototypeReceiveSessionEventKind::ReceiveStarted,
            true,
            false,
            PrototypeReceiveSessionReason::Completed,
        );

        let submit = self.relay.submit(input.relay_submit);
        if !submit.submission.accepted || !submit.queue.accepted {
            self.record_event(
                PrototypeReceiveSessionEventKind::RelaySubmitEvaluated,
                false,
                true,
                PrototypeReceiveSessionReason::RelaySubmitRejected,
            );
            return self.outcome(
                PrototypeReceiveSessionReason::RelaySubmitRejected,
                submit.submission,
                submit.queue,
                None,
                None,
                None,
                None,
                0,
                0,
            );
        }
        self.record_event(
            PrototypeReceiveSessionEventKind::RelaySubmitEvaluated,
            true,
            false,
            PrototypeReceiveSessionReason::Completed,
        );

        let delivery = self
            .relay
            .deliver(input.relay_submit.route_id, input.delivery_now_s);
        let delivered_ciphertext_len = delivery.ciphertext.len();
        let delivered_sealed_header_len = delivery.sealed_header.len();
        if !delivery.queue.accepted {
            self.record_event(
                PrototypeReceiveSessionEventKind::RelayDeliveryEvaluated,
                false,
                true,
                PrototypeReceiveSessionReason::RelayDeliveryRejected,
            );
            return self.outcome(
                PrototypeReceiveSessionReason::RelayDeliveryRejected,
                submit.submission,
                submit.queue,
                Some(delivery.queue),
                None,
                None,
                None,
                delivered_ciphertext_len,
                delivered_sealed_header_len,
            );
        }
        self.record_event(
            PrototypeReceiveSessionEventKind::RelayDeliveryEvaluated,
            true,
            false,
            PrototypeReceiveSessionReason::Completed,
        );

        let ack = evaluate_delivery_ack(DeliveryAckInput {
            queue_state: delivery.queue.next_state,
            ack_seen: input.ack_seen,
            delivered_at_s: input.delivery_now_s,
            acknowledged_at_s: input.acknowledged_at_s,
            max_ack_delay_s: input.max_ack_delay_s,
            ack_token_len: input.ack_token_len,
            ciphertext_digest_len: input.ciphertext_digest_len,
            delivery_tag_len: input.delivery_tag_len,
            plaintext_identity_fields: input.plaintext_identity_fields,
        });

        if !ack.accepted {
            self.record_event(
                PrototypeReceiveSessionEventKind::DeliveryAckEvaluated,
                false,
                true,
                PrototypeReceiveSessionReason::DeliveryAckRejected,
            );
            return self.outcome(
                PrototypeReceiveSessionReason::DeliveryAckRejected,
                submit.submission,
                submit.queue,
                Some(delivery.queue),
                Some(ack),
                None,
                None,
                delivered_ciphertext_len,
                delivered_sealed_header_len,
            );
        }
        self.record_event(
            PrototypeReceiveSessionEventKind::DeliveryAckEvaluated,
            true,
            false,
            PrototypeReceiveSessionReason::Completed,
        );

        let receive = evaluate_client_receive(ClientReceiveInput::new(
            delivery.queue,
            ack,
            input.sender_device_trust,
            input.message_policy,
            input.ciphertext_sealing,
            input.receive_replay_state,
            input.ciphertext_digest_len,
            input.plaintext_identity_fields,
        ));

        if !receive.accepted {
            self.record_event(
                PrototypeReceiveSessionEventKind::ClientReceiveEvaluated,
                false,
                true,
                PrototypeReceiveSessionReason::ClientReceiveRejected,
            );
            return self.outcome(
                PrototypeReceiveSessionReason::ClientReceiveRejected,
                submit.submission,
                submit.queue,
                Some(delivery.queue),
                Some(ack),
                Some(receive),
                None,
                delivered_ciphertext_len,
                delivered_sealed_header_len,
            );
        }
        self.record_event(
            PrototypeReceiveSessionEventKind::ClientReceiveEvaluated,
            true,
            false,
            PrototypeReceiveSessionReason::Completed,
        );

        let write = self.local_store.put_record(LocalStoreWriteRequest::new(
            input.store_locator,
            input.store_record_kind,
            LocalStorePayload::sealed(&delivery.ciphertext),
            Some(input.message_policy),
        ));

        if !write.accepted {
            self.record_event(
                PrototypeReceiveSessionEventKind::LocalStoreWriteEvaluated,
                false,
                true,
                PrototypeReceiveSessionReason::LocalStoreWriteRejected,
            );
            return self.outcome(
                PrototypeReceiveSessionReason::LocalStoreWriteRejected,
                submit.submission,
                submit.queue,
                Some(delivery.queue),
                Some(ack),
                Some(receive),
                Some(write),
                delivered_ciphertext_len,
                delivered_sealed_header_len,
            );
        }
        self.record_event(
            PrototypeReceiveSessionEventKind::LocalStoreWriteEvaluated,
            true,
            false,
            PrototypeReceiveSessionReason::Completed,
        );
        self.record_event(
            PrototypeReceiveSessionEventKind::ReceiveFinished,
            true,
            true,
            PrototypeReceiveSessionReason::Completed,
        );

        self.outcome(
            PrototypeReceiveSessionReason::Completed,
            submit.submission,
            submit.queue,
            Some(delivery.queue),
            Some(ack),
            Some(receive),
            Some(write),
            delivered_ciphertext_len,
            delivered_sealed_header_len,
        )
    }

    pub fn local_store(&self) -> &PrototypeEncryptedLocalStore {
        &self.local_store
    }

    pub fn relay(&self) -> &PrototypeRelayServer {
        &self.relay
    }

    pub fn events(&self) -> &[PrototypeReceiveSessionEvent] {
        &self.events
    }

    fn record_event(
        &mut self,
        kind: PrototypeReceiveSessionEventKind,
        accepted: bool,
        terminal: bool,
        reason: PrototypeReceiveSessionReason,
    ) {
        self.events.push(PrototypeReceiveSessionEvent {
            sequence: self.events.len() as i32,
            kind,
            accepted,
            terminal,
            reason,
            plaintext_bytes_exposed: false,
        });
    }

    fn outcome(
        &self,
        reason: PrototypeReceiveSessionReason,
        relay_submission: RelaySubmissionDecision,
        relay_queue: RelayQueueDecision,
        relay_delivery: Option<RelayQueueDecision>,
        delivery_ack: Option<DeliveryAckDecision>,
        client_receive: Option<ClientReceiveDecision>,
        store_write: Option<LocalStoreWriteDecision>,
        delivered_ciphertext_len: usize,
        delivered_sealed_header_len: usize,
    ) -> PrototypeReceiveSessionOutcome {
        PrototypeReceiveSessionOutcome {
            completed: reason == PrototypeReceiveSessionReason::Completed,
            reason,
            relay_submission,
            relay_queue,
            relay_delivery,
            delivery_ack,
            client_receive,
            store_write,
            local_store_records: self.local_store.len(),
            relay_items: self.relay.len(),
            delivered_ciphertext_len,
            delivered_sealed_header_len,
            plaintext_exposed: false,
        }
    }
}

