pub enum LocalStoreUnlockSecretState {
    PresentSealed,
    Missing,
    Corrupt,
    PlaintextPresent,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LocalStoreUnlockDatabaseHeaderState {
    Authenticated,
    Missing,
    Corrupt,
    AuthenticationFailed,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LocalStoreUnlockReason {
    Accepted,
    UnsupportedStoreVersion,
    PlaintextCacheForbidden,
    RecoveryRequired,
    KeychainUnavailable,
    DeviceSecretMissing,
    DeviceSecretCorrupt,
    PlaintextSecretForbidden,
    DatabaseHeaderMissing,
    DatabaseHeaderCorrupt,
    DatabaseHeaderAuthenticationFailed,
    AppLockRequired,
}

impl LocalStoreUnlockReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::Accepted => 0,
            Self::UnsupportedStoreVersion => 1,
            Self::PlaintextCacheForbidden => 2,
            Self::RecoveryRequired => 3,
            Self::KeychainUnavailable => 4,
            Self::DeviceSecretMissing => 5,
            Self::DeviceSecretCorrupt => 6,
            Self::PlaintextSecretForbidden => 7,
            Self::DatabaseHeaderMissing => 8,
            Self::DatabaseHeaderCorrupt => 9,
            Self::DatabaseHeaderAuthenticationFailed => 10,
            Self::AppLockRequired => 11,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Accepted => "ACCEPTED",
            Self::UnsupportedStoreVersion => "UNSUPPORTED_STORE_VERSION",
            Self::PlaintextCacheForbidden => "PLAINTEXT_CACHE_FORBIDDEN",
            Self::RecoveryRequired => "RECOVERY_REQUIRED",
            Self::KeychainUnavailable => "KEYCHAIN_UNAVAILABLE",
            Self::DeviceSecretMissing => "DEVICE_SECRET_MISSING",
            Self::DeviceSecretCorrupt => "DEVICE_SECRET_CORRUPT",
            Self::PlaintextSecretForbidden => "PLAINTEXT_SECRET_FORBIDDEN",
            Self::DatabaseHeaderMissing => "DATABASE_HEADER_MISSING",
            Self::DatabaseHeaderCorrupt => "DATABASE_HEADER_CORRUPT",
            Self::DatabaseHeaderAuthenticationFailed => "DATABASE_HEADER_AUTHENTICATION_FAILED",
            Self::AppLockRequired => "APP_LOCK_REQUIRED",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreUnlockInput {
    pub store_version: i32,
    pub keychain_available: bool,
    pub device_secret: LocalStoreUnlockSecretState,
    pub database_header: LocalStoreUnlockDatabaseHeaderState,
    pub app_lock_satisfied: bool,
    pub recovery_required: bool,
    pub plaintext_cache_records: i32,
}

impl LocalStoreUnlockInput {
    pub fn evaluate(self) -> LocalStoreUnlockDecision {
        evaluate_local_store_unlock(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreUnlockDecision {
    pub accepted: bool,
    pub can_open_database: bool,
    pub can_unseal_device_secret: bool,
    pub can_load_message_keys: bool,
    pub requires_user_auth: bool,
    pub requires_recovery: bool,
    pub requires_migration: bool,
    pub requires_destructive_repair: bool,
    pub reason: LocalStoreUnlockReason,
}

pub fn evaluate_local_store_unlock(input: LocalStoreUnlockInput) -> LocalStoreUnlockDecision {
    if input.store_version != MERCURY_LOCAL_STORE_VERSION {
        return local_store_unlock_reject(
            LocalStoreUnlockReason::UnsupportedStoreVersion,
            false,
            false,
            true,
            false,
        );
    }

    if input.plaintext_cache_records != 0 {
        return local_store_unlock_reject(
            LocalStoreUnlockReason::PlaintextCacheForbidden,
            false,
            false,
            false,
            true,
        );
    }

    if input.recovery_required {
        return local_store_unlock_reject(
            LocalStoreUnlockReason::RecoveryRequired,
            false,
            true,
            false,
            false,
        );
    }

    if !input.keychain_available {
        return local_store_unlock_reject(
            LocalStoreUnlockReason::KeychainUnavailable,
            true,
            false,
            false,
            false,
        );
    }

    match input.device_secret {
        LocalStoreUnlockSecretState::PresentSealed => {}
        LocalStoreUnlockSecretState::Missing => {
            return local_store_unlock_reject(
                LocalStoreUnlockReason::DeviceSecretMissing,
                false,
                true,
                false,
                false,
            );
        }
        LocalStoreUnlockSecretState::Corrupt => {
            return local_store_unlock_reject(
                LocalStoreUnlockReason::DeviceSecretCorrupt,
                false,
                true,
                false,
                false,
            );
        }
        LocalStoreUnlockSecretState::PlaintextPresent => {
            return local_store_unlock_reject(
                LocalStoreUnlockReason::PlaintextSecretForbidden,
                false,
                false,
                false,
                true,
            );
        }
    }

    match input.database_header {
        LocalStoreUnlockDatabaseHeaderState::Authenticated => {}
        LocalStoreUnlockDatabaseHeaderState::Missing => {
            return local_store_unlock_reject(
                LocalStoreUnlockReason::DatabaseHeaderMissing,
                false,
                true,
                false,
                false,
            );
        }
        LocalStoreUnlockDatabaseHeaderState::Corrupt => {
            return local_store_unlock_reject(
                LocalStoreUnlockReason::DatabaseHeaderCorrupt,
                false,
                false,
                false,
                true,
            );
        }
        LocalStoreUnlockDatabaseHeaderState::AuthenticationFailed => {
            return local_store_unlock_reject(
                LocalStoreUnlockReason::DatabaseHeaderAuthenticationFailed,
                true,
                false,
                false,
                false,
            );
        }
    }

    if !input.app_lock_satisfied {
        return local_store_unlock_reject(
            LocalStoreUnlockReason::AppLockRequired,
            true,
            false,
            false,
            false,
        );
    }

    LocalStoreUnlockDecision {
        accepted: true,
        can_open_database: true,
        can_unseal_device_secret: true,
        can_load_message_keys: true,
        requires_user_auth: false,
        requires_recovery: false,
        requires_migration: false,
        requires_destructive_repair: false,
        reason: LocalStoreUnlockReason::Accepted,
    }
}

const fn local_store_unlock_reject(
    reason: LocalStoreUnlockReason,
    requires_user_auth: bool,
    requires_recovery: bool,
    requires_migration: bool,
    requires_destructive_repair: bool,
) -> LocalStoreUnlockDecision {
    LocalStoreUnlockDecision {
        accepted: false,
        can_open_database: false,
        can_unseal_device_secret: false,
        can_load_message_keys: false,
        requires_user_auth,
        requires_recovery,
        requires_migration,
        requires_destructive_repair,
        reason,
    }
}

