#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreProductionOpenInput {
    pub unlock: LocalStoreUnlockInput,
    pub header_magic_matches: bool,
    pub header_suite_code: i32,
    pub header_nonce_len: i32,
    pub header_tag_len: i32,
    pub required_key_slots: i32,
    pub sealed_key_slots: i32,
    pub plaintext_key_slots: i32,
    pub root_key_scope: LocalStoreKeyScope,
    pub root_key_generation: i32,
    pub crash_recovery: LocalStoreCrashRecoveryState,
}

impl LocalStoreProductionOpenInput {
    pub fn evaluate(self) -> LocalStoreProductionOpenDecision {
        evaluate_local_store_production_open(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreProductionOpenDecision {
    pub accepted: bool,
    pub can_open_database: bool,
    pub can_replay_wal: bool,
    pub can_load_records: bool,
    pub can_load_message_keys: bool,
    pub requires_user_auth: bool,
    pub requires_recovery: bool,
    pub requires_migration: bool,
    pub requires_crash_recovery: bool,
    pub requires_destructive_repair: bool,
    pub reason: LocalStoreProductionOpenReason,
    pub unlock_decision: LocalStoreUnlockDecision,
}

pub fn evaluate_local_store_production_open(
    input: LocalStoreProductionOpenInput,
) -> LocalStoreProductionOpenDecision {
    let unlock_decision = input.unlock.evaluate();
    if !unlock_decision.accepted {
        return local_store_production_unlock_reject(unlock_decision);
    }

    if !input.header_magic_matches {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::HeaderMagicMismatch,
            false,
            false,
            false,
            true,
        );
    }

    if LocalStoreSealingSuite::from_code(input.header_suite_code)
        != Some(LocalStoreSealingSuite::MercuryLocalStoreV1)
    {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::HeaderSuiteMismatch,
            false,
            false,
            true,
            false,
        );
    }

    let suite = LocalStoreSealingSuite::MercuryLocalStoreV1;
    if input.header_nonce_len != suite.nonce_len() {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::BadHeaderNonceLength,
            false,
            false,
            false,
            true,
        );
    }

    if input.header_tag_len != suite.authentication_tag_len() {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::BadHeaderTagLength,
            false,
            false,
            false,
            true,
        );
    }

    if input.plaintext_key_slots != 0 {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::PlaintextKeySlotForbidden,
            false,
            false,
            false,
            true,
        );
    }

    if input.required_key_slots <= 0 || input.sealed_key_slots < input.required_key_slots {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::KeySlotMissing,
            false,
            true,
            false,
            false,
        );
    }

    if input.root_key_scope != LocalStoreKeyScope::DeviceLocal {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::RootKeyScopeMismatch,
            false,
            false,
            false,
            true,
        );
    }

    if input.root_key_generation <= 0 {
        return local_store_production_reject(
            unlock_decision,
            LocalStoreProductionOpenReason::RootKeyGenerationInvalid,
            false,
            false,
            false,
            true,
        );
    }

    match input.crash_recovery {
        LocalStoreCrashRecoveryState::Clean => {}
        LocalStoreCrashRecoveryState::WalReplayRequired => {
            return LocalStoreProductionOpenDecision {
                accepted: false,
                can_open_database: false,
                can_replay_wal: true,
                can_load_records: false,
                can_load_message_keys: false,
                requires_user_auth: false,
                requires_recovery: false,
                requires_migration: false,
                requires_crash_recovery: true,
                requires_destructive_repair: false,
                reason: LocalStoreProductionOpenReason::WalReplayRequired,
                unlock_decision,
            };
        }
        LocalStoreCrashRecoveryState::DirtyWithoutWal => {
            return local_store_production_reject(
                unlock_decision,
                LocalStoreProductionOpenReason::DirtyShutdownWithoutWal,
                false,
                false,
                false,
                true,
            );
        }
        LocalStoreCrashRecoveryState::ReplayFailed => {
            return local_store_production_reject(
                unlock_decision,
                LocalStoreProductionOpenReason::WalReplayFailed,
                false,
                false,
                false,
                true,
            );
        }
    }

    LocalStoreProductionOpenDecision {
        accepted: true,
        can_open_database: true,
        can_replay_wal: false,
        can_load_records: true,
        can_load_message_keys: true,
        requires_user_auth: false,
        requires_recovery: false,
        requires_migration: false,
        requires_crash_recovery: false,
        requires_destructive_repair: false,
        reason: LocalStoreProductionOpenReason::Accepted,
        unlock_decision,
    }
}

const fn local_store_production_unlock_reject(
    unlock_decision: LocalStoreUnlockDecision,
) -> LocalStoreProductionOpenDecision {
    LocalStoreProductionOpenDecision {
        accepted: false,
        can_open_database: false,
        can_replay_wal: false,
        can_load_records: false,
        can_load_message_keys: false,
        requires_user_auth: unlock_decision.requires_user_auth,
        requires_recovery: unlock_decision.requires_recovery,
        requires_migration: unlock_decision.requires_migration,
        requires_crash_recovery: false,
        requires_destructive_repair: unlock_decision.requires_destructive_repair,
        reason: LocalStoreProductionOpenReason::UnlockRejected,
        unlock_decision,
    }
}

const fn local_store_production_reject(
    unlock_decision: LocalStoreUnlockDecision,
    reason: LocalStoreProductionOpenReason,
    requires_crash_recovery: bool,
    requires_recovery: bool,
    requires_migration: bool,
    requires_destructive_repair: bool,
) -> LocalStoreProductionOpenDecision {
    LocalStoreProductionOpenDecision {
        accepted: false,
        can_open_database: false,
        can_replay_wal: requires_crash_recovery,
        can_load_records: false,
        can_load_message_keys: false,
        requires_user_auth: false,
        requires_recovery,
        requires_migration,
        requires_crash_recovery,
        requires_destructive_repair,
        reason,
        unlock_decision,
    }
}

