#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreKeychainUnlockInput {
    pub store_version: i32,
    pub backend: LocalStoreKeychainBackend,
    pub backend_available: bool,
    pub protection: LocalStoreKeychainProtection,
    pub allow_development_backend: bool,
    pub user_auth_required: bool,
    pub user_auth_satisfied: bool,
    pub device_secret: LocalStoreUnlockSecretState,
    pub device_secret_exportable: bool,
    pub database_header: LocalStoreUnlockDatabaseHeaderState,
    pub recovery_required: bool,
    pub plaintext_cache_records: i32,
}

impl LocalStoreKeychainUnlockInput {
    pub fn evaluate(self) -> LocalStoreKeychainUnlockDecision {
        evaluate_local_store_keychain_unlock(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreKeychainUnlockDecision {
    pub accepted: bool,
    pub can_build_unlock_input: bool,
    pub requires_user_auth: bool,
    pub requires_recovery: bool,
    pub requires_destructive_repair: bool,
    pub backend_code: i32,
    pub backend_label: &'static str,
    pub protection_code: i32,
    pub protection_label: &'static str,
    pub reason: LocalStoreKeychainReason,
    pub unlock_input: LocalStoreUnlockInput,
}

pub fn evaluate_local_store_keychain_unlock(
    input: LocalStoreKeychainUnlockInput,
) -> LocalStoreKeychainUnlockDecision {
    let unlock_input = LocalStoreUnlockInput {
        store_version: input.store_version,
        keychain_available: input.backend_available,
        device_secret: input.device_secret,
        database_header: input.database_header,
        app_lock_satisfied: !input.user_auth_required || input.user_auth_satisfied,
        recovery_required: input.recovery_required,
        plaintext_cache_records: input.plaintext_cache_records,
    };

    if !input.backend_available {
        return local_store_keychain_reject(
            input,
            unlock_input,
            LocalStoreKeychainReason::BackendUnavailable,
            true,
            false,
            false,
        );
    }

    if (input.backend == LocalStoreKeychainBackend::DevelopmentMemory
        || input.protection == LocalStoreKeychainProtection::DevelopmentOnly)
        && !input.allow_development_backend
    {
        return local_store_keychain_reject(
            input,
            unlock_input,
            LocalStoreKeychainReason::DevelopmentBackendForbidden,
            false,
            false,
            true,
        );
    }

    if input.device_secret_exportable {
        return local_store_keychain_reject(
            input,
            unlock_input,
            LocalStoreKeychainReason::ExportableSecretForbidden,
            false,
            false,
            true,
        );
    }

    match input.device_secret {
        LocalStoreUnlockSecretState::PresentSealed => {}
        LocalStoreUnlockSecretState::Missing => {
            return local_store_keychain_reject(
                input,
                unlock_input,
                LocalStoreKeychainReason::DeviceSecretMissing,
                false,
                true,
                false,
            );
        }
        LocalStoreUnlockSecretState::Corrupt => {
            return local_store_keychain_reject(
                input,
                unlock_input,
                LocalStoreKeychainReason::DeviceSecretCorrupt,
                false,
                true,
                false,
            );
        }
        LocalStoreUnlockSecretState::PlaintextPresent => {
            return local_store_keychain_reject(
                input,
                unlock_input,
                LocalStoreKeychainReason::PlaintextSecretForbidden,
                false,
                false,
                true,
            );
        }
    }

    if input.user_auth_required && !input.user_auth_satisfied {
        return local_store_keychain_reject(
            input,
            unlock_input,
            LocalStoreKeychainReason::UserAuthRequired,
            true,
            false,
            false,
        );
    }

    LocalStoreKeychainUnlockDecision {
        accepted: true,
        can_build_unlock_input: true,
        requires_user_auth: false,
        requires_recovery: false,
        requires_destructive_repair: false,
        backend_code: input.backend.code(),
        backend_label: input.backend.label(),
        protection_code: input.protection.code(),
        protection_label: input.protection.label(),
        reason: LocalStoreKeychainReason::Accepted,
        unlock_input,
    }
}

const fn local_store_keychain_reject(
    input: LocalStoreKeychainUnlockInput,
    unlock_input: LocalStoreUnlockInput,
    reason: LocalStoreKeychainReason,
    requires_user_auth: bool,
    requires_recovery: bool,
    requires_destructive_repair: bool,
) -> LocalStoreKeychainUnlockDecision {
    LocalStoreKeychainUnlockDecision {
        accepted: false,
        can_build_unlock_input: false,
        requires_user_auth,
        requires_recovery,
        requires_destructive_repair,
        backend_code: input.backend.code(),
        backend_label: input.backend.label(),
        protection_code: input.protection.code(),
        protection_label: input.protection.label(),
        reason,
        unlock_input,
    }
}

