pub trait ProductionLocalStoreAdapter: EncryptedLocalStoreAdapter {
    fn open_database(&mut self, open: AcceptedLocalStoreProductionOpen) -> Result<(), Self::Error>;

    fn replay_wal(&mut self, replay: AcceptedLocalStoreWalReplay) -> Result<(), Self::Error>;

    fn read_record(
        &self,
        locator: LocalStoreRecordLocator<'_>,
    ) -> Result<Option<LocalStoreReadRecord>, Self::Error>;
}

pub fn open_production_local_store<S>(
    store: &mut S,
    input: LocalStoreProductionOpenInput,
) -> Result<LocalStoreProductionOpenDecision, S::Error>
where
    S: ProductionLocalStoreAdapter + ?Sized,
{
    let decision = input.evaluate();
    if decision.accepted {
        store.open_database(AcceptedLocalStoreProductionOpen { decision })?;
    }
    Ok(decision)
}

pub fn replay_production_local_store_wal<S>(
    store: &mut S,
    decision: LocalStoreProductionOpenDecision,
) -> Result<bool, S::Error>
where
    S: ProductionLocalStoreAdapter + ?Sized,
{
    if !decision.can_replay_wal {
        return Ok(false);
    }

    store.replay_wal(AcceptedLocalStoreWalReplay { decision })?;
    Ok(true)
}

pub fn put_production_local_store_record<S>(
    store: &mut S,
    request: LocalStoreWriteRequest<'_>,
) -> Result<LocalStoreWriteDecision, S::Error>
where
    S: ProductionLocalStoreAdapter + ?Sized,
{
    put_local_store_record(store, request)
}

pub fn read_production_local_store_record<S>(
    store: &S,
    locator: LocalStoreRecordLocator<'_>,
) -> Result<Option<LocalStoreReadRecord>, S::Error>
where
    S: ProductionLocalStoreAdapter + ?Sized,
{
    store.read_record(locator)
}

impl ProductionLocalStoreAdapter for PrototypeEncryptedLocalStore {
    fn open_database(
        &mut self,
        _open: AcceptedLocalStoreProductionOpen,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    fn replay_wal(&mut self, _replay: AcceptedLocalStoreWalReplay) -> Result<(), Self::Error> {
        Ok(())
    }

    fn read_record(
        &self,
        locator: LocalStoreRecordLocator<'_>,
    ) -> Result<Option<LocalStoreReadRecord>, Self::Error> {
        Ok(PrototypeEncryptedLocalStore::get_record(self, locator)
            .map(local_store_read_record_from_prototype))
    }
}

impl ProductionLocalStoreAdapter for PrototypeFileEncryptedLocalStore {
    fn open_database(
        &mut self,
        _open: AcceptedLocalStoreProductionOpen,
    ) -> Result<(), Self::Error> {
        Ok(())
    }

    fn replay_wal(&mut self, _replay: AcceptedLocalStoreWalReplay) -> Result<(), Self::Error> {
        Ok(())
    }

    fn read_record(
        &self,
        locator: LocalStoreRecordLocator<'_>,
    ) -> Result<Option<LocalStoreReadRecord>, Self::Error> {
        Ok(PrototypeFileEncryptedLocalStore::get_record(self, locator)?
            .as_ref()
            .map(local_store_read_record_from_prototype))
    }
}

fn local_store_read_record_from_prototype(
    record: &PrototypeLocalStoreRecord,
) -> LocalStoreReadRecord {
    LocalStoreReadRecord::new(
        record.namespace.clone(),
        record.record_id.clone(),
        record.record_kind,
        record.payload_kind,
        record.bytes.clone(),
    )
}

