#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PlatformLocalStoreAdapterInput {
    pub runtime: PlatformLocalStoreRuntime,
    pub adapter_kind: PlatformLocalStoreAdapterKind,
    pub database_root_present: bool,
    pub os_keychain_available: bool,
    pub hardware_backed_key_store: bool,
    pub app_lock_satisfied: bool,
    pub allow_development_adapters: bool,
}

impl PlatformLocalStoreAdapterInput {
    pub const fn evaluate(self) -> PlatformLocalStoreAdapterDecision {
        if matches!(self.runtime, PlatformLocalStoreRuntime::Unknown) {
            return platform_local_store_adapter_reject(
                PlatformLocalStoreAdapterReason::UnknownRuntime,
            );
        }

        if matches!(
            self.adapter_kind,
            PlatformLocalStoreAdapterKind::PlaintextFileStore
        ) {
            return platform_local_store_adapter_reject(
                PlatformLocalStoreAdapterReason::PlaintextAdapterForbidden,
            );
        }

        if matches!(
            self.adapter_kind,
            PlatformLocalStoreAdapterKind::PrototypeFileStore
                | PlatformLocalStoreAdapterKind::DevelopmentMemoryStore
        ) && !self.allow_development_adapters
        {
            return platform_local_store_adapter_reject(
                PlatformLocalStoreAdapterReason::DevelopmentAdapterForbidden,
            );
        }

        if !self.database_root_present {
            return platform_local_store_adapter_reject(
                PlatformLocalStoreAdapterReason::DatabaseRootMissing,
            );
        }

        if !self.os_keychain_available {
            return platform_local_store_adapter_reject(
                PlatformLocalStoreAdapterReason::KeychainUnavailable,
            );
        }

        if matches!(self.runtime, PlatformLocalStoreRuntime::Mobile)
            && !self.hardware_backed_key_store
        {
            return platform_local_store_adapter_reject(
                PlatformLocalStoreAdapterReason::HardwareBackingRequired,
            );
        }

        if !self.app_lock_satisfied {
            return platform_local_store_adapter_reject(
                PlatformLocalStoreAdapterReason::AppLockRequired,
            );
        }

        PlatformLocalStoreAdapterDecision {
            accepted: true,
            reason: PlatformLocalStoreAdapterReason::Accepted,
            can_open_adapter: true,
            requires_user_auth: false,
            requires_install_setup: false,
            requires_hardware_backing: false,
            forbids_plaintext_storage: true,
        }
    }
}

