#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreDatabaseSecurityInput {
    pub platform_adapter: PlatformLocalStoreAdapterDecision,
    pub production_open: LocalStoreProductionOpenDecision,
    pub engine: LocalStoreDatabaseEngine,
    pub cipher: LocalStoreDatabaseCipher,
    pub kdf: LocalStoreDatabaseKdf,
    pub kdf_iterations: i32,
    pub page_size: i32,
    pub per_page_random_nonce: bool,
    pub per_page_authentication: bool,
    pub encryption_key_separate_from_mac_key: bool,
    pub unique_database_salt: bool,
    pub raw_key_wrapped_by_platform_keystore: bool,
    pub encrypted_wal: bool,
    pub encrypted_journal: bool,
    pub temp_store_memory_only: bool,
    pub plaintext_header_bytes: i32,
    pub os_cloud_backup_excluded: bool,
    pub backup_uses_consistent_encrypted_snapshot: bool,
    pub secure_delete_enabled: bool,
    pub memory_locking_enabled: bool,
    pub zeroizes_key_material: bool,
    pub crash_recovery_tested: bool,
    pub plaintext_metadata_fields: i32,
    pub sqlite_extension_loading_enabled: bool,
    pub debug_plaintext_export_enabled: bool,
}

impl LocalStoreDatabaseSecurityInput {
    pub fn evaluate(self) -> LocalStoreDatabaseSecurityDecision {
        evaluate_local_store_database_security(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreDatabaseSecurityDecision {
    pub accepted: bool,
    pub can_open_database: bool,
    pub can_load_records: bool,
    pub can_load_message_keys: bool,
    pub can_host_mls_transactions: bool,
    pub requires_user_auth: bool,
    pub requires_install_setup: bool,
    pub requires_hardware_backing: bool,
    pub requires_recovery: bool,
    pub requires_migration: bool,
    pub requires_crash_recovery: bool,
    pub requires_destructive_repair: bool,
    pub requires_backup_reconfiguration: bool,
    pub forbids_plaintext_storage: bool,
    pub engine_code: i32,
    pub engine_label: &'static str,
    pub cipher_code: i32,
    pub cipher_label: &'static str,
    pub kdf_code: i32,
    pub kdf_label: &'static str,
    pub reason: LocalStoreDatabaseSecurityReason,
    pub platform_adapter_reason: PlatformLocalStoreAdapterReason,
    pub production_open_reason: LocalStoreProductionOpenReason,
}

pub fn evaluate_local_store_database_security(
    input: LocalStoreDatabaseSecurityInput,
) -> LocalStoreDatabaseSecurityDecision {
    if !input.platform_adapter.accepted {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::PlatformAdapterRejected,
            input.platform_adapter.requires_user_auth,
            input.platform_adapter.requires_install_setup,
            input.platform_adapter.requires_hardware_backing,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if !input.production_open.accepted {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::ProductionOpenRejected,
            input.production_open.requires_user_auth,
            false,
            false,
            input.production_open.requires_recovery,
            input.production_open.requires_migration,
            input.production_open.requires_crash_recovery,
            input.production_open.requires_destructive_repair,
            false,
        );
    }

    if matches!(
        input.engine,
        LocalStoreDatabaseEngine::PlainSqlite | LocalStoreDatabaseEngine::Unknown
    ) {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::PlaintextDatabaseForbidden,
            false,
            true,
            false,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if !input.cipher.accepted_for_database() {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::WeakCipherSuite,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !local_store_database_kdf_accepted(input.kdf, input.kdf_iterations) {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::KdfTooWeak,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if input.page_size != MERCURY_LOCAL_STORE_PAGE_SIZE || !input.per_page_random_nonce {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::PageShapeRejected,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.per_page_authentication {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::MissingPerPageAuthentication,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.encryption_key_separate_from_mac_key {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::MacKeyReuseForbidden,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.unique_database_salt {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::DatabaseSaltMissing,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.raw_key_wrapped_by_platform_keystore {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::KeyNotKeystoreWrapped,
            false,
            true,
            true,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.encrypted_wal || !input.encrypted_journal {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::WalOrJournalPlaintext,
            false,
            true,
            false,
            false,
            false,
            true,
            true,
            false,
        );
    }

    if !input.temp_store_memory_only {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::FileTempStoreForbidden,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if input.plaintext_header_bytes != 0 {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::PlaintextHeaderForbidden,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.os_cloud_backup_excluded || !input.backup_uses_consistent_encrypted_snapshot {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::BackupPolicyRejected,
            false,
            true,
            false,
            false,
            false,
            false,
            true,
            true,
        );
    }

    if !input.secure_delete_enabled {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::SecureDeleteMissing,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.memory_locking_enabled || !input.zeroizes_key_material {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::SecretLifecycleRejected,
            false,
            true,
            false,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if !input.crash_recovery_tested {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::CrashRecoveryUntested,
            false,
            true,
            false,
            false,
            false,
            true,
            true,
            false,
        );
    }

    if input.plaintext_metadata_fields != 0 {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::PlaintextMetadataForbidden,
            false,
            true,
            false,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if input.sqlite_extension_loading_enabled {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::ExtensionLoadingForbidden,
            false,
            true,
            false,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if input.debug_plaintext_export_enabled {
        return local_store_database_security_reject(
            input,
            LocalStoreDatabaseSecurityReason::DebugExportForbidden,
            false,
            true,
            false,
            false,
            false,
            false,
            true,
            false,
        );
    }

    LocalStoreDatabaseSecurityDecision {
        accepted: true,
        can_open_database: true,
        can_load_records: true,
        can_load_message_keys: true,
        can_host_mls_transactions: true,
        requires_user_auth: false,
        requires_install_setup: false,
        requires_hardware_backing: false,
        requires_recovery: false,
        requires_migration: false,
        requires_crash_recovery: false,
        requires_destructive_repair: false,
        requires_backup_reconfiguration: false,
        forbids_plaintext_storage: true,
        engine_code: input.engine.code(),
        engine_label: input.engine.label(),
        cipher_code: input.cipher.code(),
        cipher_label: input.cipher.label(),
        kdf_code: input.kdf.code(),
        kdf_label: input.kdf.label(),
        reason: LocalStoreDatabaseSecurityReason::Accepted,
        platform_adapter_reason: input.platform_adapter.reason,
        production_open_reason: input.production_open.reason,
    }
}

const fn local_store_database_kdf_accepted(
    kdf: LocalStoreDatabaseKdf,
    kdf_iterations: i32,
) -> bool {
    match kdf {
        LocalStoreDatabaseKdf::RawKeyFromPlatformKeystore => true,
        LocalStoreDatabaseKdf::Pbkdf2HmacSha512 | LocalStoreDatabaseKdf::Argon2id => {
            kdf_iterations >= MERCURY_LOCAL_STORE_MIN_KDF_ITERATIONS
        }
        LocalStoreDatabaseKdf::None | LocalStoreDatabaseKdf::Unknown => false,
    }
}

const fn local_store_database_security_reject(
    input: LocalStoreDatabaseSecurityInput,
    reason: LocalStoreDatabaseSecurityReason,
    requires_user_auth: bool,
    requires_install_setup: bool,
    requires_hardware_backing: bool,
    requires_recovery: bool,
    requires_migration: bool,
    requires_crash_recovery: bool,
    requires_destructive_repair: bool,
    requires_backup_reconfiguration: bool,
) -> LocalStoreDatabaseSecurityDecision {
    LocalStoreDatabaseSecurityDecision {
        accepted: false,
        can_open_database: false,
        can_load_records: false,
        can_load_message_keys: false,
        can_host_mls_transactions: false,
        requires_user_auth,
        requires_install_setup,
        requires_hardware_backing,
        requires_recovery,
        requires_migration,
        requires_crash_recovery,
        requires_destructive_repair,
        requires_backup_reconfiguration,
        forbids_plaintext_storage: true,
        engine_code: input.engine.code(),
        engine_label: input.engine.label(),
        cipher_code: input.cipher.code(),
        cipher_label: input.cipher.label(),
        kdf_code: input.kdf.code(),
        kdf_label: input.kdf.label(),
        reason,
        platform_adapter_reason: input.platform_adapter.reason,
        production_open_reason: input.production_open.reason,
    }
}

