#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreDatabaseAdapterSelectionInput {
    pub database_security: LocalStoreDatabaseSecurityDecision,
    pub adapter_kind: LocalStoreDatabaseAdapterKind,
    pub binding_kind: LocalStoreDatabaseBindingKind,
    pub target_platform: LocalStoreDatabaseTargetPlatform,
    pub license_kind: LocalStoreDatabaseLicenseKind,
    pub sqlcipher_major_version: i32,
    pub sqlite_source_verified: bool,
    pub sqlcipher_source_verified: bool,
    pub platform_package_supported: bool,
    pub license_allows_redistribution: bool,
    pub crypto_provider_documented: bool,
    pub fips_required: bool,
    pub fips_module_validated: bool,
    pub fips_runtime_self_tests_available: bool,
    pub fips_mode_checked_at_runtime: bool,
    pub compile_has_codec: bool,
    pub compile_has_sqlcipher_extra_init_shutdown: bool,
    pub temp_store_memory_configured: bool,
    pub extension_loading_disabled: bool,
    pub trusted_schema_disabled: bool,
    pub secure_delete_configured: bool,
    pub cipher_memory_security_enabled: bool,
    pub cipher_integrity_check_on_open: bool,
    pub sqlcipher_compatibility_current_major: bool,
    pub deterministic_migration_tested: bool,
    pub crash_recovery_drill_passed: bool,
    pub release_artifacts_signed: bool,
    pub sbom_present: bool,
    pub cve_monitoring_enabled: bool,
    pub debug_sqlcipher_logging_enabled: bool,
}

impl LocalStoreDatabaseAdapterSelectionInput {
    pub fn evaluate(self) -> LocalStoreDatabaseAdapterSelectionDecision {
        evaluate_local_store_database_adapter_selection(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LocalStoreDatabaseAdapterSelectionDecision {
    pub accepted: bool,
    pub can_link_adapter: bool,
    pub can_open_database: bool,
    pub can_ship_release: bool,
    pub can_host_mls_transactions: bool,
    pub requires_license_review: bool,
    pub requires_fips_attestation: bool,
    pub requires_migration_drill: bool,
    pub requires_supply_chain_review: bool,
    pub requires_platform_packaging: bool,
    pub forbids_plaintext_storage: bool,
    pub adapter_kind_code: i32,
    pub adapter_kind_label: &'static str,
    pub binding_kind_code: i32,
    pub binding_kind_label: &'static str,
    pub target_platform_code: i32,
    pub target_platform_label: &'static str,
    pub license_kind_code: i32,
    pub license_kind_label: &'static str,
    pub reason: LocalStoreDatabaseAdapterSelectionReason,
    pub database_security_reason: LocalStoreDatabaseSecurityReason,
}

pub fn evaluate_local_store_database_adapter_selection(
    input: LocalStoreDatabaseAdapterSelectionInput,
) -> LocalStoreDatabaseAdapterSelectionDecision {
    if !input.database_security.accepted {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::DatabaseProfileRejected,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if matches!(
        input.adapter_kind,
        LocalStoreDatabaseAdapterKind::PlainSqlite | LocalStoreDatabaseAdapterKind::Unknown
    ) {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::AdapterKindRejected,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if matches!(input.binding_kind, LocalStoreDatabaseBindingKind::Unknown) {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::BindingKindRejected,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if matches!(
        input.target_platform,
        LocalStoreDatabaseTargetPlatform::Unknown
    ) || !input.platform_package_supported
    {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::PlatformUnsupported,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if matches!(
        input.license_kind,
        LocalStoreDatabaseLicenseKind::TrialEvaluation | LocalStoreDatabaseLicenseKind::Unknown
    ) || !input.license_allows_redistribution
    {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::LicenseRejected,
            true,
            false,
            false,
            false,
            false,
        );
    }

    let uses_sqlcipher = local_store_database_adapter_uses_sqlcipher(input.adapter_kind);

    if uses_sqlcipher && input.sqlcipher_major_version < 4 {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::SqlcipherVersionTooOld,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if !input.sqlite_source_verified || (uses_sqlcipher && !input.sqlcipher_source_verified) {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::SourceAuthenticityMissing,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if !input.crypto_provider_documented {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::CryptoProviderUnverified,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if input.fips_required && !input.fips_module_validated {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::FipsValidationMissing,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if input.fips_required
        && (!input.fips_runtime_self_tests_available || !input.fips_mode_checked_at_runtime)
    {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::FipsRuntimeCheckMissing,
            false,
            true,
            false,
            true,
            false,
        );
    }

    if uses_sqlcipher
        && (!input.compile_has_codec || !input.compile_has_sqlcipher_extra_init_shutdown)
    {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::SqlcipherCodecNotEnabled,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if !input.temp_store_memory_configured {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::UnsafeSqliteConfiguration,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if !input.extension_loading_disabled {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::ExtensionLoadingEnabled,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if !input.trusted_schema_disabled {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::TrustedSchemaEnabled,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if !input.secure_delete_configured {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::SecureDeleteMissing,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if !input.cipher_memory_security_enabled {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::MemorySecurityMissing,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if uses_sqlcipher && !input.cipher_integrity_check_on_open {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::IntegrityCheckMissing,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if uses_sqlcipher && !input.sqlcipher_compatibility_current_major {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::CompatibilityModeRejected,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if !input.deterministic_migration_tested {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::MigrationDrillMissing,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if !input.crash_recovery_drill_passed {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::CrashRecoveryDrillMissing,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if !input.release_artifacts_signed {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::UnsignedReleaseArtifact,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if !input.sbom_present || !input.cve_monitoring_enabled {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::SbomOrCveMonitoringMissing,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if input.debug_sqlcipher_logging_enabled {
        return local_store_database_adapter_selection_reject(
            input,
            LocalStoreDatabaseAdapterSelectionReason::DebugSqlcipherLoggingEnabled,
            false,
            false,
            false,
            false,
            false,
        );
    }

    LocalStoreDatabaseAdapterSelectionDecision {
        accepted: true,
        can_link_adapter: true,
        can_open_database: true,
        can_ship_release: true,
        can_host_mls_transactions: true,
        requires_license_review: false,
        requires_fips_attestation: false,
        requires_migration_drill: false,
        requires_supply_chain_review: false,
        requires_platform_packaging: false,
        forbids_plaintext_storage: true,
        adapter_kind_code: input.adapter_kind.code(),
        adapter_kind_label: input.adapter_kind.label(),
        binding_kind_code: input.binding_kind.code(),
        binding_kind_label: input.binding_kind.label(),
        target_platform_code: input.target_platform.code(),
        target_platform_label: input.target_platform.label(),
        license_kind_code: input.license_kind.code(),
        license_kind_label: input.license_kind.label(),
        reason: LocalStoreDatabaseAdapterSelectionReason::Accepted,
        database_security_reason: input.database_security.reason,
    }
}

const fn local_store_database_adapter_uses_sqlcipher(
    adapter_kind: LocalStoreDatabaseAdapterKind,
) -> bool {
    matches!(
        adapter_kind,
        LocalStoreDatabaseAdapterKind::SqlCipherCommunity
            | LocalStoreDatabaseAdapterKind::SqlCipherCommercial
            | LocalStoreDatabaseAdapterKind::SqlCipherEnterpriseFips
    )
}

const fn local_store_database_adapter_selection_reject(
    input: LocalStoreDatabaseAdapterSelectionInput,
    reason: LocalStoreDatabaseAdapterSelectionReason,
    requires_license_review: bool,
    requires_fips_attestation: bool,
    requires_migration_drill: bool,
    requires_supply_chain_review: bool,
    requires_platform_packaging: bool,
) -> LocalStoreDatabaseAdapterSelectionDecision {
    LocalStoreDatabaseAdapterSelectionDecision {
        accepted: false,
        can_link_adapter: false,
        can_open_database: false,
        can_ship_release: false,
        can_host_mls_transactions: false,
        requires_license_review,
        requires_fips_attestation,
        requires_migration_drill,
        requires_supply_chain_review,
        requires_platform_packaging,
        forbids_plaintext_storage: true,
        adapter_kind_code: input.adapter_kind.code(),
        adapter_kind_label: input.adapter_kind.label(),
        binding_kind_code: input.binding_kind.code(),
        binding_kind_label: input.binding_kind.label(),
        target_platform_code: input.target_platform.code(),
        target_platform_label: input.target_platform.label(),
        license_kind_code: input.license_kind.code(),
        license_kind_label: input.license_kind.label(),
        reason,
        database_security_reason: input.database_security.reason,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PrototypeProductionStoreSessionReason {
    Accepted,
    KeychainRejected,
    UnlockRejected,
    ProductionOpenRejected,
    WalReplayRequired,
    StoreWriteRejected,
    StoreReadMissing,
}

impl PrototypeProductionStoreSessionReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::Accepted => 0,
            Self::KeychainRejected => 1,
            Self::UnlockRejected => 2,
            Self::ProductionOpenRejected => 3,
            Self::WalReplayRequired => 4,
            Self::StoreWriteRejected => 5,
            Self::StoreReadMissing => 6,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Accepted => "ACCEPTED",
            Self::KeychainRejected => "KEYCHAIN_REJECTED",
            Self::UnlockRejected => "UNLOCK_REJECTED",
            Self::ProductionOpenRejected => "PRODUCTION_OPEN_REJECTED",
            Self::WalReplayRequired => "WAL_REPLAY_REQUIRED",
            Self::StoreWriteRejected => "STORE_WRITE_REJECTED",
            Self::StoreReadMissing => "STORE_READ_MISSING",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PrototypeProductionStoreSessionInput<'a> {
    pub keychain: LocalStoreKeychainUnlockInput,
    pub header_magic_matches: bool,
    pub header_suite_code: i32,
    pub header_nonce_len: i32,
    pub header_tag_len: i32,
    pub required_key_slots: i32,
    pub sealed_key_slots: i32,
    pub plaintext_key_slots: i32,
    pub root_key_scope: LocalStoreKeyScope,
    pub root_key_generation: i32,
    pub crash_recovery: LocalStoreCrashRecoveryState,
    pub write_request: LocalStoreWriteRequest<'a>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PrototypeProductionStoreSessionOutcome {
    pub accepted: bool,
    pub reason: PrototypeProductionStoreSessionReason,
    pub keychain_decision: LocalStoreKeychainUnlockDecision,
    pub unlock_decision: LocalStoreUnlockDecision,
    pub production_open_decision: LocalStoreProductionOpenDecision,
    pub open_attempted: bool,
    pub wal_replayed: bool,
    pub write_decision: Option<LocalStoreWriteDecision>,
    pub read_record: Option<LocalStoreReadRecord>,
    pub plaintext_exposed: bool,
}

pub fn run_prototype_production_store_session<S>(
    store: &mut S,
    input: PrototypeProductionStoreSessionInput<'_>,
) -> Result<PrototypeProductionStoreSessionOutcome, S::Error>
where
    S: ProductionLocalStoreAdapter + ?Sized,
{
    let keychain_decision = input.keychain.evaluate();
    let unlock_decision = keychain_decision.unlock_input.evaluate();
    let open_input = production_open_input_from_session(keychain_decision.unlock_input, input);
    let production_open_decision = open_input.evaluate();

    if !keychain_decision.accepted {
        return Ok(prototype_production_store_outcome(
            false,
            PrototypeProductionStoreSessionReason::KeychainRejected,
            keychain_decision,
            unlock_decision,
            production_open_decision,
            false,
            false,
            None,
            None,
        ));
    }

    if !unlock_decision.accepted {
        return Ok(prototype_production_store_outcome(
            false,
            PrototypeProductionStoreSessionReason::UnlockRejected,
            keychain_decision,
            unlock_decision,
            production_open_decision,
            false,
            false,
            None,
            None,
        ));
    }

    if production_open_decision.can_replay_wal {
        let wal_replayed = replay_production_local_store_wal(store, production_open_decision)?;
        return Ok(prototype_production_store_outcome(
            false,
            PrototypeProductionStoreSessionReason::WalReplayRequired,
            keychain_decision,
            unlock_decision,
            production_open_decision,
            false,
            wal_replayed,
            None,
            None,
        ));
    }

    if !production_open_decision.accepted {
        return Ok(prototype_production_store_outcome(
            false,
            PrototypeProductionStoreSessionReason::ProductionOpenRejected,
            keychain_decision,
            unlock_decision,
            production_open_decision,
            false,
            false,
            None,
            None,
        ));
    }

    let opened = open_production_local_store(store, open_input)?;
    let open_attempted = opened.accepted;
    let write_decision = put_production_local_store_record(store, input.write_request)?;
    if !write_decision.accepted {
        return Ok(prototype_production_store_outcome(
            false,
            PrototypeProductionStoreSessionReason::StoreWriteRejected,
            keychain_decision,
            unlock_decision,
            opened,
            open_attempted,
            false,
            Some(write_decision),
            None,
        ));
    }

    let read_record = read_production_local_store_record(store, input.write_request.locator)?;
    let Some(read_record) = read_record else {
        return Ok(prototype_production_store_outcome(
            false,
            PrototypeProductionStoreSessionReason::StoreReadMissing,
            keychain_decision,
            unlock_decision,
            opened,
            open_attempted,
            false,
            Some(write_decision),
            None,
        ));
    };

    Ok(prototype_production_store_outcome(
        true,
        PrototypeProductionStoreSessionReason::Accepted,
        keychain_decision,
        unlock_decision,
        opened,
        open_attempted,
        false,
        Some(write_decision),
        Some(read_record),
    ))
}

fn production_open_input_from_session(
    unlock: LocalStoreUnlockInput,
    input: PrototypeProductionStoreSessionInput<'_>,
) -> LocalStoreProductionOpenInput {
    LocalStoreProductionOpenInput {
        unlock,
        header_magic_matches: input.header_magic_matches,
        header_suite_code: input.header_suite_code,
        header_nonce_len: input.header_nonce_len,
        header_tag_len: input.header_tag_len,
        required_key_slots: input.required_key_slots,
        sealed_key_slots: input.sealed_key_slots,
        plaintext_key_slots: input.plaintext_key_slots,
        root_key_scope: input.root_key_scope,
        root_key_generation: input.root_key_generation,
        crash_recovery: input.crash_recovery,
    }
}

fn prototype_production_store_outcome(
    accepted: bool,
    reason: PrototypeProductionStoreSessionReason,
    keychain_decision: LocalStoreKeychainUnlockDecision,
    unlock_decision: LocalStoreUnlockDecision,
    production_open_decision: LocalStoreProductionOpenDecision,
    open_attempted: bool,
    wal_replayed: bool,
    write_decision: Option<LocalStoreWriteDecision>,
    read_record: Option<LocalStoreReadRecord>,
) -> PrototypeProductionStoreSessionOutcome {
    PrototypeProductionStoreSessionOutcome {
        accepted,
        reason,
        keychain_decision,
        unlock_decision,
        production_open_decision,
        open_attempted,
        wal_replayed,
        write_decision,
        read_record,
        plaintext_exposed: false,
    }
}

