#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ClientBootstrapInput {
    pub account_id_len: i32,
    pub device_id_len: i32,
    pub local_device_trust: DeviceTrustDecision,
    pub key_transparency: KeyTransparencyDecision,
    pub account_secret: ClientBootstrapSecretState,
    pub device_secret: ClientBootstrapSecretState,
    pub room_state: ClientBootstrapSecretState,
    pub replay_checkpoint: ClientReplayCheckpointState,
    pub sync_state: ClientSyncState,
    pub pending_recovery: bool,
    pub plaintext_cache_records: i32,
}

impl ClientBootstrapInput {
    pub fn evaluate(self) -> ClientBootstrapDecision {
        evaluate_client_bootstrap(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ClientBootstrapDecision {
    pub accepted: bool,
    pub can_start_sync: bool,
    pub can_decrypt_local_store: bool,
    pub can_open_message_ui: bool,
    pub requires_sync: bool,
    pub requires_recovery: bool,
    pub requires_user_action: bool,
    pub reason: ClientBootstrapReason,
}

pub fn evaluate_client_bootstrap(input: ClientBootstrapInput) -> ClientBootstrapDecision {
    if input.account_id_len <= 0 {
        return client_bootstrap_reject(
            ClientBootstrapReason::MissingAccountId,
            false,
            false,
            false,
            true,
        );
    }

    if input.device_id_len <= 0 {
        return client_bootstrap_reject(
            ClientBootstrapReason::MissingDeviceId,
            false,
            false,
            false,
            true,
        );
    }

    if input.pending_recovery {
        return client_bootstrap_reject(
            ClientBootstrapReason::RecoveryRequired,
            false,
            false,
            true,
            true,
        );
    }

    if input.plaintext_cache_records != 0 {
        return client_bootstrap_reject(
            ClientBootstrapReason::PlaintextCacheForbidden,
            false,
            false,
            false,
            true,
        );
    }

    if !input.local_device_trust.trusted {
        return client_bootstrap_reject(
            ClientBootstrapReason::LocalDeviceTrustRejected,
            false,
            false,
            false,
            true,
        );
    }

    match input.key_transparency.state {
        KeyTransparencyState::Consistent => {}
        KeyTransparencyState::Inconsistent => {
            return client_bootstrap_reject(
                ClientBootstrapReason::KeyTransparencyRejected,
                false,
                false,
                false,
                true,
            );
        }
        KeyTransparencyState::NotChecked
        | KeyTransparencyState::MissingProof
        | KeyTransparencyState::StaleProof => {
            return client_bootstrap_reject(
                ClientBootstrapReason::KeyTransparencyNotReady,
                true,
                true,
                false,
                input.key_transparency.requires_user_action,
            );
        }
    }

    match input.account_secret {
        ClientBootstrapSecretState::PresentSealed => {}
        ClientBootstrapSecretState::Missing => {
            return client_bootstrap_reject(
                ClientBootstrapReason::AccountSecretMissing,
                false,
                false,
                true,
                true,
            );
        }
        ClientBootstrapSecretState::Corrupt => {
            return client_bootstrap_reject(
                ClientBootstrapReason::AccountSecretCorrupt,
                false,
                false,
                true,
                true,
            );
        }
        ClientBootstrapSecretState::PlaintextPresent => {
            return client_bootstrap_reject(
                ClientBootstrapReason::PlaintextSecretForbidden,
                false,
                false,
                false,
                true,
            );
        }
    }

    match input.device_secret {
        ClientBootstrapSecretState::PresentSealed => {}
        ClientBootstrapSecretState::Missing => {
            return client_bootstrap_reject(
                ClientBootstrapReason::DeviceSecretMissing,
                false,
                false,
                true,
                true,
            );
        }
        ClientBootstrapSecretState::Corrupt => {
            return client_bootstrap_reject(
                ClientBootstrapReason::DeviceSecretCorrupt,
                false,
                false,
                true,
                true,
            );
        }
        ClientBootstrapSecretState::PlaintextPresent => {
            return client_bootstrap_reject(
                ClientBootstrapReason::PlaintextSecretForbidden,
                false,
                false,
                false,
                true,
            );
        }
    }

    match input.room_state {
        ClientBootstrapSecretState::PresentSealed => {}
        ClientBootstrapSecretState::Missing => {
            return client_bootstrap_reject(
                ClientBootstrapReason::RoomStateMissing,
                true,
                true,
                false,
                false,
            );
        }
        ClientBootstrapSecretState::Corrupt => {
            return client_bootstrap_reject(
                ClientBootstrapReason::RoomStateCorrupt,
                true,
                true,
                false,
                true,
            );
        }
        ClientBootstrapSecretState::PlaintextPresent => {
            return client_bootstrap_reject(
                ClientBootstrapReason::PlaintextSecretForbidden,
                false,
                false,
                false,
                true,
            );
        }
    }

    match input.replay_checkpoint {
        ClientReplayCheckpointState::Ready => {}
        ClientReplayCheckpointState::Missing => {
            return client_bootstrap_reject(
                ClientBootstrapReason::ReplayCheckpointMissing,
                true,
                true,
                false,
                false,
            );
        }
        ClientReplayCheckpointState::Stale => {
            return client_bootstrap_reject(
                ClientBootstrapReason::ReplayCheckpointStale,
                true,
                true,
                false,
                false,
            );
        }
        ClientReplayCheckpointState::GapDetected => {
            return client_bootstrap_reject(
                ClientBootstrapReason::ReplayGapDetected,
                true,
                true,
                false,
                false,
            );
        }
    }

    match input.sync_state {
        ClientSyncState::CaughtUp => {}
        ClientSyncState::Offline | ClientSyncState::CatchingUp => {
            return client_bootstrap_reject(
                ClientBootstrapReason::SyncIncomplete,
                true,
                true,
                false,
                false,
            );
        }
        ClientSyncState::GapDetected => {
            return client_bootstrap_reject(
                ClientBootstrapReason::SyncGapDetected,
                true,
                true,
                false,
                false,
            );
        }
        ClientSyncState::Failed => {
            return client_bootstrap_reject(
                ClientBootstrapReason::SyncFailed,
                true,
                true,
                false,
                true,
            );
        }
    }

    ClientBootstrapDecision {
        accepted: true,
        can_start_sync: true,
        can_decrypt_local_store: true,
        can_open_message_ui: true,
        requires_sync: false,
        requires_recovery: false,
        requires_user_action: false,
        reason: ClientBootstrapReason::Accepted,
    }
}

const fn client_bootstrap_reject(
    reason: ClientBootstrapReason,
    can_start_sync: bool,
    requires_sync: bool,
    requires_recovery: bool,
    requires_user_action: bool,
) -> ClientBootstrapDecision {
    ClientBootstrapDecision {
        accepted: false,
        can_start_sync,
        can_decrypt_local_store: false,
        can_open_message_ui: false,
        requires_sync,
        requires_recovery,
        requires_user_action,
        reason,
    }
}

