#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AccountRecoveryInput {
    pub recovery_requested: bool,
    pub method: AccountRecoveryMethod,
    pub high_security_account: bool,
    pub recovery_key_entropy_bits: i32,
    pub recovery_key_digest_len: i32,
    pub threshold_shares: i32,
    pub threshold_required: i32,
    pub threshold_approvals: i32,
    pub device_approval_present: bool,
    pub server_authenticated: bool,
    pub server_rate_limited: bool,
    pub backup_encrypted: bool,
    pub plaintext_backup_fields: i32,
    pub rotates_device_secret: bool,
    pub audit_digest_len: i32,
}

impl AccountRecoveryInput {
    pub fn evaluate(self) -> AccountRecoveryDecision {
        evaluate_account_recovery(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AccountRecoveryDecision {
    pub accepted: bool,
    pub method: AccountRecoveryMethod,
    pub can_start_recovery: bool,
    pub can_restore_device_secret: bool,
    pub requires_user_action: bool,
    pub requires_server_setup: bool,
    pub requires_key_rotation: bool,
    pub forbids_low_entropy_recovery: bool,
    pub forbids_plaintext_backup: bool,
    pub plaintext_bytes_exposed: bool,
    pub reason: AccountRecoveryReason,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AcceptedAccountRecovery {
    decision: AccountRecoveryDecision,
}

impl AcceptedAccountRecovery {
    pub const fn decision(self) -> AccountRecoveryDecision {
        self.decision
    }
}

pub trait AccountRecoveryServiceAdapter {
    type Error;

    fn recover_accepted_account(
        &mut self,
        accepted: AcceptedAccountRecovery,
    ) -> Result<(), Self::Error>;
}

pub fn recover_account_with_adapter<A>(
    adapter: &mut A,
    input: AccountRecoveryInput,
) -> Result<AccountRecoveryDecision, A::Error>
where
    A: AccountRecoveryServiceAdapter + ?Sized,
{
    let decision = input.evaluate();
    if decision.accepted {
        adapter.recover_accepted_account(AcceptedAccountRecovery { decision })?;
    }
    Ok(decision)
}

pub fn evaluate_account_recovery(input: AccountRecoveryInput) -> AccountRecoveryDecision {
    if !input.recovery_requested {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::RecoveryNotRequested,
            false,
            false,
            false,
        );
    }

    if input.method == AccountRecoveryMethod::LowEntropyPin {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::LowEntropyPinForbidden,
            true,
            false,
            false,
        );
    }

    if input.recovery_key_entropy_bits < account_recovery_min_entropy_bits(input) {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::RecoveryKeyTooWeak,
            true,
            false,
            false,
        );
    }

    if input.recovery_key_digest_len != 32 {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::RecoveryKeyDigestMissing,
            true,
            false,
            false,
        );
    }

    if input.method == AccountRecoveryMethod::ThresholdRecovery
        && (input.threshold_required < 2
            || input.threshold_shares < input.threshold_required
            || input.threshold_approvals < input.threshold_required)
    {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::ThresholdQuorumInsufficient,
            true,
            false,
            false,
        );
    }

    if input.method == AccountRecoveryMethod::HardwareDeviceTransfer
        && !input.device_approval_present
    {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::DeviceApprovalMissing,
            true,
            false,
            false,
        );
    }

    if !input.server_authenticated {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::ServerAuthenticationMissing,
            false,
            true,
            false,
        );
    }

    if !input.server_rate_limited {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::ServerRateLimitMissing,
            false,
            true,
            false,
        );
    }

    if !input.backup_encrypted {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::BackupEncryptionMissing,
            false,
            false,
            false,
        );
    }

    if input.plaintext_backup_fields != 0 {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::PlaintextBackupForbidden,
            false,
            false,
            false,
        );
    }

    if input.high_security_account && !input.rotates_device_secret {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::KeyRotationMissing,
            false,
            false,
            true,
        );
    }

    if input.audit_digest_len != 32 {
        return account_recovery_reject(
            input,
            AccountRecoveryReason::AuditDigestMissing,
            true,
            false,
            false,
        );
    }

    AccountRecoveryDecision {
        accepted: true,
        method: input.method,
        can_start_recovery: true,
        can_restore_device_secret: true,
        requires_user_action: false,
        requires_server_setup: false,
        requires_key_rotation: false,
        forbids_low_entropy_recovery: true,
        forbids_plaintext_backup: true,
        plaintext_bytes_exposed: false,
        reason: AccountRecoveryReason::Accepted,
    }
}

const fn account_recovery_min_entropy_bits(input: AccountRecoveryInput) -> i32 {
    if input.high_security_account {
        192
    } else {
        128
    }
}

const fn account_recovery_reject(
    input: AccountRecoveryInput,
    reason: AccountRecoveryReason,
    requires_user_action: bool,
    requires_server_setup: bool,
    requires_key_rotation: bool,
) -> AccountRecoveryDecision {
    AccountRecoveryDecision {
        accepted: false,
        method: input.method,
        can_start_recovery: false,
        can_restore_device_secret: false,
        requires_user_action,
        requires_server_setup,
        requires_key_rotation,
        forbids_low_entropy_recovery: true,
        forbids_plaintext_backup: true,
        plaintext_bytes_exposed: false,
        reason,
    }
}

