#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SecureBackupRestoreInput {
    pub account_recovery: AccountRecoveryDecision,
    pub scope: SecureBackupRestoreScope,
    pub transport: SecureBackupRestoreTransport,
    pub envelope_suite: SecureBackupRestoreEnvelopeSuite,
    pub high_security_account: bool,
    pub backup_key_entropy_bits: i32,
    pub backup_key_digest_len: i32,
    pub kdf_memory_cost_mib: i32,
    pub kdf_iterations: i32,
    pub device_approval_present: bool,
    pub threshold_shares: i32,
    pub threshold_required: i32,
    pub threshold_approvals: i32,
    pub server_authenticated: bool,
    pub server_rate_limited: bool,
    pub opaque_account_identifier: bool,
    pub backup_encrypted: bool,
    pub plaintext_export_fields: i32,
    pub os_plaintext_backup_excluded: bool,
    pub mls_state_included: bool,
    pub mls_state_sealed: bool,
    pub mls_epoch_bound: bool,
    pub restore_rotates_device_secret: bool,
    pub restore_rekeys_groups: bool,
    pub archive_manifest_authenticated: bool,
    pub replay_nonce_len: i32,
    pub audit_digest_len: i32,
    pub retention_days: i32,
    pub max_retention_days: i32,
}

impl SecureBackupRestoreInput {
    pub fn evaluate(self) -> SecureBackupRestoreDecision {
        evaluate_secure_backup_restore(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SecureBackupRestoreDecision {
    pub accepted: bool,
    pub scope: SecureBackupRestoreScope,
    pub transport: SecureBackupRestoreTransport,
    pub envelope_suite: SecureBackupRestoreEnvelopeSuite,
    pub can_create_backup: bool,
    pub can_restore_device: bool,
    pub can_restore_mls_state: bool,
    pub can_use_cloud_storage: bool,
    pub requires_user_action: bool,
    pub requires_server_setup: bool,
    pub requires_device_rekey: bool,
    pub requires_group_rekey: bool,
    pub requires_backup_reconfiguration: bool,
    pub forbids_plaintext_export: bool,
    pub forbids_os_plaintext_backup: bool,
    pub plaintext_bytes_exposed: bool,
    pub reason: SecureBackupRestoreReason,
}

pub fn evaluate_secure_backup_restore(
    input: SecureBackupRestoreInput,
) -> SecureBackupRestoreDecision {
    if !input.account_recovery.accepted {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::AccountRecoveryRejected,
            input.account_recovery.requires_user_action,
            input.account_recovery.requires_server_setup,
            input.account_recovery.requires_key_rotation,
            false,
            false,
        );
    }

    if input.scope == SecureBackupRestoreScope::Unknown {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::ScopeRejected,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if input.transport == SecureBackupRestoreTransport::Unknown {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::TransportRejected,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if !input.envelope_suite.is_portable_archive_suite() {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::EnvelopeSuiteRejected,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if input.backup_key_entropy_bits < secure_backup_min_entropy_bits(input) {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::BackupKeyTooWeak,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if input.backup_key_digest_len != 32 {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::BackupKeyDigestMissing,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if input.kdf_memory_cost_mib < secure_backup_min_kdf_memory_mib(input)
        || input.kdf_iterations < 3
    {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::KdfPolicyMissing,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if input.transport == SecureBackupRestoreTransport::HardwareDeviceTransfer
        && !input.device_approval_present
    {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::DeviceApprovalMissing,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if input.transport == SecureBackupRestoreTransport::ThresholdRecoveryService
        && (input.threshold_required < 2
            || input.threshold_shares < input.threshold_required
            || input.threshold_approvals < input.threshold_required)
    {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::ThresholdQuorumMissing,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if input.transport.is_server_backed() && !input.server_authenticated {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::ServerAuthenticationMissing,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if input.transport.is_server_backed() && !input.server_rate_limited {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::ServerRateLimitMissing,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if input.transport.is_server_backed() && !input.opaque_account_identifier {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::OpaqueIdentifierMissing,
            false,
            true,
            false,
            false,
            true,
        );
    }

    if !input.backup_encrypted {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::BackupEncryptionMissing,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if input.plaintext_export_fields != 0 {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::PlaintextExportForbidden,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if !input.os_plaintext_backup_excluded {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::OsBackupPolicyRejected,
            false,
            false,
            false,
            false,
            true,
        );
    }

    let should_restore_mls_state = input.scope.includes_mls_state() || input.mls_state_included;
    if should_restore_mls_state && !input.mls_state_sealed {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::MlsStateNotSealed,
            false,
            false,
            false,
            true,
            true,
        );
    }

    if should_restore_mls_state && !input.mls_epoch_bound {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::MlsEpochBindingMissing,
            false,
            false,
            false,
            true,
            true,
        );
    }

    if !input.restore_rotates_device_secret
        || (should_restore_mls_state && !input.restore_rekeys_groups)
    {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::RestoreRekeyMissing,
            false,
            false,
            !input.restore_rotates_device_secret,
            should_restore_mls_state && !input.restore_rekeys_groups,
            false,
        );
    }

    if !input.archive_manifest_authenticated {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::TamperEvidenceMissing,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if input.replay_nonce_len < 24 {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::ReplayProtectionMissing,
            false,
            false,
            false,
            false,
            true,
        );
    }

    if input.audit_digest_len != 32 {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::AuditDigestMissing,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if input.max_retention_days <= 0
        || input.retention_days < 0
        || input.retention_days > input.max_retention_days
    {
        return secure_backup_restore_reject(
            input,
            SecureBackupRestoreReason::RetentionPolicyRejected,
            true,
            false,
            false,
            false,
            true,
        );
    }

    SecureBackupRestoreDecision {
        accepted: true,
        scope: input.scope,
        transport: input.transport,
        envelope_suite: input.envelope_suite,
        can_create_backup: true,
        can_restore_device: true,
        can_restore_mls_state: should_restore_mls_state,
        can_use_cloud_storage: input.transport == SecureBackupRestoreTransport::CloudObjectStore,
        requires_user_action: false,
        requires_server_setup: false,
        requires_device_rekey: false,
        requires_group_rekey: false,
        requires_backup_reconfiguration: false,
        forbids_plaintext_export: true,
        forbids_os_plaintext_backup: true,
        plaintext_bytes_exposed: false,
        reason: SecureBackupRestoreReason::Accepted,
    }
}

const fn secure_backup_min_entropy_bits(input: SecureBackupRestoreInput) -> i32 {
    if input.high_security_account {
        256
    } else {
        192
    }
}

const fn secure_backup_min_kdf_memory_mib(input: SecureBackupRestoreInput) -> i32 {
    if input.high_security_account { 128 } else { 64 }
}

const fn secure_backup_restore_reject(
    input: SecureBackupRestoreInput,
    reason: SecureBackupRestoreReason,
    requires_user_action: bool,
    requires_server_setup: bool,
    requires_device_rekey: bool,
    requires_group_rekey: bool,
    requires_backup_reconfiguration: bool,
) -> SecureBackupRestoreDecision {
    SecureBackupRestoreDecision {
        accepted: false,
        scope: input.scope,
        transport: input.transport,
        envelope_suite: input.envelope_suite,
        can_create_backup: false,
        can_restore_device: false,
        can_restore_mls_state: false,
        can_use_cloud_storage: false,
        requires_user_action,
        requires_server_setup,
        requires_device_rekey,
        requires_group_rekey,
        requires_backup_reconfiguration,
        forbids_plaintext_export: true,
        forbids_os_plaintext_backup: true,
        plaintext_bytes_exposed: false,
        reason,
    }
}

