#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditEventChainInput {
    pub event_kind: SealedAuditEventKind,
    pub anchor_kind: SealedAuditAnchorKind,
    pub envelope_suite: SealedAuditEnvelopeSuite,
    pub event_sequence: i64,
    pub previous_chain_size: i64,
    pub previous_event_hash_len: i32,
    pub event_hash_len: i32,
    pub record_digest_len: i32,
    pub merkle_leaf_hash_len: i32,
    pub merkle_root_hash_len: i32,
    pub event_sealed: bool,
    pub aad_binds_event_context: bool,
    pub plaintext_field_count: i32,
    pub plaintext_payload_bytes: i32,
    pub monotonic_counter_present: bool,
    pub monotonic_counter_increases: bool,
    pub device_binding_digest_len: i32,
    pub actor_binding_digest_len: i32,
    pub epoch_binding_digest_len: i32,
    pub room_epoch_digest_len: i32,
    pub critical_event_bound: bool,
    pub signed_checkpoint_present: bool,
    pub checkpoint_signature_len: i32,
    pub checkpoint_timestamp_s: i64,
    pub checkpoint_size: i64,
    pub previous_checkpoint_size: i64,
    pub inclusion_proof_verified: bool,
    pub consistency_proof_verified: bool,
    pub transparency_receipt_present: bool,
    pub witness_count: i32,
    pub witness_threshold: i32,
    pub witness_operator_count: i32,
    pub storage_append_only: bool,
    pub storage_transactional: bool,
    pub rollback_resistant_store: bool,
    pub local_store_sealed: bool,
    pub forward_secret_rotated: bool,
    pub previous_key_material_deleted: bool,
}

impl SealedAuditEventChainInput {
    pub fn evaluate(self) -> SealedAuditEventChainDecision {
        evaluate_sealed_audit_event_chain(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditEventChainDecision {
    pub accepted: bool,
    pub event_kind: SealedAuditEventKind,
    pub anchor_kind: SealedAuditAnchorKind,
    pub envelope_suite: SealedAuditEnvelopeSuite,
    pub event_sequence: i64,
    pub can_append_event: bool,
    pub can_verify_inclusion: bool,
    pub can_publish_transparency_receipt: bool,
    pub can_detect_rollback: bool,
    pub requires_storage_repair: bool,
    pub requires_transparency_setup: bool,
    pub requires_redaction: bool,
    pub requires_key_rotation: bool,
    pub tamper_evident: bool,
    pub append_only: bool,
    pub plaintext_bytes_exposed: bool,
    pub reason: SealedAuditEventChainReason,
}

pub fn evaluate_sealed_audit_event_chain(
    input: SealedAuditEventChainInput,
) -> SealedAuditEventChainDecision {
    if input.event_kind == SealedAuditEventKind::Unknown {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::EventKindRejected,
            false,
            false,
            true,
            false,
        );
    }

    if input.anchor_kind == SealedAuditAnchorKind::Unknown {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::AnchorRejected,
            false,
            true,
            false,
            false,
        );
    }

    if !input.envelope_suite.is_sealed() {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::EnvelopeSuiteRejected,
            false,
            false,
            false,
            true,
        );
    }

    if input.plaintext_field_count != 0 || input.plaintext_payload_bytes != 0 {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::PlaintextEventForbidden,
            false,
            false,
            true,
            false,
        );
    }

    if input.event_hash_len != 32
        || input.record_digest_len != 32
        || input.merkle_leaf_hash_len != 32
        || input.merkle_root_hash_len != 32
    {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::DigestShapeRejected,
            false,
            false,
            false,
            false,
        );
    }

    if input.event_sequence < 0
        || input.previous_chain_size < 0
        || input.event_sequence != input.previous_chain_size
        || input.checkpoint_size <= input.previous_checkpoint_size
    {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::SequenceRejected,
            false,
            false,
            false,
            false,
        );
    }

    if input.previous_chain_size > 0 && input.previous_event_hash_len != 32 {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::PreviousHashMissing,
            false,
            false,
            false,
            false,
        );
    }

    if !input.monotonic_counter_present || !input.monotonic_counter_increases {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::MonotonicCounterRejected,
            true,
            false,
            false,
            false,
        );
    }

    if input.device_binding_digest_len != 32
        || input.actor_binding_digest_len != 32
        || input.epoch_binding_digest_len != 32
        || (input.event_kind.requires_room_epoch_binding() && input.room_epoch_digest_len != 32)
        || !input.critical_event_bound
    {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::EventBindingMissing,
            false,
            false,
            false,
            false,
        );
    }

    if !input.event_sealed || !input.aad_binds_event_context {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::SealMissing,
            false,
            false,
            false,
            true,
        );
    }

    if !input.signed_checkpoint_present || input.checkpoint_timestamp_s <= 0 {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::CheckpointMissing,
            false,
            true,
            false,
            false,
        );
    }

    if input.checkpoint_signature_len < 64 {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::CheckpointSignatureMissing,
            false,
            true,
            false,
            false,
        );
    }

    if !input.inclusion_proof_verified || !input.consistency_proof_verified {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::MerkleProofMissing,
            false,
            true,
            false,
            false,
        );
    }

    if input.anchor_kind.requires_transparency_receipt() && !input.transparency_receipt_present {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::TransparencyReceiptMissing,
            false,
            true,
            false,
            false,
        );
    }

    if input.anchor_kind.requires_witness_quorum()
        && (input.witness_threshold < 2
            || input.witness_count < input.witness_threshold
            || input.witness_operator_count < 2)
    {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::WitnessQuorumMissing,
            false,
            true,
            false,
            false,
        );
    }

    if !input.storage_append_only || !input.storage_transactional {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::AppendOnlyStorageMissing,
            true,
            false,
            false,
            false,
        );
    }

    if !input.rollback_resistant_store || !input.local_store_sealed {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::RollbackProtectionMissing,
            true,
            false,
            false,
            false,
        );
    }

    if !input.forward_secret_rotated || !input.previous_key_material_deleted {
        return sealed_audit_event_chain_reject(
            input,
            SealedAuditEventChainReason::ForwardSecrecyMissing,
            false,
            false,
            false,
            true,
        );
    }

    SealedAuditEventChainDecision {
        accepted: true,
        event_kind: input.event_kind,
        anchor_kind: input.anchor_kind,
        envelope_suite: input.envelope_suite,
        event_sequence: input.event_sequence,
        can_append_event: true,
        can_verify_inclusion: true,
        can_publish_transparency_receipt: input.anchor_kind.requires_transparency_receipt(),
        can_detect_rollback: true,
        requires_storage_repair: false,
        requires_transparency_setup: false,
        requires_redaction: false,
        requires_key_rotation: false,
        tamper_evident: true,
        append_only: true,
        plaintext_bytes_exposed: false,
        reason: SealedAuditEventChainReason::Accepted,
    }
}

const fn sealed_audit_event_chain_reject(
    input: SealedAuditEventChainInput,
    reason: SealedAuditEventChainReason,
    requires_storage_repair: bool,
    requires_transparency_setup: bool,
    requires_redaction: bool,
    requires_key_rotation: bool,
) -> SealedAuditEventChainDecision {
    SealedAuditEventChainDecision {
        accepted: false,
        event_kind: input.event_kind,
        anchor_kind: input.anchor_kind,
        envelope_suite: input.envelope_suite,
        event_sequence: input.event_sequence,
        can_append_event: false,
        can_verify_inclusion: false,
        can_publish_transparency_receipt: false,
        can_detect_rollback: false,
        requires_storage_repair,
        requires_transparency_setup,
        requires_redaction,
        requires_key_rotation,
        tamper_evident: false,
        append_only: false,
        plaintext_bytes_exposed: false,
        reason,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SealedAuditEventStoreReason {
    Accepted,
    ChainRejected,
    DuplicateSequence,
    DuplicateEventHash,
    DuplicateCheckpoint,
    RollbackSequence,
    BadDigestShape,
    PlaintextMetadataForbidden,
    CheckpointBindingMissing,
    TransparencyReceiptMissing,
    AppendOnlyGuardMissing,
}

impl SealedAuditEventStoreReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::Accepted => 0,
            Self::ChainRejected => 1,
            Self::DuplicateSequence => 2,
            Self::DuplicateEventHash => 3,
            Self::DuplicateCheckpoint => 4,
            Self::RollbackSequence => 5,
            Self::BadDigestShape => 6,
            Self::PlaintextMetadataForbidden => 7,
            Self::CheckpointBindingMissing => 8,
            Self::TransparencyReceiptMissing => 9,
            Self::AppendOnlyGuardMissing => 10,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Accepted => "ACCEPTED",
            Self::ChainRejected => "CHAIN_REJECTED",
            Self::DuplicateSequence => "DUPLICATE_SEQUENCE",
            Self::DuplicateEventHash => "DUPLICATE_EVENT_HASH",
            Self::DuplicateCheckpoint => "DUPLICATE_CHECKPOINT",
            Self::RollbackSequence => "ROLLBACK_SEQUENCE",
            Self::BadDigestShape => "BAD_DIGEST_SHAPE",
            Self::PlaintextMetadataForbidden => "PLAINTEXT_METADATA_FORBIDDEN",
            Self::CheckpointBindingMissing => "CHECKPOINT_BINDING_MISSING",
            Self::TransparencyReceiptMissing => "TRANSPARENCY_RECEIPT_MISSING",
            Self::AppendOnlyGuardMissing => "APPEND_ONLY_GUARD_MISSING",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditEventStoreWrite<'a> {
    pub chain_decision: SealedAuditEventChainDecision,
    pub event_sequence: i64,
    pub event_hash: &'a [u8],
    pub previous_event_hash: &'a [u8],
    pub record_digest: &'a [u8],
    pub merkle_root_hash: &'a [u8],
    pub checkpoint_id: &'a [u8],
    pub checkpoint_signature: &'a [u8],
    pub transparency_receipt: &'a [u8],
    pub witness_receipt: &'a [u8],
    pub event_kind: SealedAuditEventKind,
    pub anchor_kind: SealedAuditAnchorKind,
    pub sealed_payload_len: i32,
    pub plaintext_metadata_fields: i32,
    pub append_only_guard: bool,
    pub checkpoint_binds_chain: bool,
    pub receipt_binds_checkpoint: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SealedAuditEventStoreRecord {
    pub event_sequence: i64,
    pub event_hash: Vec<u8>,
    pub previous_event_hash: Vec<u8>,
    pub record_digest: Vec<u8>,
    pub merkle_root_hash: Vec<u8>,
    pub checkpoint_id: Vec<u8>,
    pub checkpoint_signature: Vec<u8>,
    pub transparency_receipt: Vec<u8>,
    pub witness_receipt: Vec<u8>,
    pub event_kind: SealedAuditEventKind,
    pub anchor_kind: SealedAuditAnchorKind,
    pub sealed_payload_len: i32,
    pub checkpoint_binds_chain: bool,
    pub receipt_binds_checkpoint: bool,
    pub plaintext_bytes_exposed: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditEventStoreDecision {
    pub accepted: bool,
    pub reason: SealedAuditEventStoreReason,
    pub persisted_record: bool,
    pub record_count: usize,
    pub event_sequence: i64,
    pub can_publish_receipt: bool,
    pub can_detect_replay: bool,
    pub append_only: bool,
    pub keeps_digest_only: bool,
    pub keeps_plaintext_metadata: bool,
    pub plaintext_bytes_exposed: bool,
}

pub struct AcceptedSealedAuditEventStoreWrite<'a> {
    write: SealedAuditEventStoreWrite<'a>,
    decision: SealedAuditEventStoreDecision,
}

impl<'a> AcceptedSealedAuditEventStoreWrite<'a> {
    pub const fn write(&self) -> SealedAuditEventStoreWrite<'a> {
        self.write
    }

    pub const fn decision(&self) -> &SealedAuditEventStoreDecision {
        &self.decision
    }
}

pub trait SealedAuditEventStoreAdapter {
    type Error;

    fn put_accepted_sealed_audit_event(
        &mut self,
        write: AcceptedSealedAuditEventStoreWrite<'_>,
    ) -> Result<(), Self::Error>;

    fn read_sealed_audit_event_by_sequence(
        &self,
        event_sequence: i64,
    ) -> Result<Option<SealedAuditEventStoreRecord>, Self::Error>;

    fn read_sealed_audit_event_by_hash(
        &self,
        event_hash: &[u8],
    ) -> Result<Option<SealedAuditEventStoreRecord>, Self::Error>;

    fn sealed_audit_checkpoint_recorded(&self, checkpoint_id: &[u8]) -> Result<bool, Self::Error>;

    fn sealed_audit_highest_event_sequence(&self) -> Result<Option<i64>, Self::Error>;

    fn sealed_audit_event_record_count(&self) -> Result<usize, Self::Error>;
}

pub fn evaluate_sealed_audit_event_store_write(
    write: SealedAuditEventStoreWrite<'_>,
) -> SealedAuditEventStoreDecision {
    if !write.chain_decision.accepted
        || !write.chain_decision.can_append_event
        || !write.chain_decision.tamper_evident
        || !write.chain_decision.append_only
        || write.chain_decision.plaintext_bytes_exposed
    {
        return sealed_audit_event_store_reject(
            write,
            SealedAuditEventStoreReason::ChainRejected,
            false,
        );
    }

    if write.event_sequence < 0
        || write.event_sequence != write.chain_decision.event_sequence
        || write.event_hash.len() != 32
        || (write.event_sequence > 0 && write.previous_event_hash.len() != 32)
        || write.record_digest.len() != 32
        || write.merkle_root_hash.len() != 32
        || write.checkpoint_id.len() != 32
        || write.checkpoint_signature.len() < 64
        || write.sealed_payload_len <= 0
    {
        return sealed_audit_event_store_reject(
            write,
            SealedAuditEventStoreReason::BadDigestShape,
            false,
        );
    }

    if write.event_kind != write.chain_decision.event_kind
        || write.anchor_kind != write.chain_decision.anchor_kind
        || !write.checkpoint_binds_chain
    {
        return sealed_audit_event_store_reject(
            write,
            SealedAuditEventStoreReason::CheckpointBindingMissing,
            false,
        );
    }

    if write.plaintext_metadata_fields != 0 {
        return sealed_audit_event_store_reject(
            write,
            SealedAuditEventStoreReason::PlaintextMetadataForbidden,
            false,
        );
    }

    if write.chain_decision.can_publish_transparency_receipt
        && (write.transparency_receipt.len() < 64 || !write.receipt_binds_checkpoint)
    {
        return sealed_audit_event_store_reject(
            write,
            SealedAuditEventStoreReason::TransparencyReceiptMissing,
            false,
        );
    }

    if write.anchor_kind.requires_witness_quorum() && write.witness_receipt.len() < 64 {
        return sealed_audit_event_store_reject(
            write,
            SealedAuditEventStoreReason::TransparencyReceiptMissing,
            false,
        );
    }

    if !write.append_only_guard {
        return sealed_audit_event_store_reject(
            write,
            SealedAuditEventStoreReason::AppendOnlyGuardMissing,
            false,
        );
    }

    sealed_audit_event_store_accept(
        0,
        write.event_sequence,
        write.chain_decision.can_publish_transparency_receipt,
    )
}

pub fn put_sealed_audit_event_record<S>(
    store: &mut S,
    write: SealedAuditEventStoreWrite<'_>,
) -> Result<SealedAuditEventStoreDecision, S::Error>
where
    S: SealedAuditEventStoreAdapter + ?Sized,
{
    let record_count = store.sealed_audit_event_record_count()?;
    let decision = evaluate_sealed_audit_event_store_write(write);
    if !decision.accepted {
        return Ok(SealedAuditEventStoreDecision {
            record_count,
            ..decision
        });
    }

    if store
        .read_sealed_audit_event_by_sequence(write.event_sequence)?
        .is_some()
    {
        return Ok(sealed_audit_event_store_reject_with_count(
            write,
            SealedAuditEventStoreReason::DuplicateSequence,
            record_count,
        ));
    }

    if let Some(highest_sequence) = store.sealed_audit_highest_event_sequence()? {
        if write.event_sequence <= highest_sequence {
            return Ok(sealed_audit_event_store_reject_with_count(
                write,
                SealedAuditEventStoreReason::RollbackSequence,
                record_count,
            ));
        }
    }

    if store
        .read_sealed_audit_event_by_hash(write.event_hash)?
        .is_some()
    {
        return Ok(sealed_audit_event_store_reject_with_count(
            write,
            SealedAuditEventStoreReason::DuplicateEventHash,
            record_count,
        ));
    }

    if store.sealed_audit_checkpoint_recorded(write.checkpoint_id)? {
        return Ok(sealed_audit_event_store_reject_with_count(
            write,
            SealedAuditEventStoreReason::DuplicateCheckpoint,
            record_count,
        ));
    }

    store
        .put_accepted_sealed_audit_event(AcceptedSealedAuditEventStoreWrite { write, decision })?;
    let record_count = store.sealed_audit_event_record_count()?;
    Ok(SealedAuditEventStoreDecision {
        record_count,
        ..decision
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeSealedAuditEventStore {
    records_by_sequence: BTreeMap<i64, SealedAuditEventStoreRecord>,
    sequences_by_hash: BTreeMap<Vec<u8>, i64>,
    checkpoint_ids: BTreeSet<Vec<u8>>,
}

impl PrototypeSealedAuditEventStore {
    pub fn put(&mut self, write: SealedAuditEventStoreWrite<'_>) -> SealedAuditEventStoreDecision {
        match put_sealed_audit_event_record(self, write) {
            Ok(decision) => decision,
            Err(error) => match error {},
        }
    }

    pub fn get_by_sequence(&self, event_sequence: i64) -> Option<&SealedAuditEventStoreRecord> {
        self.records_by_sequence.get(&event_sequence)
    }

    pub fn get_by_hash(&self, event_hash: &[u8]) -> Option<&SealedAuditEventStoreRecord> {
        self.sequences_by_hash
            .get(event_hash)
            .and_then(|sequence| self.records_by_sequence.get(sequence))
    }

    pub fn checkpoint_recorded(&self, checkpoint_id: &[u8]) -> bool {
        self.checkpoint_ids.contains(checkpoint_id)
    }

    pub fn highest_event_sequence(&self) -> Option<i64> {
        self.records_by_sequence.keys().next_back().copied()
    }

    pub fn len(&self) -> usize {
        self.records_by_sequence.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records_by_sequence.is_empty()
    }
}

impl SealedAuditEventStoreAdapter for PrototypeSealedAuditEventStore {
    type Error = Infallible;

    fn put_accepted_sealed_audit_event(
        &mut self,
        write: AcceptedSealedAuditEventStoreWrite<'_>,
    ) -> Result<(), Self::Error> {
        let request = write.write();
        let record = SealedAuditEventStoreRecord {
            event_sequence: request.event_sequence,
            event_hash: request.event_hash.to_vec(),
            previous_event_hash: request.previous_event_hash.to_vec(),
            record_digest: request.record_digest.to_vec(),
            merkle_root_hash: request.merkle_root_hash.to_vec(),
            checkpoint_id: request.checkpoint_id.to_vec(),
            checkpoint_signature: request.checkpoint_signature.to_vec(),
            transparency_receipt: request.transparency_receipt.to_vec(),
            witness_receipt: request.witness_receipt.to_vec(),
            event_kind: request.event_kind,
            anchor_kind: request.anchor_kind,
            sealed_payload_len: request.sealed_payload_len,
            checkpoint_binds_chain: request.checkpoint_binds_chain,
            receipt_binds_checkpoint: request.receipt_binds_checkpoint,
            plaintext_bytes_exposed: false,
        };
        self.sequences_by_hash
            .insert(record.event_hash.clone(), record.event_sequence);
        self.checkpoint_ids.insert(record.checkpoint_id.clone());
        self.records_by_sequence
            .insert(record.event_sequence, record);
        Ok(())
    }

    fn read_sealed_audit_event_by_sequence(
        &self,
        event_sequence: i64,
    ) -> Result<Option<SealedAuditEventStoreRecord>, Self::Error> {
        Ok(self.get_by_sequence(event_sequence).cloned())
    }

    fn read_sealed_audit_event_by_hash(
        &self,
        event_hash: &[u8],
    ) -> Result<Option<SealedAuditEventStoreRecord>, Self::Error> {
        Ok(self.get_by_hash(event_hash).cloned())
    }

    fn sealed_audit_checkpoint_recorded(&self, checkpoint_id: &[u8]) -> Result<bool, Self::Error> {
        Ok(self.checkpoint_recorded(checkpoint_id))
    }

    fn sealed_audit_highest_event_sequence(&self) -> Result<Option<i64>, Self::Error> {
        Ok(self.highest_event_sequence())
    }

    fn sealed_audit_event_record_count(&self) -> Result<usize, Self::Error> {
        Ok(self.records_by_sequence.len())
    }
}

const fn sealed_audit_event_store_accept(
    record_count: usize,
    event_sequence: i64,
    can_publish_receipt: bool,
) -> SealedAuditEventStoreDecision {
    SealedAuditEventStoreDecision {
        accepted: true,
        reason: SealedAuditEventStoreReason::Accepted,
        persisted_record: true,
        record_count,
        event_sequence,
        can_publish_receipt,
        can_detect_replay: true,
        append_only: true,
        keeps_digest_only: true,
        keeps_plaintext_metadata: false,
        plaintext_bytes_exposed: false,
    }
}

const fn sealed_audit_event_store_reject(
    write: SealedAuditEventStoreWrite<'_>,
    reason: SealedAuditEventStoreReason,
    plaintext_bytes_exposed: bool,
) -> SealedAuditEventStoreDecision {
    sealed_audit_event_store_reject_with_count(write, reason, 0)
        .with_plaintext_exposure(plaintext_bytes_exposed)
}

const fn sealed_audit_event_store_reject_with_count(
    write: SealedAuditEventStoreWrite<'_>,
    reason: SealedAuditEventStoreReason,
    record_count: usize,
) -> SealedAuditEventStoreDecision {
    SealedAuditEventStoreDecision {
        accepted: false,
        reason,
        persisted_record: false,
        record_count,
        event_sequence: write.event_sequence,
        can_publish_receipt: false,
        can_detect_replay: true,
        append_only: true,
        keeps_digest_only: true,
        keeps_plaintext_metadata: false,
        plaintext_bytes_exposed: false,
    }
}

impl SealedAuditEventStoreDecision {
    const fn with_plaintext_exposure(mut self, plaintext_bytes_exposed: bool) -> Self {
        self.plaintext_bytes_exposed = plaintext_bytes_exposed;
        self
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SealedAuditCheckpointSignatureAlgorithm {
    Ed25519,
    EcdsaP256Sha256,
    MlDsa44,
    HybridEd25519MlDsa44,
    Unknown,
}

impl SealedAuditCheckpointSignatureAlgorithm {
    pub const fn code(self) -> i32 {
        match self {
            Self::Ed25519 => 1,
            Self::EcdsaP256Sha256 => 2,
            Self::MlDsa44 => 3,
            Self::HybridEd25519MlDsa44 => 4,
            Self::Unknown => 5,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Ed25519 => "ed25519",
            Self::EcdsaP256Sha256 => "ecdsa_p256_sha256",
            Self::MlDsa44 => "ml_dsa_44",
            Self::HybridEd25519MlDsa44 => "hybrid_ed25519_ml_dsa_44",
            Self::Unknown => "unknown",
        }
    }

    pub const fn is_supported(self) -> bool {
        matches!(
            self,
            Self::Ed25519 | Self::EcdsaP256Sha256 | Self::MlDsa44 | Self::HybridEd25519MlDsa44
        )
    }

    pub const fn is_post_quantum_or_hybrid(self) -> bool {
        matches!(self, Self::MlDsa44 | Self::HybridEd25519MlDsa44)
    }

    pub const fn checkpoint_signature_min_len(self) -> i32 {
        match self {
            Self::Ed25519 => 64,
            Self::EcdsaP256Sha256 => 64,
            Self::MlDsa44 => 2420,
            Self::HybridEd25519MlDsa44 => 2484,
            Self::Unknown => 0,
        }
    }

    pub const fn witness_cosignature_min_len(self) -> i32 {
        match self {
            Self::Ed25519 => 76,
            Self::EcdsaP256Sha256 => 76,
            Self::MlDsa44 => 2432,
            Self::HybridEd25519MlDsa44 => 2508,
            Self::Unknown => 0,
        }
    }
}

