#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditWitnessCheckpointInput {
    pub store_decision: SealedAuditEventStoreDecision,
    pub anchor_kind: SealedAuditAnchorKind,
    pub signature_algorithm: SealedAuditCheckpointSignatureAlgorithm,
    pub checkpoint_origin_len: i32,
    pub log_id_digest_len: i32,
    pub checkpoint_timestamp_s: i64,
    pub checkpoint_size: i64,
    pub previous_checkpoint_size: i64,
    pub checkpoint_root_hash_len: i32,
    pub checkpoint_signature_len: i32,
    pub signing_key_id_digest_len: i32,
    pub signing_key_not_expired: bool,
    pub signing_key_rotation_window_valid: bool,
    pub previous_signing_key_retained_for_verification: bool,
    pub consistency_proof_verified: bool,
    pub consistency_proof_hash_count: i32,
    pub witness_count: i32,
    pub witness_threshold: i32,
    pub witness_operator_count: i32,
    pub witness_key_pins_present: bool,
    pub witness_cosignature_bytes: i32,
    pub cosignatures_timestamped: bool,
    pub cosignatures_bind_checkpoint: bool,
    pub split_view_evidence_present: bool,
    pub monitor_query_uses_private_retrieval: bool,
    pub monitor_query_plaintext_selectors: i32,
    pub monitor_receives_only_digests: bool,
    pub local_latest_checkpoint_available: bool,
    pub recovery_checkpoint_authenticated: bool,
    pub recovery_requires_user_verification: bool,
}

impl SealedAuditWitnessCheckpointInput {
    pub fn evaluate(self) -> SealedAuditWitnessCheckpointDecision {
        evaluate_sealed_audit_witness_checkpoint(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditWitnessCheckpointDecision {
    pub accepted: bool,
    pub reason: SealedAuditWitnessCheckpointReason,
    pub anchor_kind: SealedAuditAnchorKind,
    pub signature_algorithm: SealedAuditCheckpointSignatureAlgorithm,
    pub store_event_sequence: i64,
    pub checkpoint_size: i64,
    pub witness_threshold: i32,
    pub can_publish_checkpoint: bool,
    pub can_request_witness_cosignature: bool,
    pub can_monitor_privately: bool,
    pub can_detect_split_view: bool,
    pub requires_witness_repair: bool,
    pub requires_key_rotation: bool,
    pub requires_user_warning: bool,
    pub requires_local_recovery: bool,
    pub plaintext_bytes_exposed: bool,
}

pub fn evaluate_sealed_audit_witness_checkpoint(
    input: SealedAuditWitnessCheckpointInput,
) -> SealedAuditWitnessCheckpointDecision {
    if !input.store_decision.accepted
        || !input.store_decision.persisted_record
        || !input.store_decision.append_only
        || !input.store_decision.keeps_digest_only
        || input.store_decision.keeps_plaintext_metadata
        || input.store_decision.plaintext_bytes_exposed
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::StoreRejected,
            false,
            false,
            false,
            false,
            input.store_decision.plaintext_bytes_exposed,
        );
    }

    if !input.anchor_kind.requires_witness_quorum() {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::AnchorRejected,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.checkpoint_origin_len <= 0
        || input.checkpoint_origin_len > 255
        || input.log_id_digest_len != 32
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::LogOriginRejected,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.checkpoint_timestamp_s <= 0
        || input.checkpoint_size <= 0
        || input.previous_checkpoint_size < 0
        || input.checkpoint_root_hash_len != 32
        || input.checkpoint_size < input.store_decision.event_sequence + 1
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::CheckpointShapeRejected,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.checkpoint_size <= input.previous_checkpoint_size {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::StaleCheckpoint,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if !input.signature_algorithm.is_supported()
        || !input.signature_algorithm.is_post_quantum_or_hybrid()
        || input.checkpoint_signature_len < input.signature_algorithm.checkpoint_signature_min_len()
        || input.signing_key_id_digest_len != 32
        || !input.signing_key_not_expired
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::SigningKeyRejected,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if !input.signing_key_rotation_window_valid
        || !input.previous_signing_key_retained_for_verification
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::KeyRotationRejected,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if !input.consistency_proof_verified
        || input.consistency_proof_hash_count < 0
        || input.consistency_proof_hash_count > 63
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::ConsistencyProofRejected,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if input.witness_threshold < 2
        || input.witness_count < input.witness_threshold
        || input.witness_operator_count < 2
        || !input.witness_key_pins_present
        || input.witness_cosignature_bytes
            < input.witness_threshold * input.signature_algorithm.witness_cosignature_min_len()
        || !input.cosignatures_timestamped
        || !input.cosignatures_bind_checkpoint
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::WitnessQuorumRejected,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if input.split_view_evidence_present {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::SplitViewEvidence,
            true,
            false,
            true,
            false,
            false,
        );
    }

    if !input.monitor_query_uses_private_retrieval
        || input.monitor_query_plaintext_selectors != 0
        || !input.monitor_receives_only_digests
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::MonitorPrivacyRejected,
            false,
            false,
            false,
            false,
            input.monitor_query_plaintext_selectors != 0,
        );
    }

    let requires_local_recovery = !input.local_latest_checkpoint_available;
    if requires_local_recovery
        && (!input.recovery_checkpoint_authenticated || !input.recovery_requires_user_verification)
    {
        return sealed_audit_witness_checkpoint_reject(
            input,
            SealedAuditWitnessCheckpointReason::RecoveryStateRejected,
            false,
            false,
            true,
            true,
            false,
        );
    }

    SealedAuditWitnessCheckpointDecision {
        accepted: true,
        reason: SealedAuditWitnessCheckpointReason::Accepted,
        anchor_kind: input.anchor_kind,
        signature_algorithm: input.signature_algorithm,
        store_event_sequence: input.store_decision.event_sequence,
        checkpoint_size: input.checkpoint_size,
        witness_threshold: input.witness_threshold,
        can_publish_checkpoint: true,
        can_request_witness_cosignature: true,
        can_monitor_privately: true,
        can_detect_split_view: true,
        requires_witness_repair: false,
        requires_key_rotation: false,
        requires_user_warning: false,
        requires_local_recovery,
        plaintext_bytes_exposed: false,
    }
}

const fn sealed_audit_witness_checkpoint_reject(
    input: SealedAuditWitnessCheckpointInput,
    reason: SealedAuditWitnessCheckpointReason,
    requires_witness_repair: bool,
    requires_key_rotation: bool,
    requires_user_warning: bool,
    requires_local_recovery: bool,
    plaintext_bytes_exposed: bool,
) -> SealedAuditWitnessCheckpointDecision {
    SealedAuditWitnessCheckpointDecision {
        accepted: false,
        reason,
        anchor_kind: input.anchor_kind,
        signature_algorithm: input.signature_algorithm,
        store_event_sequence: input.store_decision.event_sequence,
        checkpoint_size: input.checkpoint_size,
        witness_threshold: input.witness_threshold,
        can_publish_checkpoint: false,
        can_request_witness_cosignature: false,
        can_monitor_privately: false,
        can_detect_split_view: true,
        requires_witness_repair,
        requires_key_rotation,
        requires_user_warning,
        requires_local_recovery,
        plaintext_bytes_exposed,
    }
}

