pub struct AcceptedSealedAuditVerifierPolicySnapshot<'a> {
    snapshot: SealedAuditVerifierPolicySnapshot<'a>,
    decision: SealedAuditVerifierPolicyDecision,
}

impl<'a> AcceptedSealedAuditVerifierPolicySnapshot<'a> {
    pub const fn snapshot(&self) -> SealedAuditVerifierPolicySnapshot<'a> {
        self.snapshot
    }

    pub const fn decision(&self) -> &SealedAuditVerifierPolicyDecision {
        &self.decision
    }
}

pub trait SealedAuditVerifierPolicyStore {
    type Error;

    fn put_accepted_verifier_policy_snapshot(
        &mut self,
        snapshot: AcceptedSealedAuditVerifierPolicySnapshot<'_>,
    ) -> Result<(), Self::Error>;

    fn read_verifier_policy_snapshot_by_digest(
        &self,
        policy_snapshot_digest: &[u8],
    ) -> Result<Option<SealedAuditVerifierPolicyRecord>, Self::Error>;

    fn read_latest_verifier_policy_snapshot(
        &self,
    ) -> Result<Option<SealedAuditVerifierPolicyRecord>, Self::Error>;

    fn verifier_policy_snapshot_count(&self) -> Result<usize, Self::Error>;
}

pub fn evaluate_sealed_audit_verifier_policy_snapshot(
    snapshot: SealedAuditVerifierPolicySnapshot<'_>,
) -> SealedAuditVerifierPolicyDecision {
    if !snapshot.proof_cache_decision.accepted
        || !snapshot.proof_cache_decision.can_verify_offline
        || !snapshot.proof_cache_decision.can_refresh_monitor
        || !snapshot.proof_cache_decision.can_show_ui_status
        || snapshot.proof_cache_decision.plaintext_bytes_exposed
    {
        return sealed_audit_verifier_policy_reject(
            snapshot,
            SealedAuditVerifierPolicyReason::ProofCacheRejected,
            false,
            false,
            false,
            false,
            snapshot.proof_cache_decision.plaintext_bytes_exposed,
        );
    }

    if snapshot.policy_format_version != 1
        || snapshot.policy_snapshot_digest.len() != 32
        || !(snapshot.previous_policy_snapshot_digest.is_empty()
            || snapshot.previous_policy_snapshot_digest.len() == 32)
        || snapshot.log_key_pinset_digest.len() != 32
        || snapshot.witness_key_pinset_digest.len() != 32
        || snapshot.monitor_query_plan_digest.len() != 32
        || snapshot.proof_cache_digest.len() != 32
        || snapshot.policy_epoch < snapshot.proof_cache_decision.verifier_policy_epoch
        || snapshot.imported_at_s <= 0
        || snapshot.verification_time_s < snapshot.imported_at_s
        || snapshot.expires_at_s <= snapshot.imported_at_s
        || snapshot.proof_cache_log_index != snapshot.proof_cache_decision.log_index
        || snapshot.latest_checked_log_index < snapshot.proof_cache_log_index
        || snapshot.log_key_pin_count < 1
        || snapshot.witness_quorum_threshold < 1
        || snapshot.witness_key_pin_count < snapshot.witness_quorum_threshold
        || snapshot.private_monitor_endpoint_count < 1
        || snapshot.monitor_freshness_max_age_s <= 0
        || snapshot.monitor_query_plaintext_selector_count < 0
        || snapshot.plaintext_metadata_fields < 0
        || snapshot.split_view_evidence_count < 0
        || !snapshot.policy_signature_verified
        || !snapshot.policy_consistency_proof_verified
        || !snapshot.offline_reverification_passed
        || !snapshot.scheduler_state_encrypted
        || !snapshot.scheduler_append_only
    {
        return sealed_audit_verifier_policy_reject(
            snapshot,
            SealedAuditVerifierPolicyReason::BadRecordShape,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if snapshot.verification_time_s >= snapshot.expires_at_s {
        return sealed_audit_verifier_policy_reject(
            snapshot,
            SealedAuditVerifierPolicyReason::PolicySnapshotExpired,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if snapshot.key_rotation_required && !snapshot.key_rotation_authenticated {
        return sealed_audit_verifier_policy_reject(
            snapshot,
            SealedAuditVerifierPolicyReason::KeyRotationRequired,
            true,
            false,
            true,
            false,
            false,
        );
    }

    if snapshot.monitor_last_refresh_s <= 0
        || snapshot.monitor_last_refresh_s > snapshot.verification_time_s
        || snapshot.verification_time_s - snapshot.monitor_last_refresh_s
            > snapshot.monitor_freshness_max_age_s
    {
        return sealed_audit_verifier_policy_reject(
            snapshot,
            SealedAuditVerifierPolicyReason::MonitorFreshnessStale,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if snapshot.split_view_evidence_count != 0 {
        return sealed_audit_verifier_policy_reject(
            snapshot,
            SealedAuditVerifierPolicyReason::SplitViewEscalationRequired,
            true,
            true,
            false,
            true,
            false,
        );
    }

    if snapshot.plaintext_metadata_fields != 0
        || snapshot.monitor_query_plaintext_selector_count != 0
        || !snapshot.ui_status_digest_only
    {
        return sealed_audit_verifier_policy_reject(
            snapshot,
            SealedAuditVerifierPolicyReason::PlaintextMetadataForbidden,
            false,
            false,
            false,
            false,
            snapshot.plaintext_metadata_fields != 0
                || snapshot.monitor_query_plaintext_selector_count != 0,
        );
    }

    sealed_audit_verifier_policy_accept(
        0,
        snapshot.policy_epoch,
        snapshot.proof_cache_log_index,
        snapshot.latest_checked_log_index,
    )
}

pub fn put_sealed_audit_verifier_policy_snapshot<S>(
    store: &mut S,
    snapshot: SealedAuditVerifierPolicySnapshot<'_>,
) -> Result<SealedAuditVerifierPolicyDecision, S::Error>
where
    S: SealedAuditVerifierPolicyStore + ?Sized,
{
    let snapshot_count = store.verifier_policy_snapshot_count()?;
    let decision = evaluate_sealed_audit_verifier_policy_snapshot(snapshot);
    if !decision.accepted {
        return Ok(SealedAuditVerifierPolicyDecision {
            snapshot_count,
            ..decision
        });
    }

    if store
        .read_verifier_policy_snapshot_by_digest(snapshot.policy_snapshot_digest)?
        .is_some()
    {
        return Ok(sealed_audit_verifier_policy_reject_with_count(
            snapshot,
            SealedAuditVerifierPolicyReason::BadRecordShape,
            snapshot_count,
        ));
    }

    if let Some(latest) = store.read_latest_verifier_policy_snapshot()? {
        if snapshot.policy_epoch <= latest.policy_epoch {
            return Ok(sealed_audit_verifier_policy_reject_with_count(
                snapshot,
                SealedAuditVerifierPolicyReason::PolicySnapshotExpired,
                snapshot_count,
            )
            .with_policy_refresh(true));
        }
    }

    store.put_accepted_verifier_policy_snapshot(AcceptedSealedAuditVerifierPolicySnapshot {
        snapshot,
        decision,
    })?;
    let snapshot_count = store.verifier_policy_snapshot_count()?;
    Ok(SealedAuditVerifierPolicyDecision {
        snapshot_count,
        ..decision
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeSealedAuditVerifierPolicyStore {
    records_by_digest: BTreeMap<Vec<u8>, SealedAuditVerifierPolicyRecord>,
}

impl PrototypeSealedAuditVerifierPolicyStore {
    pub fn put(
        &mut self,
        snapshot: SealedAuditVerifierPolicySnapshot<'_>,
    ) -> SealedAuditVerifierPolicyDecision {
        match put_sealed_audit_verifier_policy_snapshot(self, snapshot) {
            Ok(decision) => decision,
            Err(error) => match error {},
        }
    }

    pub fn get_by_digest(
        &self,
        policy_snapshot_digest: &[u8],
    ) -> Option<&SealedAuditVerifierPolicyRecord> {
        self.records_by_digest.get(policy_snapshot_digest)
    }

    pub fn latest(&self) -> Option<&SealedAuditVerifierPolicyRecord> {
        self.records_by_digest
            .values()
            .max_by_key(|record| record.policy_epoch)
    }

    pub fn len(&self) -> usize {
        self.records_by_digest.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records_by_digest.is_empty()
    }
}

impl SealedAuditVerifierPolicyStore for PrototypeSealedAuditVerifierPolicyStore {
    type Error = Infallible;

    fn put_accepted_verifier_policy_snapshot(
        &mut self,
        accepted: AcceptedSealedAuditVerifierPolicySnapshot<'_>,
    ) -> Result<(), Self::Error> {
        let request = accepted.snapshot();
        let record = SealedAuditVerifierPolicyRecord {
            policy_snapshot_digest: request.policy_snapshot_digest.to_vec(),
            previous_policy_snapshot_digest: request.previous_policy_snapshot_digest.to_vec(),
            log_key_pinset_digest: request.log_key_pinset_digest.to_vec(),
            witness_key_pinset_digest: request.witness_key_pinset_digest.to_vec(),
            monitor_query_plan_digest: request.monitor_query_plan_digest.to_vec(),
            proof_cache_digest: request.proof_cache_digest.to_vec(),
            policy_epoch: request.policy_epoch,
            imported_at_s: request.imported_at_s,
            verification_time_s: request.verification_time_s,
            expires_at_s: request.expires_at_s,
            proof_cache_log_index: request.proof_cache_log_index,
            latest_checked_log_index: request.latest_checked_log_index,
            monitor_last_refresh_s: request.monitor_last_refresh_s,
            plaintext_bytes_exposed: accepted.decision().plaintext_bytes_exposed,
        };
        self.records_by_digest
            .insert(record.policy_snapshot_digest.clone(), record);
        Ok(())
    }

    fn read_verifier_policy_snapshot_by_digest(
        &self,
        policy_snapshot_digest: &[u8],
    ) -> Result<Option<SealedAuditVerifierPolicyRecord>, Self::Error> {
        Ok(self.get_by_digest(policy_snapshot_digest).cloned())
    }

    fn read_latest_verifier_policy_snapshot(
        &self,
    ) -> Result<Option<SealedAuditVerifierPolicyRecord>, Self::Error> {
        Ok(self.latest().cloned())
    }

    fn verifier_policy_snapshot_count(&self) -> Result<usize, Self::Error> {
        Ok(self.records_by_digest.len())
    }
}

const fn sealed_audit_verifier_policy_accept(
    snapshot_count: usize,
    policy_epoch: i64,
    proof_cache_log_index: i64,
    latest_checked_log_index: i64,
) -> SealedAuditVerifierPolicyDecision {
    SealedAuditVerifierPolicyDecision {
        accepted: true,
        reason: SealedAuditVerifierPolicyReason::Accepted,
        persisted_snapshot: true,
        snapshot_count,
        policy_epoch,
        proof_cache_log_index,
        latest_checked_log_index,
        can_verify_offline: true,
        can_schedule_private_monitor: true,
        can_show_ui_status: true,
        requires_policy_refresh: false,
        requires_monitor_refresh: false,
        requires_key_rotation: false,
        escalates_split_view: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

const fn sealed_audit_verifier_policy_reject(
    snapshot: SealedAuditVerifierPolicySnapshot<'_>,
    reason: SealedAuditVerifierPolicyReason,
    requires_policy_refresh: bool,
    requires_monitor_refresh: bool,
    requires_key_rotation: bool,
    escalates_split_view: bool,
    plaintext_bytes_exposed: bool,
) -> SealedAuditVerifierPolicyDecision {
    sealed_audit_verifier_policy_reject_with_count(snapshot, reason, 0)
        .with_policy_refresh(requires_policy_refresh)
        .with_monitor_refresh(requires_monitor_refresh)
        .with_key_rotation(requires_key_rotation)
        .with_split_view_escalation(escalates_split_view)
        .with_plaintext_exposure(plaintext_bytes_exposed)
}

const fn sealed_audit_verifier_policy_reject_with_count(
    snapshot: SealedAuditVerifierPolicySnapshot<'_>,
    reason: SealedAuditVerifierPolicyReason,
    snapshot_count: usize,
) -> SealedAuditVerifierPolicyDecision {
    SealedAuditVerifierPolicyDecision {
        accepted: false,
        reason,
        persisted_snapshot: false,
        snapshot_count,
        policy_epoch: snapshot.policy_epoch,
        proof_cache_log_index: snapshot.proof_cache_log_index,
        latest_checked_log_index: snapshot.latest_checked_log_index,
        can_verify_offline: false,
        can_schedule_private_monitor: false,
        can_show_ui_status: false,
        requires_policy_refresh: false,
        requires_monitor_refresh: false,
        requires_key_rotation: false,
        escalates_split_view: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

impl SealedAuditVerifierPolicyDecision {
    const fn with_policy_refresh(mut self, requires_policy_refresh: bool) -> Self {
        self.requires_policy_refresh = requires_policy_refresh;
        self
    }

    const fn with_monitor_refresh(mut self, requires_monitor_refresh: bool) -> Self {
        self.requires_monitor_refresh = requires_monitor_refresh;
        self
    }

    const fn with_key_rotation(mut self, requires_key_rotation: bool) -> Self {
        self.requires_key_rotation = requires_key_rotation;
        self
    }

    const fn with_split_view_escalation(mut self, escalates_split_view: bool) -> Self {
        self.escalates_split_view = escalates_split_view;
        self
    }

    const fn with_plaintext_exposure(mut self, plaintext_bytes_exposed: bool) -> Self {
        self.plaintext_bytes_exposed = plaintext_bytes_exposed;
        self
    }
}

