pub fn evaluate_sealed_audit_incident_evidence(
    write: SealedAuditIncidentEvidenceWrite<'_>,
) -> SealedAuditIncidentEvidenceDecision {
    if !write.verifier_policy_decision.accepted
        || !write.verifier_policy_decision.can_verify_offline
        || !write.verifier_policy_decision.can_schedule_private_monitor
        || !write.verifier_policy_decision.can_show_ui_status
        || write.verifier_policy_decision.plaintext_bytes_exposed
    {
        return sealed_audit_incident_evidence_reject(
            write,
            SealedAuditIncidentEvidenceReason::VerifierPolicyRejected,
            false,
            false,
            false,
            false,
            write.verifier_policy_decision.plaintext_bytes_exposed,
        );
    }

    if write.incident_format_version != 1
        || write.incident_id.len() != 32
        || write.verifier_policy_digest.len() != 32
        || write.proof_cache_digest.len() != 32
        || write.checkpoint_digest.len() != 32
        || write.witness_operator_digest.len() != 32
        || write.contradiction_digest.len() != 32
        || write.missing_proof_report_digest.len() != 32
        || write.monitor_report_digest.len() != 32
        || write.accountability_route_digest.len() != 32
        || write.policy_epoch != write.verifier_policy_decision.policy_epoch
        || write.proof_cache_log_index != write.verifier_policy_decision.proof_cache_log_index
        || write.latest_checked_log_index != write.verifier_policy_decision.latest_checked_log_index
        || write.latest_checked_log_index < write.proof_cache_log_index
        || write.reported_at_s <= 0
        || write.evidence_observed_at_s <= 0
        || write.evidence_observed_at_s > write.reported_at_s
        || write.split_view_evidence_count < 0
        || write.missing_proof_count < 0
        || write.monitor_failure_count < 0
        || write.operator_signature_count < 0
        || write.witness_quorum_threshold < 1
        || write.retry_after_s < 0
        || write.plaintext_selector_count < 0
        || write.plaintext_metadata_fields < 0
        || !write.incident_signature_verified
        || !write.store_record_encrypted
        || !write.append_only_guard
    {
        return sealed_audit_incident_evidence_reject(
            write,
            SealedAuditIncidentEvidenceReason::BadRecordShape,
            false,
            false,
            false,
            write.retry_after_s > 0,
            false,
        );
    }

    if write.plaintext_selector_count != 0
        || write.plaintext_metadata_fields != 0
        || !write.ui_status_digest_only
    {
        return sealed_audit_incident_evidence_reject(
            write,
            SealedAuditIncidentEvidenceReason::PlaintextMetadataForbidden,
            false,
            false,
            false,
            write.retry_after_s > 0,
            write.plaintext_selector_count != 0
                || write.plaintext_metadata_fields != 0
                || !write.ui_status_digest_only,
        );
    }

    if write.split_view_evidence_count == 0
        && write.missing_proof_count == 0
        && write.monitor_failure_count == 0
    {
        return sealed_audit_incident_evidence_reject(
            write,
            SealedAuditIncidentEvidenceReason::NoIncidentEvidence,
            false,
            false,
            false,
            write.retry_after_s > 0,
            false,
        );
    }

    if (write.missing_proof_count > 0 && !write.missing_proof_report_blinded)
        || (write.monitor_failure_count > 0 && !write.monitor_report_private)
    {
        return sealed_audit_incident_evidence_reject(
            write,
            SealedAuditIncidentEvidenceReason::MissingProofReportRequired,
            true,
            false,
            false,
            write.retry_after_s > 0,
            false,
        );
    }

    if write.split_view_evidence_count > 0 && !write.contradiction_proof_verified {
        return sealed_audit_incident_evidence_reject(
            write,
            SealedAuditIncidentEvidenceReason::SplitViewEvidenceRequired,
            false,
            true,
            false,
            write.retry_after_s > 0,
            false,
        );
    }

    if write.operator_signature_count < write.witness_quorum_threshold
        || !write.accountability_route_configured
    {
        return sealed_audit_incident_evidence_reject(
            write,
            SealedAuditIncidentEvidenceReason::OperatorAccountabilityRequired,
            false,
            false,
            true,
            write.retry_after_s > 0,
            false,
        );
    }

    sealed_audit_incident_evidence_accept(0, write)
}

pub fn put_sealed_audit_incident_evidence_record<S>(
    store: &mut S,
    write: SealedAuditIncidentEvidenceWrite<'_>,
) -> Result<SealedAuditIncidentEvidenceDecision, S::Error>
where
    S: SealedAuditIncidentEvidenceStore + ?Sized,
{
    let record_count = store.incident_evidence_record_count()?;
    let decision = evaluate_sealed_audit_incident_evidence(write);
    if !decision.accepted {
        return Ok(SealedAuditIncidentEvidenceDecision {
            record_count,
            ..decision
        });
    }

    if store
        .read_sealed_audit_incident_by_id(write.incident_id)?
        .is_some()
    {
        return Ok(sealed_audit_incident_evidence_reject_with_count(
            write,
            SealedAuditIncidentEvidenceReason::BadRecordShape,
            record_count,
        ));
    }

    store.put_accepted_sealed_audit_incident_evidence(
        AcceptedSealedAuditIncidentEvidenceWrite { write, decision },
    )?;
    let record_count = store.incident_evidence_record_count()?;
    Ok(SealedAuditIncidentEvidenceDecision {
        record_count,
        ..decision
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeSealedAuditIncidentEvidenceStore {
    records_by_incident_id: BTreeMap<Vec<u8>, SealedAuditIncidentEvidenceRecord>,
}

impl PrototypeSealedAuditIncidentEvidenceStore {
    pub fn put(
        &mut self,
        write: SealedAuditIncidentEvidenceWrite<'_>,
    ) -> SealedAuditIncidentEvidenceDecision {
        match put_sealed_audit_incident_evidence_record(self, write) {
            Ok(decision) => decision,
            Err(error) => match error {},
        }
    }

    pub fn get_by_incident_id(
        &self,
        incident_id: &[u8],
    ) -> Option<&SealedAuditIncidentEvidenceRecord> {
        self.records_by_incident_id.get(incident_id)
    }

    pub fn len(&self) -> usize {
        self.records_by_incident_id.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records_by_incident_id.is_empty()
    }
}

impl SealedAuditIncidentEvidenceStore for PrototypeSealedAuditIncidentEvidenceStore {
    type Error = Infallible;

    fn put_accepted_sealed_audit_incident_evidence(
        &mut self,
        accepted: AcceptedSealedAuditIncidentEvidenceWrite<'_>,
    ) -> Result<(), Self::Error> {
        let request = accepted.write();
        let record = SealedAuditIncidentEvidenceRecord {
            incident_id: request.incident_id.to_vec(),
            verifier_policy_digest: request.verifier_policy_digest.to_vec(),
            proof_cache_digest: request.proof_cache_digest.to_vec(),
            checkpoint_digest: request.checkpoint_digest.to_vec(),
            witness_operator_digest: request.witness_operator_digest.to_vec(),
            contradiction_digest: request.contradiction_digest.to_vec(),
            missing_proof_report_digest: request.missing_proof_report_digest.to_vec(),
            monitor_report_digest: request.monitor_report_digest.to_vec(),
            accountability_route_digest: request.accountability_route_digest.to_vec(),
            policy_epoch: request.policy_epoch,
            proof_cache_log_index: request.proof_cache_log_index,
            latest_checked_log_index: request.latest_checked_log_index,
            reported_at_s: request.reported_at_s,
            evidence_observed_at_s: request.evidence_observed_at_s,
            split_view_evidence_count: request.split_view_evidence_count,
            missing_proof_count: request.missing_proof_count,
            monitor_failure_count: request.monitor_failure_count,
            operator_signature_count: request.operator_signature_count,
            witness_quorum_threshold: request.witness_quorum_threshold,
            can_escalate_incident: accepted.decision().can_escalate_incident,
            can_report_privately: accepted.decision().can_report_privately,
            suppressed_by_authenticated_policy: accepted
                .decision()
                .suppressed_by_authenticated_policy,
            plaintext_bytes_exposed: accepted.decision().plaintext_bytes_exposed,
        };
        self.records_by_incident_id
            .insert(record.incident_id.clone(), record);
        Ok(())
    }

    fn read_sealed_audit_incident_by_id(
        &self,
        incident_id: &[u8],
    ) -> Result<Option<SealedAuditIncidentEvidenceRecord>, Self::Error> {
        Ok(self.get_by_incident_id(incident_id).cloned())
    }

    fn incident_evidence_record_count(&self) -> Result<usize, Self::Error> {
        Ok(self.records_by_incident_id.len())
    }
}

const fn sealed_audit_incident_evidence_accept(
    record_count: usize,
    write: SealedAuditIncidentEvidenceWrite<'_>,
) -> SealedAuditIncidentEvidenceDecision {
    SealedAuditIncidentEvidenceDecision {
        accepted: true,
        reason: SealedAuditIncidentEvidenceReason::Accepted,
        persisted_record: true,
        record_count,
        policy_epoch: write.policy_epoch,
        proof_cache_log_index: write.proof_cache_log_index,
        latest_checked_log_index: write.latest_checked_log_index,
        can_escalate_incident: write.split_view_evidence_count > 0,
        can_report_privately: true,
        can_show_ui_status: true,
        requires_missing_proof_report: write.missing_proof_count > 0
            || write.monitor_failure_count > 0,
        requires_split_view_escalation: write.split_view_evidence_count > 0,
        requires_operator_accountability: write.split_view_evidence_count > 0
            || write.operator_signature_count >= write.witness_quorum_threshold,
        requires_retry_backoff: write.retry_after_s > 0,
        suppressed_by_authenticated_policy: write.suppression_authenticated,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

const fn sealed_audit_incident_evidence_reject(
    write: SealedAuditIncidentEvidenceWrite<'_>,
    reason: SealedAuditIncidentEvidenceReason,
    requires_missing_proof_report: bool,
    requires_split_view_escalation: bool,
    requires_operator_accountability: bool,
    requires_retry_backoff: bool,
    plaintext_bytes_exposed: bool,
) -> SealedAuditIncidentEvidenceDecision {
    sealed_audit_incident_evidence_reject_with_count(write, reason, 0)
        .with_missing_proof_report(requires_missing_proof_report)
        .with_split_view_escalation(requires_split_view_escalation)
        .with_operator_accountability(requires_operator_accountability)
        .with_retry_backoff(requires_retry_backoff)
        .with_plaintext_exposure(plaintext_bytes_exposed)
}

const fn sealed_audit_incident_evidence_reject_with_count(
    write: SealedAuditIncidentEvidenceWrite<'_>,
    reason: SealedAuditIncidentEvidenceReason,
    record_count: usize,
) -> SealedAuditIncidentEvidenceDecision {
    SealedAuditIncidentEvidenceDecision {
        accepted: false,
        reason,
        persisted_record: false,
        record_count,
        policy_epoch: write.policy_epoch,
        proof_cache_log_index: write.proof_cache_log_index,
        latest_checked_log_index: write.latest_checked_log_index,
        can_escalate_incident: false,
        can_report_privately: false,
        can_show_ui_status: false,
        requires_missing_proof_report: false,
        requires_split_view_escalation: false,
        requires_operator_accountability: false,
        requires_retry_backoff: false,
        suppressed_by_authenticated_policy: write.suppression_authenticated,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

impl SealedAuditIncidentEvidenceDecision {
    const fn with_missing_proof_report(mut self, requires_missing_proof_report: bool) -> Self {
        self.requires_missing_proof_report = requires_missing_proof_report;
        self
    }

    const fn with_split_view_escalation(mut self, requires_split_view_escalation: bool) -> Self {
        self.requires_split_view_escalation = requires_split_view_escalation;
        self
    }

    const fn with_operator_accountability(
        mut self,
        requires_operator_accountability: bool,
    ) -> Self {
        self.requires_operator_accountability = requires_operator_accountability;
        self
    }

    const fn with_retry_backoff(mut self, requires_retry_backoff: bool) -> Self {
        self.requires_retry_backoff = requires_retry_backoff;
        self
    }

    const fn with_plaintext_exposure(mut self, plaintext_bytes_exposed: bool) -> Self {
        self.plaintext_bytes_exposed = plaintext_bytes_exposed;
        self
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SealedAuditRecoveryExportReason {
    Accepted,
    IncidentEvidenceRejected,
    RestoreQuorumRequired,
    StalePolicySnapshot,
    RollbackExportRejected,
    DeviceBindingRequired,
    PlaintextMetadataForbidden,
    BadRecordShape,
}

impl SealedAuditRecoveryExportReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::Accepted => 0,
            Self::IncidentEvidenceRejected => 1,
            Self::RestoreQuorumRequired => 2,
            Self::StalePolicySnapshot => 3,
            Self::RollbackExportRejected => 4,
            Self::DeviceBindingRequired => 5,
            Self::PlaintextMetadataForbidden => 6,
            Self::BadRecordShape => 7,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Accepted => "ACCEPTED",
            Self::IncidentEvidenceRejected => "INCIDENT_EVIDENCE_REJECTED",
            Self::RestoreQuorumRequired => "RESTORE_QUORUM_REQUIRED",
            Self::StalePolicySnapshot => "STALE_POLICY_SNAPSHOT",
            Self::RollbackExportRejected => "ROLLBACK_EXPORT_REJECTED",
            Self::DeviceBindingRequired => "DEVICE_BINDING_REQUIRED",
            Self::PlaintextMetadataForbidden => "PLAINTEXT_METADATA_FORBIDDEN",
            Self::BadRecordShape => "BAD_RECORD_SHAPE",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditRecoveryExportWrite<'a> {
    pub incident_evidence_decision: SealedAuditIncidentEvidenceDecision,
    pub export_format_version: i32,
    pub export_manifest_digest: &'a [u8],
    pub previous_export_manifest_digest: &'a [u8],
    pub device_set_digest: &'a [u8],
    pub recovery_policy_digest: &'a [u8],
    pub verifier_policy_digest: &'a [u8],
    pub proof_cache_digest: &'a [u8],
    pub incident_id: &'a [u8],
    pub incident_evidence_digest: &'a [u8],
    pub export_ciphertext_digest: &'a [u8],
    pub restore_authorization_digest: &'a [u8],
    pub sync_state_digest: &'a [u8],
    pub audit_log_checkpoint_digest: &'a [u8],
    pub export_sequence: i64,
    pub previous_export_sequence: i64,
    pub policy_epoch: i64,
    pub proof_cache_log_index: i64,
    pub latest_checked_log_index: i64,
    pub created_at_s: i64,
    pub expires_at_s: i64,
    pub restored_at_s: i64,
    pub device_count: i32,
    pub device_quorum_threshold: i32,
    pub approving_device_count: i32,
    pub recovery_share_count: i32,
    pub recovery_share_threshold: i32,
    pub manifest_signature_verified: bool,
    pub device_binding_verified: bool,
    pub recovery_policy_verified: bool,
    pub export_ciphertext_encrypted: bool,
    pub export_ciphertext_authenticated: bool,
    pub restore_authorization_verified: bool,
    pub restore_quorum_met: bool,
    pub rollback_guard_verified: bool,
    pub previous_export_bound: bool,
    pub cross_device_sync_private: bool,
    pub incident_selectors_redacted: bool,
    pub audit_log_checkpoint_verified: bool,
    pub store_record_encrypted: bool,
    pub append_only_guard: bool,
    pub plaintext_selector_count: i32,
    pub plaintext_metadata_fields: i32,
    pub ui_status_digest_only: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SealedAuditRecoveryExportRecord {
    pub export_manifest_digest: Vec<u8>,
    pub previous_export_manifest_digest: Vec<u8>,
    pub device_set_digest: Vec<u8>,
    pub recovery_policy_digest: Vec<u8>,
    pub verifier_policy_digest: Vec<u8>,
    pub proof_cache_digest: Vec<u8>,
    pub incident_id: Vec<u8>,
    pub incident_evidence_digest: Vec<u8>,
    pub export_ciphertext_digest: Vec<u8>,
    pub restore_authorization_digest: Vec<u8>,
    pub sync_state_digest: Vec<u8>,
    pub audit_log_checkpoint_digest: Vec<u8>,
    pub export_sequence: i64,
    pub previous_export_sequence: i64,
    pub policy_epoch: i64,
    pub proof_cache_log_index: i64,
    pub latest_checked_log_index: i64,
    pub created_at_s: i64,
    pub expires_at_s: i64,
    pub restored_at_s: i64,
    pub device_count: i32,
    pub device_quorum_threshold: i32,
    pub approving_device_count: i32,
    pub recovery_share_count: i32,
    pub recovery_share_threshold: i32,
    pub can_export_state: bool,
    pub can_restore_state: bool,
    pub can_sync_cross_device: bool,
    pub plaintext_bytes_exposed: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditRecoveryExportDecision {
    pub accepted: bool,
    pub reason: SealedAuditRecoveryExportReason,
    pub persisted_record: bool,
    pub record_count: usize,
    pub export_sequence: i64,
    pub policy_epoch: i64,
    pub proof_cache_log_index: i64,
    pub latest_checked_log_index: i64,
    pub can_export_state: bool,
    pub can_restore_state: bool,
    pub can_sync_cross_device: bool,
    pub requires_restore_quorum: bool,
    pub requires_policy_refresh: bool,
    pub rejects_rollback: bool,
    pub requires_device_binding: bool,
    pub keeps_digest_only: bool,
    pub plaintext_bytes_exposed: bool,
}

pub struct AcceptedSealedAuditRecoveryExportWrite<'a> {
    write: SealedAuditRecoveryExportWrite<'a>,
    decision: SealedAuditRecoveryExportDecision,
}

impl<'a> AcceptedSealedAuditRecoveryExportWrite<'a> {
    pub const fn write(&self) -> SealedAuditRecoveryExportWrite<'a> {
        self.write
    }

    pub const fn decision(&self) -> &SealedAuditRecoveryExportDecision {
        &self.decision
    }
}

pub trait SealedAuditRecoveryExportStore {
    type Error;

    fn put_accepted_sealed_audit_recovery_export(
        &mut self,
        write: AcceptedSealedAuditRecoveryExportWrite<'_>,
    ) -> Result<(), Self::Error>;

    fn read_sealed_audit_recovery_export_by_digest(
        &self,
        export_manifest_digest: &[u8],
    ) -> Result<Option<SealedAuditRecoveryExportRecord>, Self::Error>;

    fn read_latest_sealed_audit_recovery_export(
        &self,
    ) -> Result<Option<SealedAuditRecoveryExportRecord>, Self::Error>;

    fn recovery_export_record_count(&self) -> Result<usize, Self::Error>;
}

pub fn evaluate_sealed_audit_recovery_export(
    write: SealedAuditRecoveryExportWrite<'_>,
) -> SealedAuditRecoveryExportDecision {
    if !write.incident_evidence_decision.accepted
        || !write.incident_evidence_decision.can_report_privately
        || !write.incident_evidence_decision.can_show_ui_status
        || !write.incident_evidence_decision.keeps_digest_only
        || write.incident_evidence_decision.plaintext_bytes_exposed
    {
        return sealed_audit_recovery_export_reject(
            write,
            SealedAuditRecoveryExportReason::IncidentEvidenceRejected,
            false,
            false,
            false,
            false,
            write.incident_evidence_decision.plaintext_bytes_exposed,
        );
    }

    if write.export_format_version != 1
        || write.export_manifest_digest.len() != 32
        || !(write.previous_export_manifest_digest.is_empty()
            || write.previous_export_manifest_digest.len() == 32)
        || write.device_set_digest.len() != 32
        || write.recovery_policy_digest.len() != 32
        || write.verifier_policy_digest.len() != 32
        || write.proof_cache_digest.len() != 32
        || write.incident_id.len() != 32
        || write.incident_evidence_digest.len() != 32
        || write.export_ciphertext_digest.len() != 32
        || write.restore_authorization_digest.len() != 32
        || write.sync_state_digest.len() != 32
        || write.audit_log_checkpoint_digest.len() != 32
        || write.export_sequence < 1
        || write.previous_export_sequence < 0
        || write.policy_epoch != write.incident_evidence_decision.policy_epoch
        || write.proof_cache_log_index != write.incident_evidence_decision.proof_cache_log_index
        || write.latest_checked_log_index
            != write.incident_evidence_decision.latest_checked_log_index
        || write.latest_checked_log_index < write.proof_cache_log_index
        || write.created_at_s <= 0
        || write.expires_at_s <= write.created_at_s
        || write.restored_at_s < 0
        || write.restored_at_s > write.expires_at_s
        || write.device_count < 1
        || write.device_quorum_threshold < 1
        || write.device_quorum_threshold > write.device_count
        || write.approving_device_count < 0
        || write.recovery_share_count < 0
        || write.recovery_share_threshold < 1
        || write.plaintext_selector_count < 0
        || write.plaintext_metadata_fields < 0
        || !write.manifest_signature_verified
        || !write.recovery_policy_verified
        || !write.export_ciphertext_encrypted
        || !write.export_ciphertext_authenticated
        || !write.rollback_guard_verified
        || !write.audit_log_checkpoint_verified
        || !write.store_record_encrypted
        || !write.append_only_guard
    {
        return sealed_audit_recovery_export_reject(
            write,
            SealedAuditRecoveryExportReason::BadRecordShape,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if write.created_at_s >= write.expires_at_s
        || (write.restored_at_s > 0 && write.restored_at_s >= write.expires_at_s)
        || write.policy_epoch < 1
    {
        return sealed_audit_recovery_export_reject(
            write,
            SealedAuditRecoveryExportReason::StalePolicySnapshot,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if write.export_sequence <= write.previous_export_sequence
        || (write.previous_export_sequence > 0 && !write.previous_export_bound)
    {
        return sealed_audit_recovery_export_reject(
            write,
            SealedAuditRecoveryExportReason::RollbackExportRejected,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if !write.device_binding_verified {
        return sealed_audit_recovery_export_reject(
            write,
            SealedAuditRecoveryExportReason::DeviceBindingRequired,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if !write.restore_authorization_verified
        || !write.restore_quorum_met
        || write.approving_device_count < write.device_quorum_threshold
        || write.recovery_share_count < write.recovery_share_threshold
    {
        return sealed_audit_recovery_export_reject(
            write,
            SealedAuditRecoveryExportReason::RestoreQuorumRequired,
            true,
            false,
            false,
            false,
            false,
        );
    }

    if write.plaintext_selector_count != 0
        || write.plaintext_metadata_fields != 0
        || !write.cross_device_sync_private
        || !write.incident_selectors_redacted
        || !write.ui_status_digest_only
    {
        return sealed_audit_recovery_export_reject(
            write,
            SealedAuditRecoveryExportReason::PlaintextMetadataForbidden,
            false,
            false,
            false,
            false,
            write.plaintext_selector_count != 0
                || write.plaintext_metadata_fields != 0
                || !write.incident_selectors_redacted
                || !write.ui_status_digest_only,
        );
    }

    sealed_audit_recovery_export_accept(0, write)
}

pub fn put_sealed_audit_recovery_export_record<S>(
    store: &mut S,
    write: SealedAuditRecoveryExportWrite<'_>,
) -> Result<SealedAuditRecoveryExportDecision, S::Error>
where
    S: SealedAuditRecoveryExportStore + ?Sized,
{
    let record_count = store.recovery_export_record_count()?;
    let decision = evaluate_sealed_audit_recovery_export(write);
    if !decision.accepted {
        return Ok(SealedAuditRecoveryExportDecision {
            record_count,
            ..decision
        });
    }

    if store
        .read_sealed_audit_recovery_export_by_digest(write.export_manifest_digest)?
        .is_some()
    {
        return Ok(sealed_audit_recovery_export_reject_with_count(
            write,
            SealedAuditRecoveryExportReason::BadRecordShape,
            record_count,
        ));
    }

    if let Some(latest) = store.read_latest_sealed_audit_recovery_export()? {
        if write.export_sequence <= latest.export_sequence {
            return Ok(sealed_audit_recovery_export_reject_with_count(
                write,
                SealedAuditRecoveryExportReason::RollbackExportRejected,
                record_count,
            )
            .with_rollback(true));
        }
    }

    store.put_accepted_sealed_audit_recovery_export(AcceptedSealedAuditRecoveryExportWrite {
        write,
        decision,
    })?;
    let record_count = store.recovery_export_record_count()?;
    Ok(SealedAuditRecoveryExportDecision {
        record_count,
        ..decision
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeSealedAuditRecoveryExportStore {
    records_by_digest: BTreeMap<Vec<u8>, SealedAuditRecoveryExportRecord>,
}

impl PrototypeSealedAuditRecoveryExportStore {
    pub fn put(
        &mut self,
        write: SealedAuditRecoveryExportWrite<'_>,
    ) -> SealedAuditRecoveryExportDecision {
        match put_sealed_audit_recovery_export_record(self, write) {
            Ok(decision) => decision,
            Err(error) => match error {},
        }
    }

    pub fn get_by_digest(
        &self,
        export_manifest_digest: &[u8],
    ) -> Option<&SealedAuditRecoveryExportRecord> {
        self.records_by_digest.get(export_manifest_digest)
    }

    pub fn latest(&self) -> Option<&SealedAuditRecoveryExportRecord> {
        self.records_by_digest
            .values()
            .max_by_key(|record| record.export_sequence)
    }

    pub fn len(&self) -> usize {
        self.records_by_digest.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records_by_digest.is_empty()
    }
}

impl SealedAuditRecoveryExportStore for PrototypeSealedAuditRecoveryExportStore {
    type Error = Infallible;

    fn put_accepted_sealed_audit_recovery_export(
        &mut self,
        accepted: AcceptedSealedAuditRecoveryExportWrite<'_>,
    ) -> Result<(), Self::Error> {
        let request = accepted.write();
        let record = SealedAuditRecoveryExportRecord {
            export_manifest_digest: request.export_manifest_digest.to_vec(),
            previous_export_manifest_digest: request.previous_export_manifest_digest.to_vec(),
            device_set_digest: request.device_set_digest.to_vec(),
            recovery_policy_digest: request.recovery_policy_digest.to_vec(),
            verifier_policy_digest: request.verifier_policy_digest.to_vec(),
            proof_cache_digest: request.proof_cache_digest.to_vec(),
            incident_id: request.incident_id.to_vec(),
            incident_evidence_digest: request.incident_evidence_digest.to_vec(),
            export_ciphertext_digest: request.export_ciphertext_digest.to_vec(),
            restore_authorization_digest: request.restore_authorization_digest.to_vec(),
            sync_state_digest: request.sync_state_digest.to_vec(),
            audit_log_checkpoint_digest: request.audit_log_checkpoint_digest.to_vec(),
            export_sequence: request.export_sequence,
            previous_export_sequence: request.previous_export_sequence,
            policy_epoch: request.policy_epoch,
            proof_cache_log_index: request.proof_cache_log_index,
            latest_checked_log_index: request.latest_checked_log_index,
            created_at_s: request.created_at_s,
            expires_at_s: request.expires_at_s,
            restored_at_s: request.restored_at_s,
            device_count: request.device_count,
            device_quorum_threshold: request.device_quorum_threshold,
            approving_device_count: request.approving_device_count,
            recovery_share_count: request.recovery_share_count,
            recovery_share_threshold: request.recovery_share_threshold,
            can_export_state: accepted.decision().can_export_state,
            can_restore_state: accepted.decision().can_restore_state,
            can_sync_cross_device: accepted.decision().can_sync_cross_device,
            plaintext_bytes_exposed: accepted.decision().plaintext_bytes_exposed,
        };
        self.records_by_digest
            .insert(record.export_manifest_digest.clone(), record);
        Ok(())
    }

    fn read_sealed_audit_recovery_export_by_digest(
        &self,
        export_manifest_digest: &[u8],
    ) -> Result<Option<SealedAuditRecoveryExportRecord>, Self::Error> {
        Ok(self.get_by_digest(export_manifest_digest).cloned())
    }

    fn read_latest_sealed_audit_recovery_export(
        &self,
    ) -> Result<Option<SealedAuditRecoveryExportRecord>, Self::Error> {
        Ok(self.latest().cloned())
    }

    fn recovery_export_record_count(&self) -> Result<usize, Self::Error> {
        Ok(self.records_by_digest.len())
    }
}

const fn sealed_audit_recovery_export_accept(
    record_count: usize,
    write: SealedAuditRecoveryExportWrite<'_>,
) -> SealedAuditRecoveryExportDecision {
    SealedAuditRecoveryExportDecision {
        accepted: true,
        reason: SealedAuditRecoveryExportReason::Accepted,
        persisted_record: true,
        record_count,
        export_sequence: write.export_sequence,
        policy_epoch: write.policy_epoch,
        proof_cache_log_index: write.proof_cache_log_index,
        latest_checked_log_index: write.latest_checked_log_index,
        can_export_state: true,
        can_restore_state: true,
        can_sync_cross_device: true,
        requires_restore_quorum: false,
        requires_policy_refresh: false,
        rejects_rollback: false,
        requires_device_binding: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

const fn sealed_audit_recovery_export_reject(
    write: SealedAuditRecoveryExportWrite<'_>,
    reason: SealedAuditRecoveryExportReason,
    requires_restore_quorum: bool,
    requires_policy_refresh: bool,
    rejects_rollback: bool,
    requires_device_binding: bool,
    plaintext_bytes_exposed: bool,
) -> SealedAuditRecoveryExportDecision {
    sealed_audit_recovery_export_reject_with_count(write, reason, 0)
        .with_restore_quorum(requires_restore_quorum)
        .with_policy_refresh(requires_policy_refresh)
        .with_rollback(rejects_rollback)
        .with_device_binding(requires_device_binding)
        .with_plaintext_exposure(plaintext_bytes_exposed)
}

const fn sealed_audit_recovery_export_reject_with_count(
    write: SealedAuditRecoveryExportWrite<'_>,
    reason: SealedAuditRecoveryExportReason,
    record_count: usize,
) -> SealedAuditRecoveryExportDecision {
    SealedAuditRecoveryExportDecision {
        accepted: false,
        reason,
        persisted_record: false,
        record_count,
        export_sequence: write.export_sequence,
        policy_epoch: write.policy_epoch,
        proof_cache_log_index: write.proof_cache_log_index,
        latest_checked_log_index: write.latest_checked_log_index,
        can_export_state: false,
        can_restore_state: false,
        can_sync_cross_device: false,
        requires_restore_quorum: false,
        requires_policy_refresh: false,
        rejects_rollback: false,
        requires_device_binding: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

impl SealedAuditRecoveryExportDecision {
    const fn with_restore_quorum(mut self, requires_restore_quorum: bool) -> Self {
        self.requires_restore_quorum = requires_restore_quorum;
        self
    }

    const fn with_policy_refresh(mut self, requires_policy_refresh: bool) -> Self {
        self.requires_policy_refresh = requires_policy_refresh;
        self
    }

    const fn with_rollback(mut self, rejects_rollback: bool) -> Self {
        self.rejects_rollback = rejects_rollback;
        self
    }

    const fn with_device_binding(mut self, requires_device_binding: bool) -> Self {
        self.requires_device_binding = requires_device_binding;
        self
    }

    const fn with_plaintext_exposure(mut self, plaintext_bytes_exposed: bool) -> Self {
        self.plaintext_bytes_exposed = plaintext_bytes_exposed;
        self
    }
}

