#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditDatabaseAdapterDecision {
    pub accepted: bool,
    pub reason: SealedAuditDatabaseAdapterReason,
    pub can_open_database: bool,
    pub can_persist_sealed_audit: bool,
    pub can_run_migration: bool,
    pub requires_database_encryption: bool,
    pub requires_append_only_guard: bool,
    pub requires_migration_drill: bool,
    pub keeps_digest_only: bool,
    pub plaintext_bytes_exposed: bool,
    pub latest_export_sequence: i64,
    pub policy_epoch: i64,
    pub proof_cache_log_index: i64,
    pub latest_checked_log_index: i64,
}

impl<'a> SealedAuditDatabaseAdapterInput<'a> {
    pub fn evaluate(self) -> SealedAuditDatabaseAdapterDecision {
        evaluate_sealed_audit_database_adapter(self)
    }
}

pub fn evaluate_sealed_audit_database_adapter(
    input: SealedAuditDatabaseAdapterInput<'_>,
) -> SealedAuditDatabaseAdapterDecision {
    if !input.recovery_export_decision.accepted
        || !input.recovery_export_decision.can_export_state
        || !input.recovery_export_decision.can_restore_state
        || !input.recovery_export_decision.can_sync_cross_device
        || !input.recovery_export_decision.keeps_digest_only
        || input.recovery_export_decision.plaintext_bytes_exposed
    {
        return sealed_audit_database_adapter_reject(
            input,
            SealedAuditDatabaseAdapterReason::RecoveryExportRejected,
            false,
            false,
            false,
            input.recovery_export_decision.plaintext_bytes_exposed,
        );
    }

    if input.adapter_format_version != 1
        || input.database_profile_digest.len() != 32
        || input.schema_digest.len() != 32
        || input.event_table_digest.len() != 32
        || input.proof_cache_table_digest.len() != 32
        || input.verifier_policy_table_digest.len() != 32
        || input.incident_evidence_table_digest.len() != 32
        || input.recovery_export_table_digest.len() != 32
        || input.checkpoint_table_digest.len() != 32
        || input.migration_plan_digest.len() != 32
        || input.crash_recovery_plan_digest.len() != 32
        || input.latest_export_sequence != input.recovery_export_decision.export_sequence
        || input.policy_epoch != input.recovery_export_decision.policy_epoch
        || input.proof_cache_log_index != input.recovery_export_decision.proof_cache_log_index
        || input.latest_checked_log_index != input.recovery_export_decision.latest_checked_log_index
        || input.latest_checked_log_index < input.proof_cache_log_index
        || input.plaintext_header_bytes < 0
        || input.plaintext_selector_count < 0
        || input.plaintext_metadata_fields < 0
    {
        return sealed_audit_database_adapter_reject(
            input,
            SealedAuditDatabaseAdapterReason::BadRecordShape,
            false,
            false,
            false,
            false,
        );
    }

    if !input.database_selection_decision.accepted
        || !input.database_selection_decision.can_open_database
        || !input.database_selection_decision.can_ship_release
        || !input.database_selection_decision.forbids_plaintext_storage
        || !input.all_tables_encrypted
        || !input.wal_encrypted
        || !input.temp_store_memory_only
        || !input.page_authentication_enabled
        || !input.platform_key_wrapping_enabled
        || !input.key_rotation_supported
        || !input.cipher_integrity_check_passed
    {
        return sealed_audit_database_adapter_reject(
            input,
            SealedAuditDatabaseAdapterReason::DatabaseEncryptionRequired,
            true,
            false,
            false,
            false,
        );
    }

    if !input.append_only_event_table
        || !input.append_only_proof_cache_table
        || !input.append_only_policy_table
        || !input.append_only_incident_table
        || !input.append_only_recovery_export_table
        || !input.monotonic_sequence_constraints
        || !input.duplicate_digest_constraints
        || !input.transactional_batch_writes
        || !input.wal_checkpoint_policy_verified
    {
        return sealed_audit_database_adapter_reject(
            input,
            SealedAuditDatabaseAdapterReason::AppendOnlyGuardRequired,
            false,
            true,
            false,
            false,
        );
    }

    if !input.deterministic_migration_tested || !input.crash_recovery_drill_passed {
        return sealed_audit_database_adapter_reject(
            input,
            SealedAuditDatabaseAdapterReason::MigrationDrillRequired,
            false,
            false,
            true,
            false,
        );
    }

    if input.plaintext_header_bytes != 0
        || input.plaintext_selector_count != 0
        || input.plaintext_metadata_fields != 0
        || !input.plaintext_free_schema
        || !input.ui_status_digest_only
    {
        return sealed_audit_database_adapter_reject(
            input,
            SealedAuditDatabaseAdapterReason::PlaintextMetadataForbidden,
            false,
            false,
            false,
            true,
        );
    }

    SealedAuditDatabaseAdapterDecision {
        accepted: true,
        reason: SealedAuditDatabaseAdapterReason::Accepted,
        can_open_database: true,
        can_persist_sealed_audit: true,
        can_run_migration: true,
        requires_database_encryption: false,
        requires_append_only_guard: false,
        requires_migration_drill: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
        latest_export_sequence: input.latest_export_sequence,
        policy_epoch: input.policy_epoch,
        proof_cache_log_index: input.proof_cache_log_index,
        latest_checked_log_index: input.latest_checked_log_index,
    }
}

const fn sealed_audit_database_adapter_reject(
    input: SealedAuditDatabaseAdapterInput<'_>,
    reason: SealedAuditDatabaseAdapterReason,
    requires_database_encryption: bool,
    requires_append_only_guard: bool,
    requires_migration_drill: bool,
    plaintext_bytes_exposed: bool,
) -> SealedAuditDatabaseAdapterDecision {
    SealedAuditDatabaseAdapterDecision {
        accepted: false,
        reason,
        can_open_database: false,
        can_persist_sealed_audit: false,
        can_run_migration: false,
        requires_database_encryption,
        requires_append_only_guard,
        requires_migration_drill,
        keeps_digest_only: true,
        plaintext_bytes_exposed,
        latest_export_sequence: input.latest_export_sequence,
        policy_epoch: input.policy_epoch,
        proof_cache_log_index: input.proof_cache_log_index,
        latest_checked_log_index: input.latest_checked_log_index,
    }
}

