#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SealedAuditPrivateReportTransportDecision {
    pub accepted: bool,
    pub reason: SealedAuditPrivateReportTransportReason,
    pub can_submit_private_report: bool,
    pub can_retry_safely: bool,
    pub requires_private_transport: bool,
    pub requires_replay_guard: bool,
    pub requires_rate_limit_token: bool,
    pub keeps_digest_only: bool,
    pub plaintext_bytes_exposed: bool,
    pub policy_epoch: i64,
    pub proof_cache_log_index: i64,
    pub latest_checked_log_index: i64,
}

impl<'a> SealedAuditPrivateReportTransportInput<'a> {
    pub fn evaluate(self) -> SealedAuditPrivateReportTransportDecision {
        evaluate_sealed_audit_private_report_transport(self)
    }
}

pub fn evaluate_sealed_audit_private_report_transport(
    input: SealedAuditPrivateReportTransportInput<'_>,
) -> SealedAuditPrivateReportTransportDecision {
    if !input.database_adapter_decision.accepted
        || !input.database_adapter_decision.can_open_database
        || !input.database_adapter_decision.can_persist_sealed_audit
        || !input.database_adapter_decision.keeps_digest_only
        || input.database_adapter_decision.plaintext_bytes_exposed
    {
        return sealed_audit_private_report_transport_reject(
            input,
            SealedAuditPrivateReportTransportReason::DatabaseAdapterRejected,
            false,
            false,
            false,
            input.database_adapter_decision.plaintext_bytes_exposed,
        );
    }

    if input.report_format_version != 1
        || input.report_transport_config_digest.len() != 32
        || input.ohttp_gateway_key_digest.len() != 32
        || input.ohttp_relay_policy_digest.len() != 32
        || input.privacy_pass_issuer_key_digest.len() != 32
        || input.report_outbox_digest.len() != 32
        || input.replay_window_digest.len() != 32
        || input.rate_limit_bucket_digest.len() != 32
        || input.retry_backoff_digest.len() != 32
        || input.incident_report_schema_digest.len() != 32
        || input.audit_checkpoint_digest.len() != 32
        || input.policy_epoch != input.database_adapter_decision.policy_epoch
        || input.proof_cache_log_index != input.database_adapter_decision.proof_cache_log_index
        || input.latest_checked_log_index
            != input.database_adapter_decision.latest_checked_log_index
        || input.latest_checked_log_index < input.proof_cache_log_index
        || input.report_window_s <= 0
        || input.max_reports_per_window <= 0
        || input.plaintext_selector_count < 0
        || input.plaintext_metadata_fields < 0
    {
        return sealed_audit_private_report_transport_reject(
            input,
            SealedAuditPrivateReportTransportReason::BadRecordShape,
            false,
            false,
            false,
            false,
        );
    }

    if !input.ohttp_relay_configured
        || !input.ohttp_gateway_key_pinned
        || !input.ohttp_target_state_free
        || !input.hpke_request_encryption
        || !input.gateway_response_authenticated
        || !input.constant_size_padding_enabled
        || !input.no_cookie_or_auth_state
        || !input.private_monitor_route_used
    {
        return sealed_audit_private_report_transport_reject(
            input,
            SealedAuditPrivateReportTransportReason::PrivateReportTransportRequired,
            true,
            false,
            false,
            false,
        );
    }

    if !input.privacy_pass_tokens_required
        || !input.privacy_pass_issuer_key_pinned
        || !input.anonymous_rate_limit_enforced
    {
        return sealed_audit_private_report_transport_reject(
            input,
            SealedAuditPrivateReportTransportReason::PrivateReportTransportRequired,
            true,
            false,
            true,
            false,
        );
    }

    if !input.retry_backoff_enabled
        || !input.replay_guard_enabled
        || !input.duplicate_report_rejected
    {
        return sealed_audit_private_report_transport_reject(
            input,
            SealedAuditPrivateReportTransportReason::ReplayGuardRequired,
            false,
            true,
            false,
            false,
        );
    }

    if input.plaintext_selector_count != 0
        || input.plaintext_metadata_fields != 0
        || !input.report_payload_encrypted
        || !input.report_payload_digest_only
        || !input.selector_blinding_enabled
        || !input.report_outbox_encrypted
        || !input.ui_status_digest_only
    {
        return sealed_audit_private_report_transport_reject(
            input,
            SealedAuditPrivateReportTransportReason::PlaintextMetadataForbidden,
            false,
            false,
            false,
            true,
        );
    }

    SealedAuditPrivateReportTransportDecision {
        accepted: true,
        reason: SealedAuditPrivateReportTransportReason::Accepted,
        can_submit_private_report: true,
        can_retry_safely: true,
        requires_private_transport: false,
        requires_replay_guard: false,
        requires_rate_limit_token: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
        policy_epoch: input.policy_epoch,
        proof_cache_log_index: input.proof_cache_log_index,
        latest_checked_log_index: input.latest_checked_log_index,
    }
}

const fn sealed_audit_private_report_transport_reject(
    input: SealedAuditPrivateReportTransportInput<'_>,
    reason: SealedAuditPrivateReportTransportReason,
    requires_private_transport: bool,
    requires_replay_guard: bool,
    requires_rate_limit_token: bool,
    plaintext_bytes_exposed: bool,
) -> SealedAuditPrivateReportTransportDecision {
    SealedAuditPrivateReportTransportDecision {
        accepted: false,
        reason,
        can_submit_private_report: false,
        can_retry_safely: false,
        requires_private_transport,
        requires_replay_guard,
        requires_rate_limit_token,
        keeps_digest_only: true,
        plaintext_bytes_exposed,
        policy_epoch: input.policy_epoch,
        proof_cache_log_index: input.proof_cache_log_index,
        latest_checked_log_index: input.latest_checked_log_index,
    }
}

