pub struct AcceptedSealedAuditPrivateReportGatewayEvidenceWrite<'a> {
    write: SealedAuditPrivateReportGatewayEvidenceWrite<'a>,
    decision: SealedAuditPrivateReportGatewayEvidenceDecision,
}

impl<'a> AcceptedSealedAuditPrivateReportGatewayEvidenceWrite<'a> {
    pub const fn write(&self) -> SealedAuditPrivateReportGatewayEvidenceWrite<'a> {
        self.write
    }

    pub const fn decision(&self) -> &SealedAuditPrivateReportGatewayEvidenceDecision {
        &self.decision
    }
}

pub trait SealedAuditPrivateReportGatewayEvidenceStore {
    type Error;

    fn put_accepted_sealed_audit_private_report_gateway_evidence(
        &mut self,
        write: AcceptedSealedAuditPrivateReportGatewayEvidenceWrite<'_>,
    ) -> Result<(), Self::Error>;

    fn read_sealed_audit_private_report_gateway_evidence_by_id(
        &self,
        evidence_id: &[u8],
    ) -> Result<Option<SealedAuditPrivateReportGatewayEvidenceRecord>, Self::Error>;

    fn read_sealed_audit_private_report_gateway_evidence_by_report_id(
        &self,
        report_id: &[u8],
    ) -> Result<Option<SealedAuditPrivateReportGatewayEvidenceRecord>, Self::Error>;

    fn read_latest_sealed_audit_private_report_gateway_evidence(
        &self,
    ) -> Result<Option<SealedAuditPrivateReportGatewayEvidenceRecord>, Self::Error>;

    fn private_report_gateway_evidence_record_count(&self) -> Result<usize, Self::Error>;
}

pub fn evaluate_sealed_audit_private_report_gateway_evidence(
    write: SealedAuditPrivateReportGatewayEvidenceWrite<'_>,
) -> SealedAuditPrivateReportGatewayEvidenceDecision {
    if !write.reconciliation_decision.accepted
        || !write.reconciliation_decision.persisted_record
        || !write.reconciliation_decision.can_reconcile_delivery
        || !write.reconciliation_decision.can_show_retry_status
        || !write.reconciliation_decision.rejects_false_delivery
        || !write.reconciliation_decision.keeps_digest_only
        || write.reconciliation_decision.plaintext_bytes_exposed
    {
        return sealed_audit_private_report_gateway_evidence_reject(
            write,
            SealedAuditPrivateReportGatewayEvidenceReason::PrivateReportReconciliationRequired,
            true,
            false,
            false,
            false,
            write.reconciliation_decision.plaintext_bytes_exposed,
        );
    }

    if write.evidence_format_version != 1
        || write.evidence_id.len() != 32
        || !(write.previous_evidence_id.is_empty() || write.previous_evidence_id.len() == 32)
        || write.reconciliation_id.len() != 32
        || write.report_id.len() != 32
        || write.receipt_id.len() != 32
        || write.unavailable_evidence_digest.len() != 32
        || write.relay_observation_digest.len() != 32
        || write.gateway_error_digest.len() != 32
        || write.target_absence_digest.len() != 32
        || write.retry_exhaustion_digest.len() != 32
        || write.rate_limit_state_digest.len() != 32
        || write.gateway_key_state_digest.len() != 32
        || write.accountability_route_digest.len() != 32
        || write.blinded_failure_bucket_digest.len() != 32
        || write.monitor_submission_digest.len() != 32
        || write.audit_checkpoint_digest.len() != 32
        || write.evidence_sequence < 1
        || write.previous_evidence_sequence < 0
        || write.reconciliation_sequence != write.reconciliation_decision.reconciliation_sequence
        || write.report_sequence != write.reconciliation_decision.report_sequence
        || write.receipt_sequence != write.reconciliation_decision.receipt_sequence
        || write.policy_epoch != write.reconciliation_decision.policy_epoch
        || write.proof_cache_log_index != write.reconciliation_decision.proof_cache_log_index
        || write.latest_checked_log_index != write.reconciliation_decision.latest_checked_log_index
        || write.latest_checked_log_index < write.proof_cache_log_index
        || write.created_at_s <= 0
        || write.expires_at_s <= write.created_at_s
        || write.retry_attempt_count < 0
        || write.max_retry_attempts < 1
        || write.retry_attempt_count > write.max_retry_attempts
        || write.gateway_status_code <= 0
        || write.plaintext_selector_count < 0
        || write.plaintext_metadata_fields < 0
        || !write.evidence_record_encrypted
        || !write.append_only_guard
    {
        return sealed_audit_private_report_gateway_evidence_reject(
            write,
            SealedAuditPrivateReportGatewayEvidenceReason::BadRecordShape,
            false,
            false,
            false,
            false,
            false,
        );
    }

    if write.evidence_sequence <= write.previous_evidence_sequence
        || (write.previous_evidence_sequence > 0 && write.previous_evidence_id.is_empty())
        || !write.reconciliation_bound
        || !write.unavailable_evidence_gateway_authenticated
        || !write.relay_observation_signed
        || !write.target_absence_proof_bound
        || !write.gateway_timeout_or_5xx_classified
        || !write.no_client_asserted_unavailability
        || !sealed_audit_private_report_gateway_unavailable_status(write.gateway_status_code)
    {
        return sealed_audit_private_report_gateway_evidence_reject(
            write,
            SealedAuditPrivateReportGatewayEvidenceReason::UnavailableEvidenceRequired,
            false,
            true,
            false,
            false,
            false,
        );
    }

    if write.retry_attempt_count < write.max_retry_attempts
        || !write.retry_exhaustion_bound
        || !write.rate_limit_continuity_bound
    {
        return sealed_audit_private_report_gateway_evidence_reject(
            write,
            SealedAuditPrivateReportGatewayEvidenceReason::RetryExhaustionRequired,
            false,
            false,
            false,
            true,
            false,
        );
    }

    if !write.gateway_key_state_bound
        || !write.accountability_route_bound
        || !write.operator_escalation_bound
        || !write.blinded_failure_bucket_only
        || !write.monitor_route_private
        || !write.incident_visible_only_after_policy
    {
        return sealed_audit_private_report_gateway_evidence_reject(
            write,
            SealedAuditPrivateReportGatewayEvidenceReason::AccountabilityRouteRequired,
            false,
            false,
            true,
            false,
            false,
        );
    }

    if write.plaintext_selector_count != 0
        || write.plaintext_metadata_fields != 0
        || !write.ui_status_digest_only
    {
        return sealed_audit_private_report_gateway_evidence_reject(
            write,
            SealedAuditPrivateReportGatewayEvidenceReason::PlaintextMetadataForbidden,
            false,
            false,
            false,
            false,
            true,
        );
    }

    sealed_audit_private_report_gateway_evidence_accept(0, write)
}

pub fn put_sealed_audit_private_report_gateway_evidence_record<S>(
    store: &mut S,
    write: SealedAuditPrivateReportGatewayEvidenceWrite<'_>,
) -> Result<SealedAuditPrivateReportGatewayEvidenceDecision, S::Error>
where
    S: SealedAuditPrivateReportGatewayEvidenceStore + ?Sized,
{
    let record_count = store.private_report_gateway_evidence_record_count()?;
    let decision = evaluate_sealed_audit_private_report_gateway_evidence(write);
    if !decision.accepted {
        return Ok(SealedAuditPrivateReportGatewayEvidenceDecision {
            record_count,
            ..decision
        });
    }

    if store
        .read_sealed_audit_private_report_gateway_evidence_by_id(write.evidence_id)?
        .is_some()
        || store
            .read_sealed_audit_private_report_gateway_evidence_by_report_id(write.report_id)?
            .is_some()
    {
        return Ok(
            sealed_audit_private_report_gateway_evidence_reject_with_count(
                write,
                SealedAuditPrivateReportGatewayEvidenceReason::UnavailableEvidenceRequired,
                record_count,
            )
            .with_unavailable_evidence(true),
        );
    }

    if let Some(latest) = store.read_latest_sealed_audit_private_report_gateway_evidence()? {
        if write.evidence_sequence <= latest.evidence_sequence {
            return Ok(
                sealed_audit_private_report_gateway_evidence_reject_with_count(
                    write,
                    SealedAuditPrivateReportGatewayEvidenceReason::UnavailableEvidenceRequired,
                    record_count,
                )
                .with_unavailable_evidence(true),
            );
        }
    }

    store.put_accepted_sealed_audit_private_report_gateway_evidence(
        AcceptedSealedAuditPrivateReportGatewayEvidenceWrite { write, decision },
    )?;
    let record_count = store.private_report_gateway_evidence_record_count()?;
    Ok(SealedAuditPrivateReportGatewayEvidenceDecision {
        record_count,
        ..decision
    })
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct PrototypeSealedAuditPrivateReportGatewayEvidenceStore {
    records_by_id: BTreeMap<Vec<u8>, SealedAuditPrivateReportGatewayEvidenceRecord>,
    evidence_ids_by_report_id: BTreeMap<Vec<u8>, Vec<u8>>,
}

impl PrototypeSealedAuditPrivateReportGatewayEvidenceStore {
    pub fn put(
        &mut self,
        write: SealedAuditPrivateReportGatewayEvidenceWrite<'_>,
    ) -> SealedAuditPrivateReportGatewayEvidenceDecision {
        match put_sealed_audit_private_report_gateway_evidence_record(self, write) {
            Ok(decision) => decision,
            Err(error) => match error {},
        }
    }

    pub fn get_by_id(
        &self,
        evidence_id: &[u8],
    ) -> Option<&SealedAuditPrivateReportGatewayEvidenceRecord> {
        self.records_by_id.get(evidence_id)
    }

    pub fn get_by_report_id(
        &self,
        report_id: &[u8],
    ) -> Option<&SealedAuditPrivateReportGatewayEvidenceRecord> {
        self.evidence_ids_by_report_id
            .get(report_id)
            .and_then(|evidence_id| self.records_by_id.get(evidence_id))
    }

    pub fn latest(&self) -> Option<&SealedAuditPrivateReportGatewayEvidenceRecord> {
        self.records_by_id
            .values()
            .max_by_key(|record| record.evidence_sequence)
    }

    pub fn len(&self) -> usize {
        self.records_by_id.len()
    }

    pub fn is_empty(&self) -> bool {
        self.records_by_id.is_empty()
    }
}

impl SealedAuditPrivateReportGatewayEvidenceStore
    for PrototypeSealedAuditPrivateReportGatewayEvidenceStore
{
    type Error = Infallible;

    fn put_accepted_sealed_audit_private_report_gateway_evidence(
        &mut self,
        accepted: AcceptedSealedAuditPrivateReportGatewayEvidenceWrite<'_>,
    ) -> Result<(), Self::Error> {
        let request = accepted.write();
        let record = SealedAuditPrivateReportGatewayEvidenceRecord {
            evidence_id: request.evidence_id.to_vec(),
            previous_evidence_id: request.previous_evidence_id.to_vec(),
            reconciliation_id: request.reconciliation_id.to_vec(),
            report_id: request.report_id.to_vec(),
            receipt_id: request.receipt_id.to_vec(),
            unavailable_evidence_digest: request.unavailable_evidence_digest.to_vec(),
            relay_observation_digest: request.relay_observation_digest.to_vec(),
            gateway_error_digest: request.gateway_error_digest.to_vec(),
            target_absence_digest: request.target_absence_digest.to_vec(),
            retry_exhaustion_digest: request.retry_exhaustion_digest.to_vec(),
            rate_limit_state_digest: request.rate_limit_state_digest.to_vec(),
            gateway_key_state_digest: request.gateway_key_state_digest.to_vec(),
            accountability_route_digest: request.accountability_route_digest.to_vec(),
            blinded_failure_bucket_digest: request.blinded_failure_bucket_digest.to_vec(),
            monitor_submission_digest: request.monitor_submission_digest.to_vec(),
            audit_checkpoint_digest: request.audit_checkpoint_digest.to_vec(),
            evidence_sequence: request.evidence_sequence,
            previous_evidence_sequence: request.previous_evidence_sequence,
            reconciliation_sequence: request.reconciliation_sequence,
            report_sequence: request.report_sequence,
            receipt_sequence: request.receipt_sequence,
            policy_epoch: request.policy_epoch,
            proof_cache_log_index: request.proof_cache_log_index,
            latest_checked_log_index: request.latest_checked_log_index,
            created_at_s: request.created_at_s,
            expires_at_s: request.expires_at_s,
            retry_attempt_count: request.retry_attempt_count,
            max_retry_attempts: request.max_retry_attempts,
            gateway_status_code: request.gateway_status_code,
            can_raise_gateway_incident: accepted.decision().can_raise_gateway_incident,
            can_notify_operator: accepted.decision().can_notify_operator,
            plaintext_bytes_exposed: accepted.decision().plaintext_bytes_exposed,
        };
        self.evidence_ids_by_report_id
            .insert(record.report_id.clone(), record.evidence_id.clone());
        self.records_by_id
            .insert(record.evidence_id.clone(), record);
        Ok(())
    }

    fn read_sealed_audit_private_report_gateway_evidence_by_id(
        &self,
        evidence_id: &[u8],
    ) -> Result<Option<SealedAuditPrivateReportGatewayEvidenceRecord>, Self::Error> {
        Ok(self.get_by_id(evidence_id).cloned())
    }

    fn read_sealed_audit_private_report_gateway_evidence_by_report_id(
        &self,
        report_id: &[u8],
    ) -> Result<Option<SealedAuditPrivateReportGatewayEvidenceRecord>, Self::Error> {
        Ok(self.get_by_report_id(report_id).cloned())
    }

    fn read_latest_sealed_audit_private_report_gateway_evidence(
        &self,
    ) -> Result<Option<SealedAuditPrivateReportGatewayEvidenceRecord>, Self::Error> {
        Ok(self.latest().cloned())
    }

    fn private_report_gateway_evidence_record_count(&self) -> Result<usize, Self::Error> {
        Ok(self.records_by_id.len())
    }
}

const fn sealed_audit_private_report_gateway_evidence_accept(
    record_count: usize,
    write: SealedAuditPrivateReportGatewayEvidenceWrite<'_>,
) -> SealedAuditPrivateReportGatewayEvidenceDecision {
    SealedAuditPrivateReportGatewayEvidenceDecision {
        accepted: true,
        reason: SealedAuditPrivateReportGatewayEvidenceReason::Accepted,
        persisted_record: true,
        record_count,
        evidence_sequence: write.evidence_sequence,
        reconciliation_sequence: write.reconciliation_sequence,
        report_sequence: write.report_sequence,
        receipt_sequence: write.receipt_sequence,
        policy_epoch: write.policy_epoch,
        proof_cache_log_index: write.proof_cache_log_index,
        latest_checked_log_index: write.latest_checked_log_index,
        can_raise_gateway_incident: true,
        can_notify_operator: true,
        can_show_unavailable_status: true,
        requires_private_report_reconciliation: false,
        requires_unavailable_evidence: false,
        requires_accountability_route: false,
        requires_retry_exhaustion: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

const fn sealed_audit_private_report_gateway_evidence_reject(
    write: SealedAuditPrivateReportGatewayEvidenceWrite<'_>,
    reason: SealedAuditPrivateReportGatewayEvidenceReason,
    requires_private_report_reconciliation: bool,
    requires_unavailable_evidence: bool,
    requires_accountability_route: bool,
    requires_retry_exhaustion: bool,
    plaintext_bytes_exposed: bool,
) -> SealedAuditPrivateReportGatewayEvidenceDecision {
    sealed_audit_private_report_gateway_evidence_reject_with_count(write, reason, 0)
        .with_private_report_reconciliation(requires_private_report_reconciliation)
        .with_unavailable_evidence(requires_unavailable_evidence)
        .with_accountability_route(requires_accountability_route)
        .with_retry_exhaustion(requires_retry_exhaustion)
        .with_plaintext_exposure(plaintext_bytes_exposed)
}

const fn sealed_audit_private_report_gateway_evidence_reject_with_count(
    write: SealedAuditPrivateReportGatewayEvidenceWrite<'_>,
    reason: SealedAuditPrivateReportGatewayEvidenceReason,
    record_count: usize,
) -> SealedAuditPrivateReportGatewayEvidenceDecision {
    SealedAuditPrivateReportGatewayEvidenceDecision {
        accepted: false,
        reason,
        persisted_record: false,
        record_count,
        evidence_sequence: write.evidence_sequence,
        reconciliation_sequence: write.reconciliation_sequence,
        report_sequence: write.report_sequence,
        receipt_sequence: write.receipt_sequence,
        policy_epoch: write.policy_epoch,
        proof_cache_log_index: write.proof_cache_log_index,
        latest_checked_log_index: write.latest_checked_log_index,
        can_raise_gateway_incident: false,
        can_notify_operator: false,
        can_show_unavailable_status: false,
        requires_private_report_reconciliation: false,
        requires_unavailable_evidence: false,
        requires_accountability_route: false,
        requires_retry_exhaustion: false,
        keeps_digest_only: true,
        plaintext_bytes_exposed: false,
    }
}

impl SealedAuditPrivateReportGatewayEvidenceDecision {
    const fn with_private_report_reconciliation(
        mut self,
        requires_private_report_reconciliation: bool,
    ) -> Self {
        self.requires_private_report_reconciliation = requires_private_report_reconciliation;
        self
    }

    const fn with_unavailable_evidence(mut self, requires_unavailable_evidence: bool) -> Self {
        self.requires_unavailable_evidence = requires_unavailable_evidence;
        self
    }

    const fn with_accountability_route(mut self, requires_accountability_route: bool) -> Self {
        self.requires_accountability_route = requires_accountability_route;
        self
    }

    const fn with_retry_exhaustion(mut self, requires_retry_exhaustion: bool) -> Self {
        self.requires_retry_exhaustion = requires_retry_exhaustion;
        self
    }

    const fn with_plaintext_exposure(mut self, plaintext_bytes_exposed: bool) -> Self {
        self.plaintext_bytes_exposed = plaintext_bytes_exposed;
        self
    }
}

const fn sealed_audit_private_report_gateway_unavailable_status(status_code: i32) -> bool {
    matches!(status_code, 408 | 425 | 429 | 500..=504)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InboundSyncSourceState {
    Ready,
    Offline,
    AuthRejected,
    BackoffRequired,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AuthenticatedRelayTransportState {
    Ready,
    Offline,
    BackoffRequired,
}

impl AuthenticatedRelayTransportState {
    pub const fn code(self) -> i32 {
        match self {
            Self::Ready => 1,
            Self::Offline => 2,
            Self::BackoffRequired => 3,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::Ready => "ready",
            Self::Offline => "offline",
            Self::BackoffRequired => "backoff_required",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum AuthenticatedRelaySourceReason {
    DeliveryReady,
    Idle,
    TransportOffline,
    BackoffRequired,
    BadSessionTicketLength,
    BadDeviceCredentialLength,
    BadServerAuthTagLength,
    ServerAuthenticationRejected,
    RouteKeyAuthenticationRejected,
    ReplayWindowRejected,
    PlaintextIdentityForbidden,
    PlaintextNotificationPreviewForbidden,
    BadPollBatchLimit,
    BadRouteIdLength,
}

impl AuthenticatedRelaySourceReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::DeliveryReady => 0,
            Self::Idle => 1,
            Self::TransportOffline => 2,
            Self::BackoffRequired => 3,
            Self::BadSessionTicketLength => 4,
            Self::BadDeviceCredentialLength => 5,
            Self::BadServerAuthTagLength => 6,
            Self::ServerAuthenticationRejected => 7,
            Self::RouteKeyAuthenticationRejected => 8,
            Self::ReplayWindowRejected => 9,
            Self::PlaintextIdentityForbidden => 10,
            Self::PlaintextNotificationPreviewForbidden => 11,
            Self::BadPollBatchLimit => 12,
            Self::BadRouteIdLength => 13,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::DeliveryReady => "DELIVERY_READY",
            Self::Idle => "IDLE",
            Self::TransportOffline => "TRANSPORT_OFFLINE",
            Self::BackoffRequired => "BACKOFF_REQUIRED",
            Self::BadSessionTicketLength => "BAD_SESSION_TICKET_LENGTH",
            Self::BadDeviceCredentialLength => "BAD_DEVICE_CREDENTIAL_LENGTH",
            Self::BadServerAuthTagLength => "BAD_SERVER_AUTH_TAG_LENGTH",
            Self::ServerAuthenticationRejected => "SERVER_AUTHENTICATION_REJECTED",
            Self::RouteKeyAuthenticationRejected => "ROUTE_KEY_AUTHENTICATION_REJECTED",
            Self::ReplayWindowRejected => "REPLAY_WINDOW_REJECTED",
            Self::PlaintextIdentityForbidden => "PLAINTEXT_IDENTITY_FORBIDDEN",
            Self::PlaintextNotificationPreviewForbidden => {
                "PLAINTEXT_NOTIFICATION_PREVIEW_FORBIDDEN"
            }
            Self::BadPollBatchLimit => "BAD_POLL_BATCH_LIMIT",
            Self::BadRouteIdLength => "BAD_ROUTE_ID_LENGTH",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AuthenticatedRelaySourceInput {
    pub transport: AuthenticatedRelayTransportState,
    pub session_ticket_len: i32,
    pub device_credential_len: i32,
    pub server_auth_tag_len: i32,
    pub server_authenticated: bool,
    pub route_key_authenticated: bool,
    pub replay_window_valid: bool,
    pub pending_delivery: bool,
    pub route_id_len: i32,
    pub poll_batch_limit: i32,
    pub plaintext_notification_preview_len: i32,
    pub plaintext_identity_fields: i32,
}

impl AuthenticatedRelaySourceInput {
    pub fn evaluate(self) -> AuthenticatedRelaySourceDecision {
        evaluate_authenticated_relay_source(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AuthenticatedRelaySourceDecision {
    pub accepted: bool,
    pub source_state: InboundSyncSourceState,
    pub pending_delivery: bool,
    pub route_id_len: i32,
    pub poll_batch_limit: i32,
    pub plaintext_notification_preview_len: i32,
    pub can_poll_relay: bool,
    pub can_run_receive_session: bool,
    pub requires_network_retry: bool,
    pub requires_user_action: bool,
    pub plaintext_bytes_exposed: bool,
    pub reason: AuthenticatedRelaySourceReason,
}

impl AuthenticatedRelaySourceDecision {
    pub const fn into_inbound_sync_input(
        self,
        bootstrap: ClientBootstrapDecision,
    ) -> InboundSyncInput {
        InboundSyncInput {
            bootstrap,
            source_state: self.source_state,
            pending_delivery: self.pending_delivery,
            route_id_len: self.route_id_len,
            poll_batch_limit: self.poll_batch_limit,
            plaintext_notification_preview_len: self.plaintext_notification_preview_len,
        }
    }
}

pub fn evaluate_authenticated_relay_source(
    input: AuthenticatedRelaySourceInput,
) -> AuthenticatedRelaySourceDecision {
    if input.plaintext_notification_preview_len != 0 {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::PlaintextNotificationPreviewForbidden,
            false,
            true,
        );
    }

    if input.plaintext_identity_fields != 0 {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::PlaintextIdentityForbidden,
            false,
            true,
        );
    }

    match input.transport {
        AuthenticatedRelayTransportState::Ready => {}
        AuthenticatedRelayTransportState::Offline => {
            return authenticated_relay_source_reject(
                input,
                InboundSyncSourceState::Offline,
                AuthenticatedRelaySourceReason::TransportOffline,
                true,
                false,
            );
        }
        AuthenticatedRelayTransportState::BackoffRequired => {
            return authenticated_relay_source_reject(
                input,
                InboundSyncSourceState::BackoffRequired,
                AuthenticatedRelaySourceReason::BackoffRequired,
                true,
                false,
            );
        }
    }

    if input.session_ticket_len != 32 {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::BadSessionTicketLength,
            false,
            true,
        );
    }

    if input.device_credential_len != 32 {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::BadDeviceCredentialLength,
            false,
            true,
        );
    }

    if input.server_auth_tag_len != 32 {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::BadServerAuthTagLength,
            false,
            true,
        );
    }

    if !input.server_authenticated {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::ServerAuthenticationRejected,
            false,
            true,
        );
    }

    if !input.route_key_authenticated {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::RouteKeyAuthenticationRejected,
            false,
            true,
        );
    }

    if !input.replay_window_valid {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::AuthRejected,
            AuthenticatedRelaySourceReason::ReplayWindowRejected,
            false,
            true,
        );
    }

    if input.poll_batch_limit < 1 || input.poll_batch_limit > 100 {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::Ready,
            AuthenticatedRelaySourceReason::BadPollBatchLimit,
            false,
            false,
        );
    }

    if input.pending_delivery && input.route_id_len != 32 {
        return authenticated_relay_source_reject(
            input,
            InboundSyncSourceState::Ready,
            AuthenticatedRelaySourceReason::BadRouteIdLength,
            false,
            false,
        );
    }

    AuthenticatedRelaySourceDecision {
        accepted: true,
        source_state: InboundSyncSourceState::Ready,
        pending_delivery: input.pending_delivery,
        route_id_len: input.route_id_len,
        poll_batch_limit: input.poll_batch_limit,
        plaintext_notification_preview_len: input.plaintext_notification_preview_len,
        can_poll_relay: true,
        can_run_receive_session: input.pending_delivery,
        requires_network_retry: false,
        requires_user_action: false,
        plaintext_bytes_exposed: false,
        reason: if input.pending_delivery {
            AuthenticatedRelaySourceReason::DeliveryReady
        } else {
            AuthenticatedRelaySourceReason::Idle
        },
    }
}

const fn authenticated_relay_source_reject(
    input: AuthenticatedRelaySourceInput,
    source_state: InboundSyncSourceState,
    reason: AuthenticatedRelaySourceReason,
    requires_network_retry: bool,
    requires_user_action: bool,
) -> AuthenticatedRelaySourceDecision {
    AuthenticatedRelaySourceDecision {
        accepted: false,
        source_state,
        pending_delivery: input.pending_delivery,
        route_id_len: input.route_id_len,
        poll_batch_limit: input.poll_batch_limit,
        plaintext_notification_preview_len: input.plaintext_notification_preview_len,
        can_poll_relay: false,
        can_run_receive_session: false,
        requires_network_retry,
        requires_user_action,
        plaintext_bytes_exposed: false,
        reason,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InboundSyncReason {
    DeliveryReady,
    Idle,
    BootstrapBlocked,
    TransportOffline,
    TransportAuthRejected,
    BackoffRequired,
    BadPollBatchLimit,
    BadRouteIdLength,
    PlaintextNotificationPreviewForbidden,
}

impl InboundSyncReason {
    pub const fn code(self) -> i32 {
        match self {
            Self::DeliveryReady => 0,
            Self::Idle => 1,
            Self::BootstrapBlocked => 2,
            Self::TransportOffline => 3,
            Self::TransportAuthRejected => 4,
            Self::BackoffRequired => 5,
            Self::BadPollBatchLimit => 6,
            Self::BadRouteIdLength => 7,
            Self::PlaintextNotificationPreviewForbidden => 8,
        }
    }

    pub const fn label(self) -> &'static str {
        match self {
            Self::DeliveryReady => "DELIVERY_READY",
            Self::Idle => "IDLE",
            Self::BootstrapBlocked => "BOOTSTRAP_BLOCKED",
            Self::TransportOffline => "TRANSPORT_OFFLINE",
            Self::TransportAuthRejected => "TRANSPORT_AUTH_REJECTED",
            Self::BackoffRequired => "BACKOFF_REQUIRED",
            Self::BadPollBatchLimit => "BAD_POLL_BATCH_LIMIT",
            Self::BadRouteIdLength => "BAD_ROUTE_ID_LENGTH",
            Self::PlaintextNotificationPreviewForbidden => {
                "PLAINTEXT_NOTIFICATION_PREVIEW_FORBIDDEN"
            }
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InboundSyncInput {
    pub bootstrap: ClientBootstrapDecision,
    pub source_state: InboundSyncSourceState,
    pub pending_delivery: bool,
    pub route_id_len: i32,
    pub poll_batch_limit: i32,
    pub plaintext_notification_preview_len: i32,
}

impl InboundSyncInput {
    pub fn evaluate(self) -> InboundSyncDecision {
        evaluate_inbound_sync(self)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InboundSyncDecision {
    pub accepted: bool,
    pub can_poll_relay: bool,
    pub can_run_receive_session: bool,
    pub can_update_replay_checkpoint: bool,
    pub requires_network_retry: bool,
    pub requires_user_action: bool,
    pub plaintext_bytes_exposed: bool,
    pub reason: InboundSyncReason,
}

pub fn evaluate_inbound_sync(input: InboundSyncInput) -> InboundSyncDecision {
    if input.plaintext_notification_preview_len != 0 {
        return inbound_sync_reject(
            InboundSyncReason::PlaintextNotificationPreviewForbidden,
            false,
            true,
        );
    }

    if !input.bootstrap.can_start_sync {
        return inbound_sync_reject(
            InboundSyncReason::BootstrapBlocked,
            false,
            input.bootstrap.requires_user_action,
        );
    }

    match input.source_state {
        InboundSyncSourceState::Ready => {}
        InboundSyncSourceState::Offline => {
            return inbound_sync_reject(InboundSyncReason::TransportOffline, true, false);
        }
        InboundSyncSourceState::AuthRejected => {
            return inbound_sync_reject(InboundSyncReason::TransportAuthRejected, false, true);
        }
        InboundSyncSourceState::BackoffRequired => {
            return inbound_sync_reject(InboundSyncReason::BackoffRequired, true, false);
        }
    }

    if input.poll_batch_limit < 1 || input.poll_batch_limit > 100 {
        return inbound_sync_reject(InboundSyncReason::BadPollBatchLimit, false, false);
    }

    if input.pending_delivery && input.route_id_len != 32 {
        return inbound_sync_reject(InboundSyncReason::BadRouteIdLength, false, false);
    }

    if !input.pending_delivery {
        return InboundSyncDecision {
            accepted: true,
            can_poll_relay: true,
            can_run_receive_session: false,
            can_update_replay_checkpoint: true,
            requires_network_retry: false,
            requires_user_action: false,
            plaintext_bytes_exposed: false,
            reason: InboundSyncReason::Idle,
        };
    }

    InboundSyncDecision {
        accepted: true,
        can_poll_relay: true,
        can_run_receive_session: true,
        can_update_replay_checkpoint: true,
        requires_network_retry: false,
        requires_user_action: false,
        plaintext_bytes_exposed: false,
        reason: InboundSyncReason::DeliveryReady,
    }
}

const fn inbound_sync_reject(
    reason: InboundSyncReason,
    requires_network_retry: bool,
    requires_user_action: bool,
) -> InboundSyncDecision {
    InboundSyncDecision {
        accepted: false,
        can_poll_relay: false,
        can_run_receive_session: false,
        can_update_replay_checkpoint: false,
        requires_network_retry,
        requires_user_action,
        plaintext_bytes_exposed: false,
        reason,
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PlatformDecisionView {
    pub source: &'static str,
    pub accepted: bool,
    pub reason_code: i32,
    pub reason_label: &'static str,
    pub can_open_message_ui: bool,
    pub can_start_sync: bool,
    pub can_send: bool,
    pub can_receive: bool,
    pub can_persist_ciphertext: bool,
    pub requires_sync: bool,
    pub requires_recovery: bool,
    pub requires_client_retry: bool,
    pub requires_user_action: bool,
}

impl PlatformDecisionView {
    pub const fn from_bootstrap(decision: ClientBootstrapDecision) -> Self {
        Self {
            source: "client_bootstrap",
            accepted: decision.accepted,
            reason_code: decision.reason.code(),
            reason_label: decision.reason.label(),
            can_open_message_ui: decision.can_open_message_ui,
            can_start_sync: decision.can_start_sync,
            can_send: false,
            can_receive: false,
            can_persist_ciphertext: false,
            requires_sync: decision.requires_sync,
            requires_recovery: decision.requires_recovery,
            requires_client_retry: false,
            requires_user_action: decision.requires_user_action,
        }
    }

    pub const fn from_outbound_send(decision: OutboundSendDecision) -> Self {
        Self {
            source: "outbound_send",
            accepted: decision.accepted,
            reason_code: decision.reason.code(),
            reason_label: decision.reason.label(),
            can_open_message_ui: false,
            can_start_sync: false,
            can_send: decision.can_send,
            can_receive: false,
            can_persist_ciphertext: decision.can_persist_ciphertext,
            requires_sync: false,
            requires_recovery: false,
            requires_client_retry: false,
            requires_user_action: decision.requires_user_action,
        }
    }

    pub const fn from_client_receive(decision: ClientReceiveDecision) -> Self {
        Self {
            source: "client_receive",
            accepted: decision.accepted,
            reason_code: decision.reason.code(),
            reason_label: decision.reason.label(),
            can_open_message_ui: decision.can_expose_to_ui,
            can_start_sync: false,
            can_send: false,
            can_receive: decision.can_decrypt,
            can_persist_ciphertext: decision.can_persist_ciphertext,
            requires_sync: false,
            requires_recovery: false,
            requires_client_retry: decision.requires_client_retry,
            requires_user_action: decision.requires_user_action,
        }
    }

    pub const fn from_policy(decision: PolicyDecision) -> Self {
        let reason = decision.reason_label();
        Self {
            source: reason.source.label(),
            accepted: decision.accepted,
            reason_code: reason.code,
            reason_label: reason.label,
            can_open_message_ui: false,
            can_start_sync: false,
            can_send: false,
            can_receive: false,
            can_persist_ciphertext: false,
            requires_sync: false,
            requires_recovery: false,
            requires_client_retry: false,
            requires_user_action: false,
        }
    }
}

#[cfg(feature = "serde")]
impl serde::Serialize for PlatformDecisionView {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: serde::Serializer,
    {
        let mut state = serializer.serialize_struct("PlatformDecisionView", 13)?;
        state.serialize_field("source", self.source)?;
        state.serialize_field("accepted", &self.accepted)?;
        state.serialize_field("reason_code", &self.reason_code)?;
        state.serialize_field("reason_label", self.reason_label)?;
        state.serialize_field("can_open_message_ui", &self.can_open_message_ui)?;
        state.serialize_field("can_start_sync", &self.can_start_sync)?;
        state.serialize_field("can_send", &self.can_send)?;
        state.serialize_field("can_receive", &self.can_receive)?;
        state.serialize_field("can_persist_ciphertext", &self.can_persist_ciphertext)?;
        state.serialize_field("requires_sync", &self.requires_sync)?;
        state.serialize_field("requires_recovery", &self.requires_recovery)?;
        state.serialize_field("requires_client_retry", &self.requires_client_retry)?;
        state.serialize_field("requires_user_action", &self.requires_user_action)?;
        state.end()
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ComponentReasons {
    pub envelope_reason: i32,
    pub room_epoch_reason: i32,
    pub ai_grant_reason: i32,
    pub ai_lifecycle_reason: i32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PolicyDecision {
    pub accepted: bool,
    pub reason_code: i32,
    pub audit_class: i32,
    pub components: ComponentReasons,
}

impl PolicyDecision {
    pub const fn pipeline_reason(self) -> PipelineReason {
        PipelineReason::from_code(self.reason_code)
    }

    pub const fn pipeline_audit_class(self) -> PipelineAuditClass {
        PipelineAuditClass::from_code(self.audit_class)
    }

    pub const fn reason_label(self) -> CodeLabel {
        self.pipeline_reason().code_label()
    }

    pub const fn audit_class_label(self) -> CodeLabel {
        self.pipeline_audit_class().code_label()
    }

    pub const fn primary_source(self) -> PolicySource {
        self.pipeline_reason().primary_source()
    }

    pub const fn component_labels(self) -> ComponentCodeLabels {
        ComponentCodeLabels {
            envelope_reason: envelope_reason_code_label(self.components.envelope_reason),
            room_epoch_reason: room_epoch_reason_code_label(self.components.room_epoch_reason),
            ai_grant_reason: ai_grant_reason_code_label(self.components.ai_grant_reason),
            ai_lifecycle_reason: ai_lifecycle_reason_code_label(
                self.components.ai_lifecycle_reason,
            ),
        }
    }

    pub const fn primary_component(self) -> Option<CodeLabel> {
        match self.pipeline_reason() {
            PipelineReason::EnvelopeReject => {
                Some(envelope_reason_code_label(self.components.envelope_reason))
            }
            PipelineReason::RoomEpochReject => Some(room_epoch_reason_code_label(
                self.components.room_epoch_reason,
            )),
            PipelineReason::AiGrantReject => {
                Some(ai_grant_reason_code_label(self.components.ai_grant_reason))
            }
            PipelineReason::AiLifecycleReject
            | PipelineReason::AiPostRevokeAccessReject
            | PipelineReason::AiHighsecRotationRequired => Some(ai_lifecycle_reason_code_label(
                self.components.ai_lifecycle_reason,
            )),
            PipelineReason::AiComponentForHuman => self.first_ai_component_label(),
            _ => None,
        }
    }

    pub const fn labels(self) -> DecisionLabels {
        DecisionLabels {
            reason: self.reason_label(),
            audit_class: self.audit_class_label(),
            primary_source: self.primary_source(),
            primary_component: self.primary_component(),
            components: self.component_labels(),
        }
    }

    pub const fn view(self) -> DecisionView {
        DecisionView::from_decision(self)
    }

    const fn first_ai_component_label(self) -> Option<CodeLabel> {
        if self.components.ai_grant_reason != policy::AI_GRANT_ACCEPT {
            Some(ai_grant_reason_code_label(self.components.ai_grant_reason))
        } else if self.components.ai_lifecycle_reason != policy::AI_GRANT_LIFECYCLE_ACCEPT {
            Some(ai_lifecycle_reason_code_label(
                self.components.ai_lifecycle_reason,
            ))
        } else {
            None
        }
    }
}

pub fn evaluate_policy(input: PolicyEvaluationInput) -> PolicyDecision {
    let envelope_reason = policy::validate_envelope(input.envelope.into());
    let room_epoch_reason = policy::validate_room_epoch(input.room_epoch.into());
    let (ai_grant_reason, ai_lifecycle_reason) = evaluate_ai_components(input.actor_kind, input.ai);

    let reason_code = policy::policy_pipeline_decide_v1(policy::PolicyPipelineInput {
        version: 1,
        actor_kind: input.actor_kind.code(),
        envelope_reason,
        room_epoch_reason,
        ai_grant_reason,
        ai_lifecycle_reason,
    });

    PolicyDecision {
        accepted: reason_code == policy::POLICY_PIPELINE_ACCEPT,
        reason_code,
        audit_class: policy::policy_pipeline_audit_class_for_reason(reason_code),
        components: ComponentReasons {
            envelope_reason,
            room_epoch_reason,
            ai_grant_reason,
            ai_lifecycle_reason,
        },
    }
}

fn evaluate_ai_components(actor_kind: ActorKind, ai: Option<AiPolicyFacts>) -> (i32, i32) {
    match (actor_kind, ai) {
        (ActorKind::Human, None) => (policy::AI_GRANT_ACCEPT, policy::AI_GRANT_LIFECYCLE_ACCEPT),
        (ActorKind::Human, Some(_)) => (
            policy::AI_GRANT_BAD_PRINCIPAL_KIND,
            policy::AI_GRANT_LIFECYCLE_ACCEPT,
        ),
        (_, Some(ai)) => (
            policy::validate_ai_grant(ai.grant.into()),
            policy::validate_ai_grant_lifecycle(ai.lifecycle.into()),
        ),
        (_, None) => (
            policy::AI_GRANT_BAD_PRINCIPAL_KIND,
            policy::AI_GRANT_LIFECYCLE_ACCEPT,
        ),
    }
}
